import json

with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

for path, methods in sorted(spec.get("paths", {}).items()):
    for method, op in methods.items():
        if method.lower() not in ["get", "post", "put", "patch", "delete"]:
            continue
        op_id = op.get("operationId")
        print(f"=== {op_id}: {method.upper()} {path} ===")
        req_body = op.get("requestBody", {})
        if req_body:
            schema = req_body.get("content", {}).get("application/json", {}).get("schema", {})
            print("  Request properties:", list(schema.get("properties", {}).keys()))
            print("  Request required:", schema.get("required", []))
        for status, resp in op.get("responses", {}).items():
            content = resp.get("content", {}).get("application/json", {})
            schema = content.get("schema", {})
            if "properties" in schema and "code" in schema["properties"] and "enum" in schema["properties"]["code"]:
                print(f"  [{status}] Error codes: {schema['properties']['code']['enum']}")
            elif "properties" in schema and "data" in schema["properties"]:
                data_schema = schema["properties"]["data"]
                if "$ref" in data_schema:
                    print(f"  [{status}] Data $ref: {data_schema['$ref']}")
                elif "properties" in data_schema:
                    print(f"  [{status}] Data props: {list(data_schema['properties'].keys())}")
                else:
                    print(f"  [{status}] Data: {data_schema}")
            else:
                print(f"  [{status}] Schema keys: {list(schema.get('properties', {}).keys()) if schema else 'none'}")
EOF

