package services

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/google/uuid"
	"labsystem/internal/models"
)

func RecordAudit(db *sql.DB, actorId, role, actorRole, action, entityType, entityId string, success bool, details map[string]interface{}) {
	auditId := uuid.New().String()
	if details == nil {
		details = make(map[string]interface{})
	}
	detailsJSON, _ := json.Marshal(details)
	if role == "" {
		role = "system"
	}
	if actorRole == "" {
		actorRole = role
	}
	if actorId == "" {
		actorId = "system"
	}

	_, _ = db.Exec(`
        INSERT INTO audit_log (audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW(), $9)
    `, auditId, actorId, role, actorRole, action, entityType, entityId, success, string(detailsJSON))
}

func SearchAudit(db *sql.DB, query, actorId, entityType, entityId, action, role string, success *bool, fromTime, toTime *time.Time, limit, offset int, order string) (*models.AuditSearchResult, error) {
	if limit <= 0 {
		limit = 50
	}
	if limit > 1000 {
		limit = 1000
	}
	if offset < 0 {
		offset = 0
	}
	if order == "" || (order != "newest_first" && order != "oldest_first") {
		order = "newest_first"
	}

	var conditions []string
	var args []interface{}
	idx := 1

	if query != "" {
		conditions = append(conditions, fmt.Sprintf("(action ILIKE $%d OR entity_type ILIKE $%d OR details::text ILIKE $%d)", idx, idx, idx))
		args = append(args, "%"+query+"%")
		idx++
	}
	if actorId != "" {
		conditions = append(conditions, fmt.Sprintf("actor_id = $%d", idx))
		args = append(args, actorId)
		idx++
	}
	if entityType != "" {
		conditions = append(conditions, fmt.Sprintf("entity_type = $%d", idx))
		args = append(args, entityType)
		idx++
	}
	if entityId != "" {
		conditions = append(conditions, fmt.Sprintf("entity_id = $%d", idx))
		args = append(args, entityId)
		idx++
	}
	if action != "" {
		conditions = append(conditions, fmt.Sprintf("action = $%d", idx))
		args = append(args, action)
		idx++
	}
	if role != "" {
		conditions = append(conditions, fmt.Sprintf("(role = $%d OR actor_role = $%d)", idx, idx))
		args = append(args, role)
		idx++
	}
	if success != nil {
		conditions = append(conditions, fmt.Sprintf("success = $%d", idx))
		args = append(args, *success)
		idx++
	}
	if fromTime != nil {
		conditions = append(conditions, fmt.Sprintf("occurred_at >= $%d", idx))
		args = append(args, *fromTime)
		idx++
	}
	if toTime != nil {
		conditions = append(conditions, fmt.Sprintf("occurred_at <= $%d", idx))
		args = append(args, *toTime)
		idx++
	}

	whereClause := ""
	if len(conditions) > 0 {
		whereClause = "WHERE " + strings.Join(conditions, " AND ")
	}

	var total int
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_log %s", whereClause)
	err := db.QueryRow(countQuery, args...).Scan(&total)
	if err != nil {
		return nil, fmt.Errorf("count failed: %w", err)
	}

	orderClause := "ORDER BY occurred_at DESC, id DESC"
	if order == "oldest_first" {
		orderClause = "ORDER BY occurred_at ASC, id ASC"
	}

	dataQuery := fmt.Sprintf("SELECT audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log %s %s LIMIT $%d OFFSET $%d", whereClause, orderClause, idx, idx+1)
	args = append(args, limit, offset)

	rows, err := db.Query(dataQuery, args...)
	if err != nil {
		return nil, fmt.Errorf("query failed: %w", err)
	}
	defer rows.Close()

	entries := make([]models.AuditEntry, 0)
	for rows.Next() {
		var a models.AuditEntry
		var detailsStr string
		var occurred time.Time
		if err := rows.Scan(&a.AuditId, &a.ActorId, &a.Role, &a.ActorRole, &a.Action, &a.EntityType, &a.EntityId, &a.Success, &occurred, &detailsStr); err != nil {
			return nil, err
		}
		a.Audit_Id = a.AuditId
		a.Actor_Id = a.ActorId
		a.Entity_Type = a.EntityType
		a.Entity_Id = a.EntityId
		a.OccurredAt = occurred.Format(time.RFC3339)
		a.Occurred_At = a.OccurredAt
		_ = json.Unmarshal([]byte(detailsStr), &a.Details)
		if a.Details == nil {
			a.Details = make(map[string]interface{})
		}
		entries = append(entries, a)
	}

	returned := len(entries)
	hasMore := (offset + returned) < total
	var nextOffset *int
	if hasMore {
		no := offset + returned
		nextOffset = &no
	}

	return &models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   returned,
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}, nil
}

func GetSampleTimeline(db *sql.DB, sampleId string) ([]models.TimelineEntry, error) {
	rows, err := db.Query(`
        SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
        FROM audit_log
        WHERE entity_id = $1 OR details->>'sampleId' = $1 OR details->>'sample_id' = $1
        ORDER BY occurred_at ASC, id ASC
    `, sampleId)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	timeline := make([]models.TimelineEntry, 0)
	for rows.Next() {
		var t models.TimelineEntry
