		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleTypeNotFound
		}
		return nil, err
	}
	st.Name = name

	RecordAudit(db, actorId, actorRole, actorRole, "sample_type_updated", "sample_type", st.ID, true, map[string]interface{}{
		"name":          st.Name,
		"containerType": st.ContainerType,
	})

	return &st, nil
}

func GetSampleType(db *sql.DB, id string) (*models.SampleType, error) {
	var st models.SampleType
	err := db.QueryRow(`
        SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed, created_at, updated_at
        FROM sample_types
        WHERE id = $1
    `, id).Scan(&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &st.IncompatibleSampleTypes, &st.RequiresCooledRoute, &st.BatchingAllowed, &st.CreatedAt, &st.UpdatedAt)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleTypeNotFound
		}
		return nil, err
	}
	return &st, nil
}
