		// BFS to find paths from originNode.id to targetLab.id
		type queueItem struct {
			nodeId        string
			duration      int
			cost          float64
			pathNodes     []string
			pathConns     []string
			visitedNodes  map[string]bool
			capacityIssue bool
		}

		initVisited := map[string]bool{originNode.id: true}
		queue := []queueItem{{
			nodeId:        originNode.id,
			duration:      collectionDwell + originNode.handlingMin,
			cost:          0,
			pathNodes:     []string{originNode.id},
			pathConns:     []string{},
			visitedNodes:  initVisited,
			capacityIssue: false,
		}}

		for len(queue) > 0 {
			curr := queue[0]
			queue = queue[1:]

			if curr.nodeId == targetLab.id {
				if curr.capacityIssue {
					hadCapacityIssue = true
					continue
				}
				arrTime := collectionStartTime.Add(time.Duration(curr.duration) * time.Minute)
				if arrTime.After(deadline) {
					hadDeadlineIssue = true
					continue
				}
				route := &RoutePath{
					LabId:            targetLab.id,
					TotalDurationMin: curr.duration,
					TotalCost:        curr.cost,
					NodeIds:          curr.pathNodes,
					ConnectionIds:    curr.pathConns,
					EstimatedArrival: arrTime,
				}
				if bestRoute == nil || route.TotalDurationMin < bestRoute.TotalDurationMin {
					bestRoute = route
				}
				continue
			}

			// Explore neighbors
			for _, conn := range adj[curr.nodeId] {
				if curr.visitedNodes[conn.toId] {
					continue
				}
				nextNode, exists := nodes[conn.toId]
				if !exists || !nextNode.active {
					continue
				}
				// Intermediate nodes must be transfer_point, hub, or laboratory
				if nextNode.id != targetLab.id && !nextNode.isTrans && !nextNode.isHub && !nextNode.isLab {
					continue
				}

				capIssue := curr.capacityIssue
				// Check connection capacity & cooling
				if st.RequiresCooledRoute {
					if !conn.cooled || conn.cooledCapUnits-conn.cooledResUnits <= 0 {
						capIssue = true
					}
					if nextNode.cooledCapUnits-nextNode.cooledResUnits <= 0 {
						capIssue = true
					}
				} else {
					if conn.capUnits-conn.resUnits <= 0 {
						capIssue = true
					}
					if nextNode.capUnits-nextNode.resUnits <= 0 {
						capIssue = true
					}
				}

				newVisited := make(map[string]bool)
				for k, v := range curr.visitedNodes {
					newVisited[k] = v
				}
				newVisited[nextNode.id] = true

				newNodes := append([]string{}, curr.pathNodes...)
				newNodes = append(newNodes, nextNode.id)

				newConns := append([]string{}, curr.pathConns...)
				newConns = append(newConns, conn.id)

				queue = append(queue, queueItem{
					nodeId:        nextNode.id,
					duration:      curr.duration + conn.travelMin + nextNode.handlingMin,
					cost:          curr.cost + conn.cost,
					pathNodes:     newNodes,
					pathConns:     newConns,
					visitedNodes:  newVisited,
					capacityIssue: capIssue,
				})
			}
		}
	}

	if bestRoute != nil {
		return true, models.ReasonServiceable, &bestRoute.LabId, &bestRoute.EstimatedArrival, version, nil
	}

	if hadCapacityIssue {
		return false, models.ReasonInsufficientCapacity, nil, nil, version, nil
	}
	if hadDeadlineIssue {
		return false, models.ReasonDeadlineUnreachable, nil, nil, version, nil
	}

	return false, models.ReasonNoRoute, nil, nil, version, nil
}

func GetLatestSnapshot(db *sql.DB) (*models.ServiceabilitySnapshotData, error) {
	var snap models.ServiceabilitySnapshotData
	var regionsJSON string
	var computedAt time.Time

	err := db.QueryRow(`
        SELECT version, status, computed_at, network_revision, active_collection_point_count, regions
        FROM serviceability_snapshots
        ORDER BY version DESC
        LIMIT 1
    `).Scan(&snap.Version, &snap.Status, &computedAt, &snap.NetworkRevision, &snap.ActiveCollectionPointCount, &regionsJSON)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil
		}
		return nil, err
	}

	snap.ComputedAt = computedAt.Format(time.RFC3339)
	_ = json.Unmarshal([]byte(regionsJSON), &snap.Regions)
	if snap.Regions == nil {
		snap.Regions = []models.ServiceabilityRegion{}
	}

	return &snap, nil
}

func RecomputeAndPublishSnapshot(db *sql.DB) error {
	rows, err := db.Query(`
        SELECT id, name, latitude, longitude, coverage_km
        FROM locations
        WHERE active = true AND function_collection_point = true
    `)
	if err != nil {
		return err
	}
	defer rows.Close()

	var regions []models.ServiceabilityRegion
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationId, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return err
		}
		regions = append(regions, r)
	}

	var latestVersion int
	_ = db.QueryRow("SELECT COALESCE(MAX(version), 0) FROM serviceability_snapshots").Scan(&latestVersion)
	newVersion := latestVersion + 1

	regBytes, _ := json.Marshal(regions)
	netRev := uuid.New().String()

	_, err = db.Exec(`
        INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, active_collection_point_count, regions)
        VALUES ($1, 'published', NOW(), $2, $3, $4)
    `, newVersion, netRev, len(regions), string(regBytes))

	return err
}

