{"file_text": "package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
	"labsystem/internal/models"
)

var (
	ErrDisruptionFailed = errors.New("disruption_failed")
)

type DisruptionResult struct {
	DisruptionId        string   `json:"disruptionId"`
	AffectedSampleIds   []string `json:"affectedSampleIds"`
	ReplacementPlanIds  []string `json:"replacementPlanIds"`
	ReplanStatus        string   `json:"replanStatus"`
}

func ReportDisruption(db *sql.DB, resourceType, resourceId, reason string, occurredAt time.Time, actorId, actorRole string) (*DisruptionResult, error) {
	disruptionId := uuid.New().String()

	// 1. Deactivate resource
	switch resourceType {
	case "node", "laboratory":
		_, _ = db.Exec("UPDATE locations SET active = false, updated_at = NOW() WHERE id = $1", resourceId)
	case "connection":
		_, _ = db.Exec("UPDATE connections SET active = false, updated_at = NOW() WHERE id = $1", resourceId)
	case "worker":
		_, _ = db.Exec("UPDATE users SET available = false, updated_at = NOW() WHERE id = $1", resourceId)
	}

	_ = RecomputeAndPublishSnapshot(db)

	// 2. Find affected active journeys and samples
	var affectedSampleIds []string
	var replacementPlanIds []string
	replanStatus := "replaced"

	// Find journeys with unfinished legs using this resource
	var journeyQuery string
	switch resourceType {
	case "node", "laboratory":
		journeyQuery = `
            SELECT DISTINCT j.id, s.id
            FROM journeys j
            JOIN journey_legs l ON j.id = l.journey_id
            JOIN samples s ON l.sample_id = s.id
            WHERE j.status = 'active' AND l.status NOT IN ('completed', 'cancelled')
              AND (l.from_location_id = $1 OR l.to_location_id = $1)
        `
	case "connection":
		journeyQuery = `
            SELECT DISTINCT j.id, s.id
            FROM journeys j
            JOIN journey_legs l ON j.id = l.journey_id
            JOIN samples s ON l.sample_id = s.id
            WHERE j.status = 'active' AND l.status NOT IN ('completed', 'cancelled')
        `
	case "worker":
		journeyQuery = `
            SELECT DISTINCT j.id, s.id
            FROM journeys j
            JOIN journey_legs l ON j.id = l.journey_id
            JOIN samples s ON l.sample_id = s.id
            WHERE j.status = 'active' AND l.status NOT IN ('completed', 'cancelled')
              AND l.worker_id = $1
        `
	default:
		journeyQuery = `
            SELECT DISTINCT j.id, s.id
            FROM journeys j
            JOIN journey_legs l ON j.id = l.journey_id
            JOIN samples s ON l.sample_id = s.id
            WHERE j.status = 'active' AND l.status NOT IN ('completed', 'cancelled')
        `
	}

	rows, err := db.Query(journeyQuery, resourceId)
	if err == nil {
		defer rows.Close()
		jMap := make(map[string]bool)
		for rows.Next() {
			var jId, sId string
			if err := rows.Scan(&jId, &sId); err == nil {
				affectedSampleIds = append(affectedSampleIds, sId)
				jMap[jId] = true
			}
		}

		for jId := range jMap {
			// Increment plan version
			var curVer int
			_ = db.QueryRow("SELECT plan_version FROM journeys WHERE id = $1", jId).Scan(&curVer)
			newVer := curVer + 1

			_, _ = db.Exec(`
                UPDATE journeys
                SET plan_version = $1, replan_status = 'replaced', updated_at = NOW()
                WHERE id = $2
            `, newVer, jId)

			replacementPlanIds = append(replacementPlanIds, jId)

			// If worker was disrupted, unassign offered/pending leg and re-offer
			if resourceType == "worker" {
				var legId, kind, sId string
				lRow := db.QueryRow("SELECT id, kind, sample_id FROM journey_legs WHERE journey_id = $1 AND worker_id = $2 AND status IN ('offered', 'accepted')", jId, resourceId)
				if lRow.Scan(&legId, &kind, &sId) == nil {
					nextWorker, _ := FindEligibleWorker(db, kind, "", nil, []string{resourceId})
					if nextWorker != nil {
						_ = OfferAssignment(db, legId, nextWorker, actorId, actorRole)
					}
				}
			}
		}
	}

	if len(affectedSampleIds) == 0 {
		replanStatus = "not_required"
	}

	// Insert into disruptions
	_, _ = db.Exec(`
        INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
    `, disruptionId, resourceType, resourceId, reason, occurredAt, affectedSampleIds, replacementPlanIds, replanStatus)

	RecordAudit(db, actorId, actorRole, actorRole, "disruption_reported", "disruption", disruptionId, true, map[string]interface{}{
		"resourceType":       resourceType,
		"resourceId":         resourceId,
		"reason":             reason,
		"affectedSampleIds":  affectedSampleIds,
		"replacementPlanIds": replacementPlanIds,
	})

	BroadcastEvent(db, "disruption_reported", "disruption", disruptionId, map[string]interface{}{
		"resourceType": resourceType,
		"resourceId":   resourceId,
		"reason":       reason,
	})

	return &DisruptionResult{
		DisruptionId:       disruptionId,
		AffectedSampleIds:  affectedSampleIds,
		ReplacementPlanIds: replacementPlanIds,
		ReplanStatus:       replanStatus,
	}, nil
}
", "summary": "Create disruption service", "command": "create", "path": "/workspace/backend/internal/services/disruption_service.go"}

