	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	funcs, err := services.SetLocationFunctionStatus(h.DB, locationId, function, req.Active, user.ID, role)
	if err != nil {
		if err == services.ErrLocationNotFound {
			WriteError(w, http.StatusNotFound, "location_not_found", "Location not found")
			return
		}
		if err == services.ErrInvalidLocationFunction {
			WriteError(w, http.StatusBadRequest, "invalid_location_function", "Invalid location function")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"locationId": locationId,
		"function":   function,
		"active":     req.Active,
		"functions":  funcs,
	})
