func (h *NetworkHandlers) HandleCreateConnection(w http.ResponseWriter, r *http.Request) {
	var req models.OperationsConnection
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
