func (h *NetworkHandlers) HandleConfigureNodeCapacity(w http.ResponseWriter, r *http.Request) {
	parts := strings.Split(r.URL.Path, "/")
	var nodeId string
	for i, p := range parts {
		if p == "nodes" && i+1 < len(parts) {
			nodeId = parts[i+1]
			break
		}
	}

	var req struct {
		CapacityUnits       int  `json:"capacityUnits"`
		CooledCapacityUnits *int `json:"cooledCapacityUnits,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cooledCap, err := services.ConfigureCapacity(h.DB, nodeId, req.CapacityUnits, req.CooledCapacityUnits, user.ID, role)
	if err != nil {
		if err == services.ErrCapacityReserved {
			WriteError(w, http.StatusConflict, "capacity_reserved", "Configured capacity cannot be less than currently reserved units")
			return
		}
		if err == services.ErrInvalidCapacity {
			WriteError(w, http.StatusBadRequest, "invalid_capacity", "Capacity must be non-negative")
			return
		}
		if err == services.ErrLocationNotFound {
			WriteError(w, http.StatusNotFound, "location_not_found", "Node not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	res := map[string]interface{}{
		"nodeId":        nodeId,
		"capacityUnits": req.CapacityUnits,
	}
	if cooledCap != nil {
		res["cooledCapacityUnits"] = *cooledCap
	}
	WriteJSON(w, http.StatusOK, res)
