{"summary": "Print exact OpenAPI request and response schemas", "command": "python3 - << 'EOF'
import json

with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

for path, methods in sorted(spec.get("paths", {}).items()):
    for method, op in methods.items():
        opId = op.get("operationId", "")
        print(f"\n=======================================================")
        print(f"{method.upper()} {path} ({opId})")
        print("Summary:", op.get("summary", ""))
        rb = op.get("requestBody", {})
        if rb:
            schema = rb.get("content", {}).get("application/json", {}).get("schema", {})
            print("Request Body Schema:")
            print(json.dumps(schema, indent=2))
        print("Responses:")
        for code, resp in sorted(op.get("responses", {}).items()):
            content = resp.get("content", {}).get("application/json", {})
            if content:
                print(f"  [{code}]:", json.dumps(content.get("schema", {}), indent=4))
            else:
                print(f"  [{code}]: (empty/no json)")
EOF"}

