package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"

	"labsystem/internal/models"
	"labsystem/internal/services"
)

type AuthHandlers struct {
	DB *sql.DB
}

func (h *AuthHandlers) HandleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	user, token, activeRole, err := services.Authenticate(h.DB, req.Username, req.Password)
	if err != nil {
		WriteError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"sessionToken": token,
			"userId":       user.ID,
			"roles":        user.Roles,
			"activeRole":   activeRole,
		},
	})
}

func (h *AuthHandlers) HandleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	token := GetTokenFromContext(r)
	if token == "" {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Missing auth token")
		return
	}

	user, activeRole, err := services.SelectActiveRole(h.DB, token, req.Role)
	if err != nil {
		if err == services.ErrRoleNotHeld {
			WriteError(w, http.StatusForbidden, "role_not_held", "User does not hold the requested role")
			return
		}
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Unauthorized")
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"activeRole": activeRole,
			"roles":      user.Roles,
		},
	})
}

func (h *AuthHandlers) HandleReadUser(w http.ResponseWriter, r *http.Request) {
	parts := strings.Split(r.URL.Path, "/")
	var userId string
	if len(parts) > 0 {
		userId = parts[len(parts)-1]
	}

	if userId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "User ID is required")
		return
	}

	user, err := services.GetUser(h.DB, userId)
	if err != nil {
		if err == services.ErrUserNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "User not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         user.ID,
			"username":       user.Username,
			"email":          user.Email,
			"fullName":       user.FullName,
			"phone":          user.Phone,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

func (h *AuthHandlers) HandleCreateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              *string                `json:"email,omitempty"`
		FullName           *string                `json:"fullName,omitempty"`
		Phone              *string                `json:"phone,omitempty"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications,omitempty"`
		Certifications     []models.Certification `json:"certifications,omitempty"`
		Active             *bool                  `json:"active,omitempty"`
		AssignedLocationId *string                `json:"assignedLocationId,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Username, initialPassword and roles are required")
		return
	}

	currUser := GetUserFromContext(r)
	actorId := "system"
	actorRole := models.RoleAdministrator
	if currUser != nil {
		actorId = currUser.ID
		actorRole = GetActiveRoleFromContext(r)
	}

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	newUser := models.User{
		Username:           req.Username,
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     req.Qualifications,
		Certifications:     req.Certifications,
		Active:             active,
		AssignedLocationId: req.AssignedLocationId,
	}

	created, err := services.CreateUser(h.DB, newUser, req.InitialPassword, actorId, actorRole)
	if err != nil {
		if err == services.ErrUsernameExists {
			WriteError(w, http.StatusConflict, "username_exists", "Username already exists")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusCreated, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         created.ID,
			"username":       created.Username,
			"email":          created.Email,
			"fullName":       created.FullName,
			"phone":          created.Phone,
			"roles":          created.Roles,
			"qualifications": created.Qualifications,
			"certifications": created.Certifications,
			"active":         created.Active,
		},
	})
}

func (h *AuthHandlers) HandleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	var req struct {
		UserId             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications,omitempty"`
		Certifications     []models.Certification `json:"certifications,omitempty"`
		Active             bool                   `json:"active"`
		AssignedLocationId *string                `json:"assignedLocationId,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.UserId == "" || len(req.Roles) == 0 {
		WriteError(w, http.StatusBadRequest, "invalid_json", "UserId and roles are required")
		return
	}

	currUser := GetUserFromContext(r)
	actorId := "system"
	actorRole := models.RoleAdministrator
	if currUser != nil {
		actorId = currUser.ID
		actorRole = GetActiveRoleFromContext(r)
	}

	updated, err := services.UpdateUserAccess(h.DB, req.UserId, req.Roles, req.Qualifications, req.Certifications, req.Active, req.AssignedLocationId, actorId, actorRole)
	if err != nil {
		if err == services.ErrUserNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "User not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusCreated, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         updated.ID,
			"roles":          updated.Roles,
			"qualifications": updated.Qualifications,
			"certifications": updated.Certifications,
			"active":         updated.Active,
		},
	})
}

