func (h *AuthHandlers) HandleLogin(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	user, token, activeRole, err := services.Authenticate(h.DB, req.Username, req.Password)
	if err != nil {
		WriteError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"token":      token,
		"activeRole": activeRole,
		"user": map[string]interface{}{
			"id":             user.ID,
			"username":       user.Username,
			"fullName":       user.FullName,
			"email":          user.Email,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

func (h *AuthHandlers) HandleSelectRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	token := GetTokenFromContext(r)
	if token == "" {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Missing auth token")
		return
	}

	user, activeRole, err := services.SelectActiveRole(h.DB, token, req.Role)
	if err != nil {
		if err == services.ErrRoleNotHeld {
			WriteError(w, http.StatusForbidden, "role_not_held", "User does not hold the requested role")
			return
		}
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Unauthorized")
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"activeRole": activeRole,
		"user": map[string]interface{}{
			"id":             user.ID,
			"username":       user.Username,
			"fullName":       user.FullName,
			"email":          user.Email,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

func (h *AuthHandlers) HandleGetCurrentUser(w http.ResponseWriter, r *http.Request) {
	user := GetUserFromContext(r)
	activeRole := GetActiveRoleFromContext(r)
	if user == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Unauthorized")
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"activeRole": activeRole,
		"user": map[string]interface{}{
