	}

	updated, err := services.UpdateUserAccess(h.DB, req.UserId, req.Roles, req.Qualifications, req.Certifications, req.Active, req.AssignedLocationId, actorId, actorRole)
	if err != nil {
		if err == services.ErrUserNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "User not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
