	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"id":                         updated.ID,
		"name":                       updated.Name,
		"qualifiedCollectorRequired": updated.QualifiedCollectorRequired,
		"requiredQualification":      updated.RequiredQualification,
		"containerType":              updated.ContainerType,
		"temperatureMinC":            updated.TemperatureMinC,
		"temperatureMaxC":            updated.TemperatureMaxC,
		"incompatibleSampleTypes":    updated.IncompatibleSampleTypes,
		"requiresCooledRoute":        updated.RequiresCooledRoute,
		"batchingAllowed":            updated.BatchingAllowed,
	})
}

func (h *NetworkHandlers) HandleListSampleTypes(w http.ResponseWriter, r *http.Request) {
	rows, err := h.DB.Query(`
        SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
        FROM sample_types
        ORDER BY name ASC
    `)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()

	list := make([]map[string]interface{}, 0)
	for rows.Next() {
		var id, name, reqQual, cType string
		var qualColl, reqCooled, batchAllow bool
		var tMin, tMax float64
		var incomp []string
		if err := rows.Scan(&id, &name, &qualColl, &reqQual, &cType, &tMin, &tMax, &incomp, &reqCooled, &batchAllow); err == nil {
			list = append(list, map[string]interface{}{
				"id":                         id,
				"name":                       name,
				"qualifiedCollectorRequired": qualColl,
				"requiredQualification":      reqQual,
				"containerType":              cType,
				"temperatureMinC":            tMin,
				"temperatureMaxC":            tMax,
				"incompatibleSampleTypes":    incomp,
				"requiresCooledRoute":        reqCooled,
				"batchingAllowed":            batchAllow,
			})
		}
	}
	WriteJSON(w, http.StatusOK, list)
}

