func parseLocationFunctions(raw json.RawMessage) models.LocationFunctionStates {
	var states models.LocationFunctionStates
	// Try parsing as array of strings
	var arr []string
	if err := json.Unmarshal(raw, &arr); err == nil {
		for _, f := range arr {
			switch f {
			case models.FunctionCollectionPoint:
				states.CollectionPoint = true
			case models.FunctionTransferPoint:
				states.TransferPoint = true
			case models.FunctionHub:
				states.Hub = true
			case models.FunctionLaboratory:
				states.Laboratory = true
			}
		}
		return states
	}

	// Try parsing as struct
	_ = json.Unmarshal(raw, &states)
	return states
}

func (h *NetworkHandlers) HandleCreateLocation(w http.ResponseWriter, r *http.Request) {
	var req LocationRequestPayload
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	loc := models.Location{
