package api

import (
	"database/sql"
	"encoding/json"
	"net/http"

	"labsystem/internal/models"
	"labsystem/internal/services"
)

type NetworkHandlers struct {
	DB *sql.DB
}

type LocationRequestPayload struct {
	LocationId      string            `json:"locationId,omitempty"`
	Name            string            `json:"name"`
	Coordinate      models.Coordinate `json:"coordinate"`
	CoverageKm      float64           `json:"coverageKm"`
	HandlingMinutes int               `json:"handlingMinutes"`
	Active          *bool             `json:"active,omitempty"`
	Functions       json.RawMessage   `json:"functions"`
}

func parseLocationFunctions(raw json.RawMessage) models.LocationFunctionStates {
	var states models.LocationFunctionStates
	// Try parsing as array of strings
	var arr []string
	if err := json.Unmarshal(raw, &arr); err == nil {
		for _, f := range arr {
			switch f {
			case models.FunctionCollectionPoint:
				states.CollectionPoint = true
			case models.FunctionTransferPoint:
				states.TransferPoint = true
			case models.FunctionHub:
				states.Hub = true
			case models.FunctionLaboratory:
				states.Laboratory = true
			}
		}
		return states
	}

	// Try parsing as struct
	_ = json.Unmarshal(raw, &states)
	return states
}

func (h *NetworkHandlers) HandleCreateLocation(w http.ResponseWriter, r *http.Request) {
	var req LocationRequestPayload
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	loc := models.Location{
		LocationId:      req.LocationId,
		Name:            req.Name,
		Coordinate:      req.Coordinate,
		CoverageKm:      req.CoverageKm,
		HandlingMinutes: req.HandlingMinutes,
		Active:          active,
		Functions:       parseLocationFunctions(req.Functions),
	}

	created, err := services.CreateLocation(h.DB, loc, user.ID, role)
	if err != nil {
		switch err {
		case services.ErrInvalidCoordinate:
			WriteError(w, http.StatusBadRequest, "invalid_coordinate", "Invalid latitude or longitude")
		case services.ErrInvalidCoverage:
			WriteError(w, http.StatusBadRequest, "invalid_node_coverage", "Coverage must be between 0 and 5 km")
		case services.ErrInvalidHandlingTime:
			WriteError(w, http.StatusBadRequest, "invalid_handling_time", "Handling time must be between 0 and 1440 minutes")
		case services.ErrInvalidLocationFunction:
			WriteError(w, http.StatusBadRequest, "invalid_location_function", "At least one valid location function must be enabled")
		default:
			WriteError(w, http.StatusBadRequest, "invalid_json", err.Error())
		}
		return
	}

	WriteJSON(w, http.StatusCreated, map[string]interface{}{
		"data": created,
	})
}

func (h *NetworkHandlers) HandleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	var req LocationRequestPayload
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.LocationId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "LocationId is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	loc := models.Location{
		LocationId:      req.LocationId,
		Name:            req.Name,
		Coordinate:      req.Coordinate,
		CoverageKm:      req.CoverageKm,
		HandlingMinutes: req.HandlingMinutes,
		Functions:       parseLocationFunctions(req.Functions),
	}

	updated, err := services.UpdateLocation(h.DB, loc, user.ID, role)
	if err != nil {
		switch err {
		case services.ErrLocationNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Location not found")
		case services.ErrInvalidCoordinate:
			WriteError(w, http.StatusBadRequest, "invalid_coordinate", "Invalid latitude or longitude")
		case services.ErrInvalidCoverage:
			WriteError(w, http.StatusBadRequest, "invalid_node_coverage", "Coverage must be between 0 and 5 km")
		case services.ErrInvalidHandlingTime:
