	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		WriteError(w, http.StatusBadRequest, "invalid_origin_type", "Origin type must be home, clinic, or node")
		return
	}

