func (h *SampleHandlers) HandleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId             string  `json:"sampleId"`
		AssignmentId         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "collect_and_seal_sample")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	collTime, err := time.Parse(time.RFC3339, req.CollectedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid collectedAt format")
		return
	}

	result, err := services.CollectAndSealSample(h.DB, req.SampleId, req.AssignmentId, user.ID, req.ContainerType, req.ObservedTemperatureC, collTime, role)
	if err != nil {
		switch err {
		case services.ErrSampleNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Sample or assignment not found")
		case services.ErrIneligibleWorker:
			WriteError(w, http.StatusForbidden, "ineligible_worker", "Collector lacks required certification")
		case services.ErrInvalidTransition:
			WriteError(w, http.StatusConflict, "invalid_sample_state", "Sample is not in requested state or assignment not accepted")
		case services.ErrOutsideCollectionWindow:
			WriteError(w, http.StatusConflict, "collection_window_missed", "Collection time is outside collection window")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		}
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "collect_and_seal_sample", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
