import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"labsystem/internal/services"
)

type HandoffHandlers struct {
	DB *sql.DB
}

func (h *HandoffHandlers) HandleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId         string  `json:"sampleId"`
		FromAssignmentId *string `json:"fromAssignmentId,omitempty"`
		ToAssignmentId   *string `json:"toAssignmentId,omitempty"`
		ReceiverId       string  `json:"receiverId"`
		InitiatedAt      string  `json:"initiatedAt"`
		IdempotencyKey   string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "initiate_handoff")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	initTime, err := time.Parse(time.RFC3339, req.InitiatedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid initiatedAt format")
		return
	}

	fromAsgn := ""
	if req.FromAssignmentId != nil {
		fromAsgn = *req.FromAssignmentId
	}
	toAsgn := ""
	if req.ToAssignmentId != nil {
		toAsgn = *req.ToAssignmentId
	}

	result, err := services.InitiateHandoff(h.DB, req.SampleId, fromAsgn, toAsgn, user.ID, req.ReceiverId, initTime, role)
	if err != nil {
		switch err {
		case services.ErrSampleNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Sample not found")
		case services.ErrNotCurrentHolder:
			WriteError(w, http.StatusConflict, "custody_required", "Worker does not hold custody of this sample")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		}
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "initiate_handoff", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

func (h *HandoffHandlers) HandleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		HandoffId        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "confirm_handoff")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	confTime, err := time.Parse(time.RFC3339, req.ConfirmedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid confirmedAt format")
		return
	}

	result, err := services.ConfirmHandoff(h.DB, req.HandoffId, req.ConfirmationSide, user.ID, confTime, role)
	if err != nil {
		switch err {
		case services.ErrHandoffNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Handoff not found")
		case services.ErrHandoffPartyMismatch:
			WriteError(w, http.StatusForbidden, "forbidden", "User is not authorized to confirm this side of handoff")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		}
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "confirm_handoff", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

