package api

import (
	"database/sql"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/go-chi/chi/v5"
	chimiddleware "github.com/go-chi/chi/v5/middleware"

	"labsystem/internal/models"
)

func SetupRouter(db *sql.DB) *chi.Mux {
	r := chi.NewRouter()

	r.Use(chimiddleware.RequestID)
	r.Use(chimiddleware.RealIP)
	r.Use(chimiddleware.Logger)
	r.Use(chimiddleware.Recoverer)

	// CORS middleware
	r.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
			w.Header().Set("Access-Control-Allow-Origin", "*")
			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
			w.Header().Set("Access-Control-Allow-Headers", "Accept, Authorization, Content-Type, X-CSRF-Token, Sec-WebSocket-Protocol")
			if req.Method == "OPTIONS" {
				w.WriteHeader(http.StatusOK)
				return
			}
			next.ServeHTTP(w, req)
		})
	})

	authH := &AuthHandlers{DB: db}
	netH := &NetworkHandlers{DB: db}
	servH := &ServiceabilityHandlers{DB: db}
	sampH := &SampleHandlers{DB: db}
	handH := &HandoffHandlers{DB: db}
	workH := &WorkDispatchHandlers{DB: db}
	jourH := &JourneyHandlers{DB: db}
	audH := &AuditEventHandlers{DB: db}

	// Readiness check
	r.Get("/ready", audH.HandleReady)

	// Map assets static file server
	mapAssetsDir := "/opt/arena/map-assets"
	if _, err := os.Stat(mapAssetsDir); err == nil {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetsDir)))
		r.Handle("/map-assets/*", fs)
	}

	// Public / Unauthenticated API routes
	r.Post("/api/authenticate-user", authH.HandleAuthenticateUser)
	r.Post("/api/check-serviceability", servH.HandleCheck)
	r.Post("/api/read-serviceability-snapshot", servH.HandleReadSnapshot)

	// Authenticated API routes
	r.Group(func(authGroup chi.Router) {
		authGroup.Use(AuthMiddleware(db))

		// User & Role Context
		authGroup.Post("/api/select-active-role", authH.HandleSelectActiveRole)
		authGroup.Get("/api/read-user/{userId}", authH.HandleReadUser)
		authGroup.Get("/api/ui/bootstrap", workH.HandleBootstrap)

		// Realtime events
		authGroup.Get("/api/events", audH.HandleStreamEvents)

		// Samples & Lifecycle
		authGroup.Get("/api/read-sample-state/{sampleId}", sampH.HandleReadSampleState)
		authGroup.Post("/api/read-sample-lifecycle", sampH.HandleReadSampleLifecycle)
		authGroup.Post("/api/record-handling-checkpoint", sampH.HandleRecordHandlingCheckpoint)
		authGroup.Post("/api/record-worker-location", sampH.HandleRecordWorkerLocation)
		authGroup.Post("/api/update-assignment-progress", sampH.HandleUpdateAssignmentProgress)

		// Handoffs
		authGroup.Post("/api/initiate-handoff", handH.HandleInitiateHandoff)
		authGroup.Post("/api/confirm-handoff", handH.HandleConfirmHandoff)

		// Work & Assignments
		authGroup.Post("/api/list-role-work", workH.HandleListRoleWork)
		authGroup.Post("/api/accept-assignment", workH.HandleAcceptAssignment)
		authGroup.Post("/api/decline-assignment", workH.HandleDeclineAssignment)
		authGroup.Post("/api/set-worker-availability", workH.HandleSetWorkerAvailability)
		authGroup.Post("/api/read-journey-plan", jourH.HandleReadJourneyPlan)

		// Requester & Collector actions
		authGroup.Post("/api/create-collection-request", sampH.HandleCreateCollectionRequest)
		authGroup.Post("/api/ingest-presealed-sample", sampH.HandleIngestPresealedSample)
		authGroup.Post("/api/collect-and-seal-sample", sampH.HandleCollectAndSealSample)

		// Laboratory actions
		authGroup.Post("/api/confirm-laboratory-receipt", sampH.HandleConfirmLaboratoryReceipt)
		authGroup.Post("/api/record-laboratory-exception", sampH.HandleRecordLaboratoryException)

		// Capacity config (node handler, lab intake, dispatcher, admin)
		authGroup.Post("/api/configure-capacity", netH.HandleConfigureCapacity)

		// Dispatcher & Admin actions
		authGroup.Group(func(dispatchGroup chi.Router) {
			dispatchGroup.Use(RoleMiddleware(models.RoleDispatcher, models.RoleAdministrator))

			dispatchGroup.Post("/api/read-operations-state", workH.HandleReadOperationsState)
			dispatchGroup.Post("/api/edit-active-plan", jourH.HandleEditActivePlan)
			dispatchGroup.Post("/api/split-journey", jourH.HandleSplitJourney)
			dispatchGroup.Post("/api/merge-journeys", jourH.HandleMergeJourneys)
			dispatchGroup.Post("/api/reroute-journey", jourH.HandleRerouteJourney)
			dispatchGroup.Post("/api/cancel-journey", jourH.HandleCancelJourney)
			dispatchGroup.Post("/api/report-disruption", jourH.HandleReportDisruption)
			dispatchGroup.Post("/api/search-audit-trail", audH.HandleSearchAuditTrail)
			dispatchGroup.Post("/api/configure-laboratory-acceptance", netH.HandleConfigureLaboratoryAcceptance)
		})

		// Administrator only actions
		authGroup.Group(func(adminGroup chi.Router) {
			adminGroup.Use(RoleMiddleware(models.RoleAdministrator))

			adminGroup.Post("/api/create-user", authH.HandleCreateUser)
			adminGroup.Post("/api/update-user-access", authH.HandleUpdateUserAccess)
			adminGroup.Post("/api/create-location", netH.HandleCreateLocation)
			adminGroup.Post("/api/update-location", netH.HandleUpdateLocation)
			adminGroup.Post("/api/set-location-status", netH.HandleSetLocationStatus)
			adminGroup.Post("/api/set-location-function-status", netH.HandleSetLocationFunctionStatus)
			adminGroup.Post("/api/create-connection", netH.HandleCreateConnection)
			adminGroup.Post("/api/set-connection-status", netH.HandleSetConnectionStatus)
			adminGroup.Post("/api/create-sample-type", netH.HandleCreateSampleType)
			adminGroup.Post("/api/update-sample-type", netH.HandleUpdateSampleType)
		})
	})

	// Frontend SPA Serving
	frontendDist := "/workspace/frontend/dist"
	if _, err := os.Stat(frontendDist); err == nil {
		r.Get("/*", func(w http.ResponseWriter, req *http.Request) {
			// Don't intercept API or assets
			if strings.HasPrefix(req.URL.Path, "/api/") || strings.HasPrefix(req.URL.Path, "/map-assets/") || req.URL.Path == "/ready" {
				http.NotFound(w, req)
				return
			}
			path := filepath.Join(frontendDist, filepath.Clean(req.URL.Path))
			if info, err := os.Stat(path); err == nil && !info.IsDir() {
