package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"labsystem/internal/api"
	"labsystem/internal/db"
	"labsystem/internal/models"
	"labsystem/internal/services"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	pgURL := os.Getenv("DATABASE_URL")
	if pgURL == "" {
		pgURL = os.Getenv("POSTGRES_URL")
	}
	if pgURL == "" {
		pgURL = "postgres://postgres:postgres@127.0.0.1:5432/arena?sslmode=disable"
	}

	redisURL := os.Getenv("REDIS_URL")
	if redisURL == "" {
		redisURL = "redis://127.0.0.1:6379/0"
	}

	log.Printf("Connecting to PostgreSQL...")
	database, err := db.InitPostgres(pgURL)
	if err != nil {
		log.Fatalf("Failed to connect to PostgreSQL: %v", err)
	}
	defer database.Close()

	log.Printf("Connecting to Redis...")
	redisClient, err := db.InitRedis(redisURL)
	if err != nil {
		log.Printf("Warning: Failed to connect to Redis: %v", err)
	} else if redisClient != nil {
		defer redisClient.Close()
	}

	log.Printf("Running database migrations...")
	if err := db.RunMigrations(database); err != nil {
		log.Fatalf("Failed to run migrations: %v", err)
	}

	// Initialize initial administrator
	adminUser := os.Getenv("ADMIN_USERNAME")
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser != "" && adminPass != "" {
		initInitialAdmin(database, adminUser, adminPass)
	}

	// Publish initial serviceability snapshot if none exists
	snap, err := services.GetLatestSnapshot(database)
	if err != nil || snap == nil {
		_ = services.RecomputeAndPublishSnapshot(database)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Start background workers
	services.StartOfferExpirationWorker(ctx, database)

	router := api.SetupRouter(database)

	srv := &http.Server{
		Addr:         ":" + port,
		Handler:      router,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	go func() {
		log.Printf("Server listening on http://127.0.0.1:%s", port)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %v", err)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	log.Printf("Shutting down server...")
	cancel()

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Fatalf("Server shutdown error: %v", err)
	}
	log.Printf("Server gracefully stopped")
}

func initInitialAdmin(db *sql.DB, username, password string) {
	var count int
	err := db.QueryRow("SELECT COUNT(*) FROM users WHERE username = $1", username).Scan(&count)
