package services

import (
	"context"
	"database/sql"
	"log"
	"time"
)

func StartOfferExpirationWorker(ctx context.Context, db *sql.DB) {
	ticker := time.NewTicker(5 * time.Second)
	go func() {
		for {
			select {
			case <-ctx.Done():
				ticker.Stop()
				return
			case <-ticker.C:
				processExpiredOffers(db)
			}
		}
	}()
}

func processExpiredOffers(db *sql.DB) {
	now := time.Now()
	rows, err := db.Query(`
        SELECT jl.id, jl.journey_id, jl.worker_id, jl.kind, jl.from_location_id, jl.to_location_id, jl.sample_id
        FROM journey_legs jl
        WHERE jl.status = 'offered' AND jl.offer_expires_at IS NOT NULL AND jl.offer_expires_at < $1
    `, now)
	if err != nil {
		return
	}
	defer rows.Close()

	type ExpiredOffer struct {
		AssignmentId string
		JourneyId    string
		WorkerId     string
		Kind         string
		FromLoc      *string
		ToLoc        *string
		SampleId     *string
	}

	expired := make([]ExpiredOffer, 0)
	for rows.Next() {
		var o ExpiredOffer
		var wId, sampId *string
		if err := rows.Scan(&o.AssignmentId, &o.JourneyId, &wId, &o.Kind, &o.FromLoc, &o.ToLoc, &sampId); err == nil {
			if wId != nil {
				o.WorkerId = *wId
			}
			o.SampleId = sampId
			expired = append(expired, o)
		}
	}

	for _, o := range expired {
		log.Printf("[Worker] Processing expired offer for assignment %s (worker: %s)", o.AssignmentId, o.WorkerId)
		if o.WorkerId != "" {
			_, _ = DeclineAssignment(db, o.AssignmentId, o.WorkerId, "offer_timed_out", now, "system")
		}
	}
}

