package services

import (
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"labsystem/internal/models"
)

var (
	ErrJourneyNotFound     = errors.New("not_found")
	ErrVersionConflict     = errors.New("version_conflict")
	ErrInvalidPlanChange   = errors.New("invalid_plan_change")
	ErrIncompatibleBatch   = errors.New("incompatible_batch")
	ErrCapacityOverbooked  = errors.New("capacity_reserved")
)

func CreateJourneyForSample(db *sql.DB, sampleId string, origin models.Coordinate, originType, originNodeId, sampleTypeId string, requestedAt, deadline, earliest, latest time.Time, actorId, actorRole string) (*models.JourneyPlan, error) {
	serviceable, reason, labIdPtr, estArrPtr, _, err := CheckServiceability(db, origin, originType, originNodeId, sampleTypeId, requestedAt, deadline, earliest, latest)
	if err != nil {
		return nil, err
	}
	if !serviceable || labIdPtr == nil {
		return nil, fmt.Errorf("sample is not serviceable: %s", reason)
	}

	st, err := GetSampleType(db, sampleTypeId)
	if err != nil {
		return nil, err
	}

	labId := *labIdPtr
	estArr := *estArrPtr

	journeyId := uuid.New().String()
	startTime := requestedAt
	if !earliest.IsZero() {
		startTime = earliest
	}

	// 1. Determine origin node
	var origNodeId string
	if originNodeId != "" {
		origNodeId = originNodeId
	} else {
		// Find closest active collection node
		_ = db.QueryRow(`
            SELECT id FROM locations
            WHERE active = true AND function_collection_point = true
            ORDER BY (latitude - $1)^2 + (longitude - $2)^2 ASC
            LIMIT 1
        `, origin.Latitude, origin.Longitude).Scan(&origNodeId)
	}

	// Insert journey
	_, err = db.Exec(`
        INSERT INTO journeys (id, plan_version, route_mode, status, replan_status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, valid)
        VALUES ($1, 1, 'direct', 'active', 'not_required', $2, 10.0, 1, 10, $3, true)
    `, journeyId, estArr, []string{sampleId})
	if err != nil {
		return nil, err
	}

	// Create Stops & Legs
	seq := 1
	var legs []models.JourneyLeg
	var stops []models.JourneyStop

	// If origin is home/clinic and separate from node -> Collection Stop & Leg
	if originType == "home" || origNodeId == "" {
		// Stop 1: Collection at Home
		homeStopId := uuid.New().String()
		homeTime := startTime.Add(15 * time.Minute)
		_, _ = db.Exec(`
            INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
            VALUES ($1, $2, $3, 'pickup', $4, $5, 15, $6, $7)
        `, homeStopId, journeyId, origNodeId, seq, homeTime, origin.Latitude, origin.Longitude)
		stops = append(stops, models.JourneyStop{
			StopId:      homeStopId,
			LocationId:  origNodeId,
			StopType:    models.StopTypePickup,
			Sequence:    seq,
			EstimatedAt: homeTime.Format(time.RFC3339),
			Coordinate:  &origin,
		})
		seq++

		// Collection Leg
		collLegId := uuid.New().String()
		_, _ = db.Exec(`
            INSERT INTO journey_legs (id, journey_id, sequence, status, from_location_id, to_location_id, sample_id, kind)
            VALUES ($1, $2, 1, 'pending', $3, $3, $4, 'collection')
        `, collLegId, journeyId, origNodeId, sampleId)
		legs = append(legs, models.JourneyLeg{
			AssignmentId: collLegId,
			Sequence:     1,
			Status:       "pending",
			FromLocationId: &origNodeId,
			ToLocationId:   &origNodeId,
			SampleId:       &sampleId,
		})

		// Try assigning collection worker
		worker, _ := FindEligibleWorker(db, "collection", sampleTypeId, nil, nil)
		if worker != nil {
			_ = OfferAssignment(db, collLegId, worker, actorId, actorRole)
			legs[0].WorkerId = &worker.ID
			legs[0].Status = "offered"
		}
	}

	// Intermediate / Node Leg & Lab Leg
	if origNodeId != labId {
		// Stop 2: Origin Node Dropoff / Handoff
		nodeStopId := uuid.New().String()
		nodeTime := startTime.Add(35 * time.Minute)
		_, _ = db.Exec(`
            INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
            VALUES ($1, $2, $3, 'handoff', $4, $5, 10)
        `, nodeStopId, journeyId, origNodeId, seq, nodeTime)
		stops = append(stops, models.JourneyStop{
			StopId:      nodeStopId,
			LocationId:  origNodeId,
			StopType:    models.StopTypeHandoff,
			Sequence:    seq,
			EstimatedAt: nodeTime.Format(time.RFC3339),
		})
		seq++

		// Transport Leg (origNode -> lab)
		transLegId := uuid.New().String()
		_, _ = db.Exec(`
            INSERT INTO journey_legs (id, journey_id, sequence, status, from_location_id, to_location_id, sample_id, kind)
            VALUES ($1, $2, $3, 'pending', $4, $5, $6, 'transport')
        `, transLegId, journeyId, len(legs)+1, origNodeId, labId, sampleId)
		legs = append(legs, models.JourneyLeg{
			AssignmentId: transLegId,
			Sequence:     len(legs) + 1,
			Status:       "pending",
			FromLocationId: &origNodeId,
			ToLocationId:   &labId,
			SampleId:       &sampleId,
		})

		// Reserve capacity on node and destination lab
		if st.RequiresCooledRoute {
			_, _ = db.Exec("UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id IN ($1, $2)", origNodeId, labId)
			_, _ = db.Exec("INSERT INTO capacity_reservations (journey_id, resource_type, resource_id, units, cooled) VALUES ($1, 'location', $2, 1, true), ($1, 'location', $3, 1, true)", journeyId, origNodeId, labId)
		} else {
			_, _ = db.Exec("UPDATE locations SET reserved_units = reserved_units + 1 WHERE id IN ($1, $2)", origNodeId, labId)
			_, _ = db.Exec("INSERT INTO capacity_reservations (journey_id, resource_type, resource_id, units, cooled) VALUES ($1, 'location', $2, 1, false), ($1, 'location', $3, 1, false)", journeyId, origNodeId, labId)
		}
	} else {
		// Origin node IS lab
		if st.RequiresCooledRoute {
			_, _ = db.Exec("UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id = $1", labId)
			_, _ = db.Exec("INSERT INTO capacity_reservations (journey_id, resource_type, resource_id, units, cooled) VALUES ($1, 'location', $2, 1, true)", journeyId, labId)
		} else {
			_, _ = db.Exec("UPDATE locations SET reserved_units = reserved_units + 1 WHERE id = $1", labId)
			_, _ = db.Exec("INSERT INTO capacity_reservations (journey_id, resource_type, resource_id, units, cooled) VALUES ($1, 'location', $2, 1, false)", journeyId, labId)
		}
	}

	// Final Stop: Laboratory Delivery
	labStopId := uuid.New().String()
	_, _ = db.Exec(`
        INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
        VALUES ($1, $2, $3, 'delivery', $4, $5, 15)
    `, labStopId, journeyId, labId, seq, estArr)
	stops = append(stops, models.JourneyStop{
		StopId:      labStopId,
		LocationId:  labId,
		StopType:    models.StopTypeDelivery,
		Sequence:    seq,
		EstimatedAt: estArr.Format(time.RFC3339),
	})

	// Lab Intake Leg
	labLegId := uuid.New().String()
	_, _ = db.Exec(`
        INSERT INTO journey_legs (id, journey_id, sequence, status, from_location_id, to_location_id, sample_id, kind)
        VALUES ($1, $2, $3, 'pending', $4, $4, $5, 'laboratory')
    `, labLegId, journeyId, len(legs)+1, labId, sampleId)
	legs = append(legs, models.JourneyLeg{
		AssignmentId: labLegId,
		Sequence:     len(legs) + 1,
		Status:       "pending",
		FromLocationId: &labId,
		ToLocationId:   &labId,
		SampleId:       &sampleId,
	})

	// Link sample to journey
	_, _ = db.Exec("UPDATE samples SET active_journey_id = $1, target_laboratory_id = $2 WHERE id = $3", journeyId, labId, sampleId)

	var estDeliveryStr *string
	if estArrPtr != nil {
		s := estArrPtr.Format(time.RFC3339)
		estDeliveryStr = &s
	}

	plan := &models.JourneyPlan{
		JourneyId:           journeyId,
		PlanVersion:         1,
		RouteMode:           models.RouteModeDirect,
		Status:              "active",
		EstimatedDeliveryAt: estDeliveryStr,
		SampleIds:           []string{sampleId},
		OrderedStops:        stops,
		Legs:                legs,
	}

	RecordAudit(db, actorId, actorRole, actorRole, "journey_created", "journey", journeyId, true, map[string]interface{}{
		"sampleId": sampleId,
		"labId":    labId,
	})

	return plan, nil
}

func GetJourneyPlan(db *sql.DB, journeyId string) (*models.JourneyPlan, error) {
	var p models.JourneyPlan
	var parentId sql.NullString
	var estDel sql.NullTime
	var cost sql.NullFloat64
	var capUsed, capAvail sql.NullInt32
	var replanStat sql.NullString
	var valid sql.NullBool

	err := db.QueryRow(`
        SELECT id, parent_journey_id, plan_version, route_mode, status, replan_status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, valid
        FROM journeys
        WHERE id = $1
    `, journeyId).Scan(&p.JourneyId, &parentId, &p.PlanVersion, &p.RouteMode, &p.Status, &replanStat, &estDel, &cost, &capUsed, &capAvail, &p.SampleIds, &valid)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrJourneyNotFound
		}
		return nil, err
	}

	if parentId.Valid {
		p.ParentJourneyId = &parentId.String
	}
	if estDel.Valid {
		formatted := estDel.Time.Format(time.RFC3339)
		p.EstimatedDeliveryAt = &formatted
	}
	if cost.Valid {
		p.TotalCostUnits = &cost.Float64
	}
	if capUsed.Valid {
		val := int(capUsed.Int32)
		p.CapacityUsed = &val
	}
	if capAvail.Valid {
		val := int(capAvail.Int32)
		p.CapacityAvailable = &val
	}
	if replanStat.Valid {
		p.ReplanStatus = &replanStat.String
	}
	if valid.Valid {
		p.Valid = &valid.Bool
	}

	// Fetch stops
	sRows, err := db.Query(`
        SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
        FROM journey_stops
        WHERE journey_id = $1
        ORDER BY sequence ASC
    `, journeyId)
	if err == nil {
		defer sRows.Close()
		p.OrderedStops = make([]models.JourneyStop, 0)
		for sRows.Next() {
			var s models.JourneyStop
			var estAt time.Time
			var dwell sql.NullInt32
			var lat, lng sql.NullFloat64
			var compAt sql.NullTime
			if err := sRows.Scan(&s.StopId, &s.LocationId, &s.StopType, &s.Sequence, &estAt, &dwell, &lat, &lng, &compAt); err == nil {
				s.Location_Id = s.LocationId
				s.Stop_Type = s.StopType
				s.EstimatedAt = estAt.Format(time.RFC3339)
				s.Estimated_At = s.EstimatedAt
				if dwell.Valid {
					dw := int(dwell.Int32)
					s.DwellMinutes = &dw
				}
				if lat.Valid && lng.Valid {
					s.Coordinate = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
				}
				if compAt.Valid {
					c := compAt.Time.Format(time.RFC3339)
					s.CompletedAt = &c
				}
				p.OrderedStops = append(p.OrderedStops, s)
			}
		}
	}

	// Fetch legs
	lRows, err := db.Query(`
        SELECT id, sequence, status, from_location_id, to_location_id, worker_id, sample_id, kind
        FROM journey_legs
        WHERE journey_id = $1
        ORDER BY sequence ASC
    `, journeyId)
	if err == nil {
		defer lRows.Close()
		p.Legs = make([]models.JourneyLeg, 0)
		for lRows.Next() {
			var l models.JourneyLeg
			var fromLoc, toLoc, wId, sId, kind sql.NullString
			if err := lRows.Scan(&l.AssignmentId, &l.Sequence, &l.Status, &fromLoc, &toLoc, &wId, &sId, &kind); err == nil {
				l.Assignment_Id = l.AssignmentId
				if fromLoc.Valid {
					l.FromLocationId = &fromLoc.String
					l.From_Location_Id = &fromLoc.String
				}
				if toLoc.Valid {
					l.ToLocationId = &toLoc.String
					l.To_Location_Id = &toLoc.String
				}
				if wId.Valid {
					l.WorkerId = &wId.String
					l.Worker_Id = &wId.String
					p.AssignedWorkerIds = append(p.AssignedWorkerIds, wId.String)
				}
				if sId.Valid {
					l.SampleId = &sId.String
				}

				if kind.String == "collection" {
					p.CollectionAssignmentId = &l.AssignmentId
					p.CollectionAssignmentIds = append(p.CollectionAssignmentIds, l.AssignmentId)
				} else if kind.String == "node" {
					p.NodeAssignmentIds = append(p.NodeAssignmentIds, l.AssignmentId)
				} else if kind.String == "laboratory" {
					p.LaboratoryAssignmentIds = append(p.LaboratoryAssignmentIds, l.AssignmentId)
				} else if kind.String == "transport" {
					if p.FirstTransportAssignmentId == nil {
						p.FirstTransportAssignmentId = &l.AssignmentId
					}
					p.FinalTransportAssignmentId = &l.AssignmentId
				}
				p.Legs = append(p.Legs, l)
			}
		}
	}

	return &p, nil
}

func EditActivePlan(db *sql.DB, journeyId string, expectedVersion int, changeType string, changes map[string]interface{}, actorId, actorRole string) (*models.JourneyPlan, error) {
	plan, err := GetJourneyPlan(db, journeyId)
	if err != nil {
		return nil, err
	}

	if plan.PlanVersion != expectedVersion {
		return nil, ErrVersionConflict
	}

	newVersion := expectedVersion + 1
	_, err = db.Exec(`
        UPDATE journeys
        SET plan_version = $1, updated_at = NOW()
        WHERE id = $2
    `, newVersion, journeyId)
	if err != nil {
		return nil, err
	}

	RecordAudit(db, actorId, actorRole, actorRole, "journey_plan_edited", "journey", journeyId, true, map[string]interface{}{
		"changeType":      changeType,
		"previousVersion": expectedVersion,
		"newVersion":      newVersion,
	})

	return GetJourneyPlan(db, journeyId)
}

func SplitJourney(db *sql.DB, journeyId string, expectedVersion int, sampleIds []string, actorId, actorRole string) (*models.JourneyPlan, *models.JourneyPlan, error) {
	plan, err := GetJourneyPlan(db, journeyId)
	if err != nil {
		return nil, nil, err
	}
	if plan.PlanVersion != expectedVersion {
		return nil, nil, ErrVersionConflict
	}

	// Validate sample IDs belong to journey
	splitSampleMap := make(map[string]bool)
	for _, s := range sampleIds {
		splitSampleMap[s] = true
	}

	remainingSamples := make([]string, 0)
	for _, s := range plan.SampleIds {
		if !splitSampleMap[s] {
			remainingSamples = append(remainingSamples, s)
		}
	}

	if len(remainingSamples) == 0 || len(splitSampleMap) == 0 {
		return nil, nil, ErrInvalidPlanChange
	}

	splitJourneyId := uuid.New().String()
	newVersion := expectedVersion + 1

	// Update original journey
	_, err = db.Exec(`
        UPDATE journeys
        SET plan_version = $1, sample_ids = $2, updated_at = NOW()
        WHERE id = $3
    `, newVersion, remainingSamples, journeyId)
	if err != nil {
		return nil, nil, err
	}

	// Create split journey
	_, err = db.Exec(`
        INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, replan_status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, valid)
        VALUES ($1, $2, 1, $3, 'active', 'not_required', $4, 10.0, $5, 10, $6, true)
    `, splitJourneyId, journeyId, plan.RouteMode, plan.EstimatedDeliveryAt, len(sampleIds), sampleIds)
	if err != nil {
		return nil, nil, err
	}

	// Update active_journey_id on split samples
	for _, s := range sampleIds {
		_, _ = db.Exec("UPDATE samples SET active_journey_id = $1 WHERE id = $2", splitJourneyId, s)
	}

	RecordAudit(db, actorId, actorRole, actorRole, "journey_split", "journey", journeyId, true, map[string]interface{}{
		"splitJourneyId":   splitJourneyId,
		"splitSampleIds":   sampleIds,
		"remainingSamples": remainingSamples,
	})

	origUpdated, _ := GetJourneyPlan(db, journeyId)
	splitPlan, _ := GetJourneyPlan(db, splitJourneyId)
	return origUpdated, splitPlan, nil
}

func MergeJourneys(db *sql.DB, targetJourneyId string, expectedVersion int, sourceJourneyIds []string, actorId, actorRole string) (*models.JourneyPlan, error) {
	targetPlan, err := GetJourneyPlan(db, targetJourneyId)
	if err != nil {
		return nil, err
	}
	if targetPlan.PlanVersion != expectedVersion {
		return nil, ErrVersionConflict
	}

	allSampleIds := append([]string{}, targetPlan.SampleIds...)

	for _, sId := range sourceJourneyIds {
		sPlan, err := GetJourneyPlan(db, sId)
		if err != nil {
			return nil, err
		}
		allSampleIds = append(allSampleIds, sPlan.SampleIds...)
	}

	// Verify batch compatibility
	var sampleTypes []models.SampleType
	for _, sampId := range allSampleIds {
		var stId string
		_ = db.QueryRow("SELECT sample_type_id FROM samples WHERE id = $1", sampId).Scan(&stId)
		st, _ := GetSampleType(db, stId)
		if st != nil {
			if !st.BatchingAllowed {
				return nil, ErrIncompatibleBatch // e.g. Pulse cannot be batched
			}
			sampleTypes = append(sampleTypes, *st)
		}
	}

	// Check incompatible sample types pairs
	for i := 0; i < len(sampleTypes); i++ {
		for j := i + 1; j < len(sampleTypes); j++ {
			for _, incomp := range sampleTypes[i].IncompatibleSampleTypes {
				if incomp == sampleTypes[j].ID || incomp == sampleTypes[j].Name {
					return nil, ErrIncompatibleBatch
				}
			}
			for _, incomp := range sampleTypes[j].IncompatibleSampleTypes {
				if incomp == sampleTypes[i].ID || incomp == sampleTypes[i].Name {
					return nil, ErrIncompatibleBatch
				}
			}
		}
	}

	newVersion := expectedVersion + 1
	_, err = db.Exec(`
        UPDATE journeys
        SET plan_version = $1, route_mode = 'batched', sample_ids = $2, capacity_used = $3, updated_at = NOW()
        WHERE id = $4
    `, newVersion, allSampleIds, len(allSampleIds), targetJourneyId)
	if err != nil {
		return nil, err
	}

	for _, sId := range sourceJourneyIds {
		_, _ = db.Exec("UPDATE journeys SET status = 'merged', updated_at = NOW() WHERE id = $1", sId)
	}

	for _, sampId := range allSampleIds {
		_, _ = db.Exec("UPDATE samples SET active_journey_id = $1 WHERE id = $2", targetJourneyId, sampId)
	}

	RecordAudit(db, actorId, actorRole, actorRole, "journeys_merged", "journey", targetJourneyId, true, map[string]interface{}{
		"sourceJourneyIds": sourceJourneyIds,
		"allSampleIds":     allSampleIds,
	})

	return GetJourneyPlan(db, targetJourneyId)
}

func RerouteJourney(db *sql.DB, journeyId string, expectedVersion int, reason string, actorId, actorRole string) (string, string, *models.JourneyPlan, error) {
	plan, err := GetJourneyPlan(db, journeyId)
	if err != nil {
		return "", "", nil, err
	}
	if plan.PlanVersion != expectedVersion {
		return "", "", nil, ErrVersionConflict
	}

	newVersion := expectedVersion + 1
	_, _ = db.Exec(`
        UPDATE journeys
        SET plan_version = $1, replan_status = 'replaced', updated_at = NOW()
        WHERE id = $2
    `, newVersion, journeyId)

	RecordAudit(db, actorId, actorRole, actorRole, "journey_rerouted", "journey", journeyId, true, map[string]interface{}{
		"reason": reason,
	})

	updatedPlan, _ := GetJourneyPlan(db, journeyId)
	return journeyId, "replaced", updatedPlan, nil
}

func CancelJourney(db *sql.DB, journeyId string, expectedVersion int, reason string, actorId, actorRole string) error {
	plan, err := GetJourneyPlan(db, journeyId)
	if err != nil {
		return err
	}
	if plan.PlanVersion != expectedVersion {
		return ErrVersionConflict
	}

	_, _ = db.Exec(`
        UPDATE journeys
        SET status = 'cancelled', updated_at = NOW()
        WHERE id = $1
    `, journeyId)

	_, _ = db.Exec(`
        UPDATE journey_legs
        SET status = 'cancelled', updated_at = NOW()
        WHERE journey_id = $1 AND status NOT IN ('completed')
    `, journeyId)

	// Release reservations
	_, _ = db.Exec("UPDATE capacity_reservations SET active = false WHERE journey_id = $1", journeyId)

	RecordAudit(db, actorId, actorRole, actorRole, "journey_cancelled", "journey", journeyId, true, map[string]interface{}{
		"reason": reason,
	})

	return nil
}

