var (
	ErrLocationNotFound         = errors.New("location_not_found")
	ErrConnectionNotFound       = errors.New("connection_not_found")
	ErrSampleTypeNotFound       = errors.New("sample_type_not_found")
	ErrInvalidCoordinate        = errors.New("invalid_coordinate")
	ErrInvalidCoverage          = errors.New("invalid_node_coverage")
	ErrInvalidHandlingTime      = errors.New("invalid_handling_time")
	ErrInvalidLocationFunction  = errors.New("invalid_location_function")
	ErrCapacityReserved         = errors.New("capacity_reserved")
	ErrInvalidCapacity         = errors.New("invalid_capacity")
