package services

import (
	"database/sql"
	"errors"
)

var (
	ErrIdempotencyConflict = errors.New("idempotency_conflict")
)

func CheckIdempotency(db *sql.DB, key, userId, operation string) (bool, string, error) {
	if key == "" {
		return false, "", nil
	}
	var responseBody string
	err := db.QueryRow(`
        SELECT response_body FROM idempotency_keys
        WHERE key = $1 AND user_id = $2 AND operation = $3
    `, key, userId, operation).Scan(&responseBody)
	if err == nil {
		return true, responseBody, nil
	}
	if errors.Is(err, sql.ErrNoRows) {
		return false, "", nil
	}
	return false, "", err
}

func SaveIdempotency(db *sql.DB, key, userId, operation, responseBody string) {
	if key == "" {
		return
	}
	_, _ = db.Exec(`
        INSERT INTO idempotency_keys (key, user_id, operation, response_body, created_at)
        VALUES ($1, $2, $3, $4, NOW())
        ON CONFLICT (key, user_id, operation) DO NOTHING
    `, key, userId, operation, responseBody)
}

