		limit = 500
	}

	rows, err := db.Query(`
        SELECT id, type, entity_type, entity_id, payload, created_at
        FROM realtime_events
        WHERE id > $1
        ORDER BY id ASC
        LIMIT $2
    `, sinceID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	events := make([]models.RealtimeEvent, 0)
	for rows.Next() {
