		a.OccurredAt = occurred.Format(time.RFC3339)
		a.Occurred_At = a.OccurredAt
		_ = json.Unmarshal([]byte(detailsStr), &a.Details)
		if a.Details == nil {
			a.Details = make(map[string]interface{})
		}
		entries = append(entries, a)
	}

	returned := len(entries)
	hasMore := (offset + returned) < total
	var nextOffset *int
	if hasMore {
		no := offset + returned
		nextOffset = &no
	}

	return &models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   returned,
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}, nil
}

func GetSampleTimeline(db *sql.DB, sampleId string) ([]models.TimelineEntry, error) {
	rows, err := db.Query(`
        SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
        FROM audit_log
        WHERE entity_id = $1 OR details->>'sampleId' = $1 OR details->>'sample_id' = $1
        ORDER BY occurred_at ASC, id ASC
    `, sampleId)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	timeline := make([]models.TimelineEntry, 0)
	for rows.Next() {
		var t models.TimelineEntry
		var detailsStr string
		var occurred time.Time
		if err := rows.Scan(&t.EventId, &t.Action, &t.ActorId, &t.Role, &t.EntityType, &t.EntityId, &t.Success, &occurred, &detailsStr); err != nil {
			return nil, err
		}
		t.OccurredAt = occurred.Format(time.RFC3339)
		_ = json.Unmarshal([]byte(detailsStr), &t.Details)
		if t.Details == nil {
			t.Details = make(map[string]interface{})
		}
		timeline = append(timeline, t)
	}
	return timeline, nil
}

