			case <-ticker.C:
				events, maxCursor, err := services.GetEventsSince(h.DB, currentCursor)
				if err == nil && len(events) > 0 {
					currentCursor = maxCursor
					for _, ev := range events {
						data, _ := json.Marshal(ev)
						fmt.Fprintf(w, "data: %s\n\n", string(data))
					}
					flusher.Flush()
				}
			}
		}
	}

	// Regular JSON response
	events, maxCursor, err := services.GetEventsSince(h.DB, since)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if events == nil {
		events = []models.RealtimeEvent{}
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"events": events,
			"cursor": maxCursor,
		},
	})
}

func (h *AuditEventHandlers) HandleReady(w http.ResponseWriter, r *http.Request) {
	err := h.DB.Ping()
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusServiceUnavailable)
		json.NewEncoder(w).Encode(map[string]string{"status": "starting"})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "ready"})
}

