		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Invalid deliveryDeadline format")
		return
	}

	if deadTime.Before(reqTime) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Delivery deadline must be after requested time")
		return
	}

	var earliest, latest *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid earliestCollectionAt format")
			return
		}
		earliest = &t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
