package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"labsystem/internal/services"
)

type JourneyHandlers struct {
	DB *sql.DB
}

func (h *JourneyHandlers) HandleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyId string `json:"journeyId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.JourneyId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "JourneyId is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	plan, err := services.GetJourneyPlan(h.DB, req.JourneyId)
	if err != nil {
		if err == services.ErrJourneyNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Journey not found")
			return
		}
		if err == services.ErrForbidden {
			WriteError(w, http.StatusForbidden, "forbidden", "Forbidden")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": plan,
	})
}

func (h *JourneyHandlers) HandleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyId           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "edit_active_plan")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	plan, err := services.EditActivePlan(h.DB, req.JourneyId, req.ExpectedPlanVersion, req.ChangeType, req.Changes, user.ID, role)
	if err != nil {
		switch err {
		case services.ErrJourneyNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Journey not found")
		case services.ErrStalePlanVersion:
			WriteError(w, http.StatusConflict, "stale_plan", "Plan version does not match expected version")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		}
		return
	}

	resp := map[string]interface{}{
		"data": plan,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "edit_active_plan", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

func (h *JourneyHandlers) HandleSplitJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyId           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIds           []string `json:"sampleIds"`
