		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	j1, j2, err := services.SplitJourney(h.DB, req.JourneyId, req.ExpectedPlanVersion, req.SampleIds, user.ID, role)
	if err != nil {
		switch err {
		case services.ErrJourneyNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Journey not found")
		case services.ErrStalePlanVersion:
			WriteError(w, http.StatusConflict, "stale_plan", "Plan version does not match expected version")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
