	}

	occTime, err := time.Parse(time.RFC3339, req.OccurredAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid occurredAt format")
		return
	}

	result, err := services.ReportDisruption(h.DB, req.ResourceType, req.ResourceId, req.Reason, occTime, user.ID, role)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "report_disruption", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

