func CollectAndSealSample(db *sql.DB, sampleId, assignmentId, collectorId, containerType string, temp float64, collectedAt time.Time, actorId, actorRole string) (*models.SampleLifecycle, error) {
	var stId string
	err := db.QueryRow("SELECT sample_type_id FROM samples WHERE id = $1", sampleId).Scan(&stId)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleNotFound
		}
		return nil, err
	}

	st, err := GetSampleType(db, stId)
	if err != nil {
		return nil, err
	}

	// Validate handling compliance
	compliant := true
	if (containerType != "" && containerType != st.ContainerType) || temp < st.TemperatureMinC || temp > st.TemperatureMaxC {
		compliant = false
	}

	status := "collected"
	var excJSON []byte
	if !compliant {
		status = "exception"
		excMap := map[string]interface{}{
			"type":        "temperature_or_container_breach",
			"observed":    temp,
			"minAllowed":  st.TemperatureMinC,
			"maxAllowed":  st.TemperatureMaxC,
			"container":   containerType,
			"requiredCon": st.ContainerType,
			"time":        collectedAt.Format(time.RFC3339),
		}
		excJSON, _ = json.Marshal(excMap)
	}

	if excJSON != nil {
		_, err = db.Exec(`
            UPDATE samples
            SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3, handling_compliant = $4, exception = $5, updated_at = NOW()
            WHERE id = $6
        `, status, collectedAt, collectorId, compliant, string(excJSON), sampleId)
	} else {
		_, err = db.Exec(`
            UPDATE samples
            SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3, handling_compliant = $4, updated_at = NOW()
            WHERE id = $5
        `, status, collectedAt, collectorId, compliant, sampleId)
	}
	if err != nil {
		return nil, err
	}

	// Record Checkpoint
	_, _ = db.Exec(`
        INSERT INTO handling_checkpoints (id, sample_id, assignment_id, actor_id, container_type, observed_temperature_c, compliant, sample_status, recorded_at)
        VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7, $8)
    `, sampleId, assignmentId, collectorId, containerType, temp, compliant, status, collectedAt)

	// Complete collection leg
	_, _ = db.Exec(`
        UPDATE journey_legs
        SET status = 'completed', completed_at = $1, updated_at = NOW()
        WHERE id = $2
    `, collectedAt, assignmentId)

	RecordAudit(db, actorId, actorRole, actorRole, "sample_collected_and_sealed", "sample", sampleId, true, map[string]interface{}{
		"assignmentId": assignmentId,
		"collectorId":  collectorId,
		"temperature":  temp,
		"compliant":    compliant,
	})

	BroadcastEvent(db, "sample_collected", "sample", sampleId, map[string]interface{}{
		"collectorId": collectorId,
		"status":      status,
		"compliant":   compliant,
	})

	return GetSampleLifecycle(db, sampleId)
}

func RecordHandlingCheckpoint(db *sql.DB, sampleId, assignmentId, actorId string, locationId *string, containerType string, temp float64, recordedAt time.Time, role string) (bool, string, error) {
	var stId string
	err := db.QueryRow("SELECT sample_type_id FROM samples WHERE id = $1", sampleId).Scan(&stId)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return false, "", ErrSampleNotFound
		}
		return false, "", err
	}

	st, err := GetSampleType(db, stId)
	if err != nil {
		return false, "", err
	}

	compliant := true
	if (containerType != "" && containerType != st.ContainerType) || temp < st.TemperatureMinC || temp > st.TemperatureMaxC {
		compliant = false
	}

	status := "in_transit"
	if !compliant {
		status = "exception"
		excMap := map[string]interface{}{
			"type":       "checkpoint_temperature_breach",
			"observed":   temp,
			"minAllowed": st.TemperatureMinC,
			"maxAllowed": st.TemperatureMaxC,
			"time":       recordedAt.Format(time.RFC3339),
		}
		excJSON, _ := json.Marshal(excMap)
		_, _ = db.Exec(`
            UPDATE samples
            SET status = 'exception', handling_compliant = false, exception = $1, updated_at = NOW()
            WHERE id = $2
        `, string(excJSON), sampleId)
	}

	_, _ = db.Exec(`
        INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, actor_id, container_type, observed_temperature_c, compliant, sample_status, recorded_at)
        VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7, $8, $9)
    `, sampleId, assignmentId, locationId, actorId, containerType, temp, compliant, status, recordedAt)

	RecordAudit(db, actorId, role, role, "checkpoint_recorded", "sample", sampleId, true, map[string]interface{}{
		"temperature": temp,
		"compliant":   compliant,
	})

	return compliant, status, nil
}

func ConfirmLaboratoryReceipt(db *sql.DB, sampleId, labId, operatorId string, receivedAt time.Time, actorId, actorRole string) (*models.SampleLifecycle, error) {
	var jId sql.NullString
	err := db.QueryRow("SELECT active_journey_id FROM samples WHERE id = $1", sampleId).Scan(&jId)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleNotFound
		}
		return nil, err
	}

	_, err = db.Exec(`
        UPDATE samples
        SET status = 'received', received_laboratory_id = $1, received_at = $2, current_holder_id = $3, updated_at = NOW()
        WHERE id = $4
    `, labId, receivedAt, operatorId, sampleId)
	if err != nil {
		return nil, err
	}

	if jId.Valid {
		_, _ = db.Exec(`
            UPDATE journeys
            SET status = 'completed', updated_at = NOW()
            WHERE id = $1
        `, jId.String)
		_, _ = db.Exec(`
            UPDATE journey_legs
            SET status = 'completed', completed_at = $1, updated_at = NOW()
            WHERE journey_id = $2
        `, receivedAt, jId.String)
		_, _ = db.Exec(`
            UPDATE capacity_reservations
            SET active = false
            WHERE journey_id = $1
        `, jId.String)
	}

	RecordAudit(db, actorId, actorRole, actorRole, "laboratory_sample_received", "sample", sampleId, true, map[string]interface{}{
		"laboratoryId": labId,
		"operatorId":   operatorId,
	})

	BroadcastEvent(db, "sample_received", "sample", sampleId, map[string]interface{}{
		"laboratoryId": labId,
		"status":       "received",
	})

	return GetSampleLifecycle(db, sampleId)
}

func RecordLaboratoryException(db *sql.DB, sampleId, labId, operatorId, reason string, observedAt time.Time, actorId, actorRole string) (*models.SampleLifecycle, error) {
	excMap := map[string]interface{}{
