)

type contextKey string

const (
	UserContextKey       contextKey = "user"
	ActiveRoleContextKey contextKey = "activeRole"
	TokenContextKey      contextKey = "token"
)

func WriteJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if data != nil {
		_ = json.NewEncoder(w).Encode(data)
	}
}

func WriteError(w http.ResponseWriter, status int, code, msg string) {
	WriteJSON(w, status, models.ErrorEnvelope{
		Code:  code,
		Error: msg,
	})
}

func AuthMiddleware(db *sql.DB) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authHeader := r.Header.Get("Authorization")
			var token string
			if strings.HasPrefix(authHeader, "Bearer ") {
				token = strings.TrimPrefix(authHeader, "Bearer ")
			} else if cookie, err := r.Cookie("token"); err == nil {
				token = cookie.Value
			}

			if token != "" {
				user, activeRole, err := services.ValidateToken(db, token)
				if err == nil && user != nil {
					ctx := context.WithValue(r.Context(), UserContextKey, user)
					ctx = context.WithValue(ctx, ActiveRoleContextKey, activeRole)
					ctx = context.WithValue(ctx, TokenContextKey, token)
					r = r.WithContext(ctx)
				}
			}

			next.ServeHTTP(w, r)
		})
	}
}

func RequireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user := GetUserFromContext(r)
		if user == nil {
			WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication is required")
			return
		}
		next(w, r)
	}
}

func RequireRoles(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			user := GetUserFromContext(r)
			if user == nil {
				WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication is required")
				return
			}
			activeRole := GetActiveRoleFromContext(r)
			if !services.CheckRole(activeRole, roles...) {
				WriteError(w, http.StatusForbidden, "forbidden", "You do not have permission to perform this action in your current role")
				return
			}
			next(w, r)
		}
	}
}

func GetUserFromContext(r *http.Request) *models.User {
	if u, ok := r.Context().Value(UserContextKey).(*models.User); ok {
		return u
	}
	return nil
}

func GetActiveRoleFromContext(r *http.Request) string {
	if role, ok := r.Context().Value(ActiveRoleContextKey).(string); ok {
		return role
	}
	return ""
}

func GetTokenFromContext(r *http.Request) string {
	if token, ok := r.Context().Value(TokenContextKey).(string); ok {
		return token
	}
	return ""
}

func IdempotencyMiddleware(db *sql.DB) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			idempKey := r.Header.Get("Idempotency-Key")
			if idempKey == "" || r.Method == http.MethodGet {
				next.ServeHTTP(w, r)
				return
			}

			var bodyBytes []byte
			if r.Body != nil {
				bodyBytes, _ = io.ReadAll(r.Body)
				r.Body = io.NopCloser(bytes.NewBuffer(bodyBytes))
			}

			hash := sha256.Sum256(bodyBytes)
			hashStr := hex.EncodeToString(hash[:])

			var cachedCode int
			var cachedBody string
			err := db.QueryRow("SELECT response_code, response_body FROM idempotency_keys WHERE key = $1 AND endpoint = $2 AND request_hash = $3", idempKey, r.URL.Path, hashStr).Scan(&cachedCode, &cachedBody)
			if err == nil {
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(cachedCode)
				_, _ = w.Write([]byte(cachedBody))
				return
			}

			rec := &responseRecorder{ResponseWriter: w, body: &bytes.Buffer{}}
			next.ServeHTTP(rec, r)

			if rec.statusCode >= 200 && rec.statusCode < 300 {
				_, _ = db.Exec(`
                    INSERT INTO idempotency_keys (key, endpoint, request_hash, response_code, response_body)
                    VALUES ($1, $2, $3, $4, $5)
                    ON CONFLICT (key) DO NOTHING
                `, idempKey, r.URL.Path, hashStr, rec.statusCode, rec.body.String())
			}
		})
	}
}

type responseRecorder struct {
	http.ResponseWriter
	statusCode int
	body       *bytes.Buffer
}

func (r *responseRecorder) WriteHeader(statusCode int) {
	r.statusCode = statusCode
	r.ResponseWriter.WriteHeader(statusCode)
}

func (r *responseRecorder) Write(b []byte) (int, error) {
	if r.statusCode == 0 {
		r.statusCode = http.StatusOK
	}
	r.body.Write(b)
	return r.ResponseWriter.Write(b)
}

func CORSMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization, Idempotency-Key")

		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusOK)
			return
		}
		next.ServeHTTP(w, r)
	})
}

