package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"

	"labsystem/internal/models"
	"labsystem/internal/services"
)

type SampleHandlers struct {
	DB *sql.DB
}

type CreateRequestPayload struct {
	RequesterId             string            `json:"requesterId"`
	Origin                  models.Coordinate `json:"origin"`
	OriginType              string            `json:"originType"`
	OriginNodeId            *string           `json:"originNodeId,omitempty"`
	RequestedAt             string            `json:"requestedAt"`
	DeliveryDeadline        string            `json:"deliveryDeadline"`
	EarliestCollectionAt    *string           `json:"earliestCollectionAt,omitempty"`
	LatestCollectionAt      *string           `json:"latestCollectionAt,omitempty"`
	SampleTypeId            string            `json:"sampleTypeId"`
	ContainerType           string            `json:"containerType"`
	TemperatureMinC         float64           `json:"temperatureMinC"`
	TemperatureMaxC         float64           `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes,omitempty"`
	IdempotencyKey          string            `json:"idempotencyKey"`
}

func (h *SampleHandlers) HandleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	var req CreateRequestPayload
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	// Check idempotency
	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "create_collection_request")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	reqTime, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid requestedAt format")
		return
	}

	deadTime, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Invalid deliveryDeadline format")
		return
	}

	if deadTime.Before(reqTime) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Delivery deadline must be after requested time")
		return
	}

	var earliest, latest *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid earliestCollectionAt format")
			return
		}
		earliest = &t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid latestCollectionAt format")
			return
		}
		latest = &t
	}

	if earliest != nil && latest != nil && latest.Before(*earliest) {
		WriteError(w, http.StatusBadRequest, "invalid_collection_window", "Earliest collection time must be before latest collection time")
		return
	}

	requesterId := user.ID
	if req.RequesterId != "" {
		requesterId = req.RequesterId
	}

	origNodeId := ""
	if req.OriginNodeId != nil {
		origNodeId = *req.OriginNodeId
	}

	result, err := services.CreateCollectionRequest(h.DB, requesterId, req.Origin, req.OriginType, origNodeId, req.SampleTypeId, reqTime, deadTime, earliest, latest, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, req.IncompatibleSampleTypes, user.ID, role)
	if err != nil {
		if err.Error() == "outside_service_coverage" || err.Error() == "no_accepting_laboratory" || err.Error() == "no_route" || err.Error() == "insufficient_capacity" || err.Error() == "deadline_unreachable" || err.Error() == "handling_rules_unsatisfiable" {
			WriteError(w, http.StatusConflict, err.Error(), "Request cannot be serviced: "+err.Error())
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "create_collection_request", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

