func (h *SampleHandlers) HandleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId       string `json:"sampleId"`
		LaboratoryId   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "record_laboratory_exception")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	obsTime, err := time.Parse(time.RFC3339, req.ObservedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid observedAt format")
		return
	}

	excId, err := services.RecordLaboratoryException(h.DB, req.SampleId, req.LaboratoryId, user.ID, req.Reason, obsTime, role)
	if err != nil {
		if err == services.ErrSampleNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Sample or laboratory not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"exceptionId": excId,
			"sampleId":    req.SampleId,
			"status":      "exception",
		},
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "record_laboratory_exception", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

func (h *SampleHandlers) HandleReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleId := chi.URLParam(r, "sampleId")
	if sampleId == "" {
		parts := strings.Split(r.URL.Path, "/")
		if len(parts) > 0 {
			sampleId = parts[len(parts)-1]
		}
	}

	if sampleId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Sample ID is required")
		return
	}

	state, err := services.GetSampleState(h.DB, sampleId)
	if err != nil {
		if err == services.ErrSampleNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Sample not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": state,
	})
}

func (h *SampleHandlers) HandleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId string `json:"sampleId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.SampleId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Sample ID is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	lifecycle, err := services.GetSampleLifecycle(h.DB, req.SampleId)
	if err != nil {
		if err == services.ErrSampleNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Sample not found")
			return
		}
		if err == services.ErrForbidden {
			WriteError(w, http.StatusForbidden, "forbidden", "Forbidden")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": lifecycle,
	})
}

