func ConfigureCapacity(db *sql.DB, resourceId string, capacityUnits int, cooledCapacityUnits *int, actorId, actorRole string) (*int, error) {
	if capacityUnits < 0 || (cooledCapacityUnits != nil && *cooledCapacityUnits < 0) {
		return nil, ErrInvalidCapacity
	}

	// Try Location first
	var reservedUnits, cooledReservedUnits int
	err := db.QueryRow("SELECT reserved_units, cooled_reserved_units FROM locations WHERE id = $1", resourceId).Scan(&reservedUnits, &cooledReservedUnits)
	if err == nil {
		if capacityUnits < reservedUnits {
			return nil, ErrCapacityReserved
		}
		if cooledCapacityUnits != nil && *cooledCapacityUnits < cooledReservedUnits {
			return nil, ErrCapacityReserved
		}

		cCap := 0
		if cooledCapacityUnits != nil {
			cCap = *cooledCapacityUnits
			_, err = db.Exec("UPDATE locations SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW() WHERE id = $3", capacityUnits, cCap, resourceId)
		} else {
			_, err = db.Exec("UPDATE locations SET capacity_units = $1, updated_at = NOW() WHERE id = $2", capacityUnits, resourceId)
		}
		if err != nil {
			return nil, err
		}

