	}

	reqTime, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid requestedAt format")
		return
	}

	deadTime, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Invalid deliveryDeadline format")
		return
	}

	if deadTime.Before(reqTime) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Delivery deadline must be after requested time")
		return
	}

	var earliest, latest *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid earliestCollectionAt format")
			return
		}
		earliest = &t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid latestCollectionAt format")
			return
		}
		latest = &t
	}

	if req.RequesterId != "" {
		user.ID = req.RequesterId
	}

	origNodeId := ""
	if req.OriginNodeId != nil {
		origNodeId = *req.OriginNodeId
	}

	result, err := services.IngestPresealedSample(h.DB, user.ID, role, req.Origin, req.OriginType, origNodeId, req.SampleTypeId, reqTime, deadTime, earliest, latest, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, req.IncompatibleSampleTypes)
	if err != nil {
		if err.Error() == "outside_service_coverage" || err.Error() == "no_accepting_laboratory" || err.Error() == "no_route" || err.Error() == "insufficient_capacity" || err.Error() == "deadline_unreachable" || err.Error() == "handling_rules_unsatisfiable" {
			WriteError(w, http.StatusConflict, err.Error(), "Sample cannot be serviced: "+err.Error())
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "ingest_presealed_sample", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

func (h *SampleHandlers) HandleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId             string  `json:"sampleId"`
		AssignmentId         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "Idempotency key is required")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	cached, cachedData, err := services.CheckIdempotency(h.DB, req.IdempotencyKey, user.ID, "collect_and_seal_sample")
	if err != nil {
		WriteError(w, http.StatusConflict, "idempotency_conflict", "Idempotency conflict")
		return
	}
	if cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		w.Write([]byte(cachedData))
		return
	}

	collTime, err := time.Parse(time.RFC3339, req.CollectedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid collectedAt format")
		return
	}

	result, err := services.CollectAndSealSample(h.DB, req.SampleId, req.AssignmentId, user.ID, req.ContainerType, req.ObservedTemperatureC, collTime, user.ID, role)
	if err != nil {
		switch err {
		case services.ErrSampleNotFound:
			WriteError(w, http.StatusNotFound, "not_found", "Sample or assignment not found")
		case services.ErrIneligibleWorker:
			WriteError(w, http.StatusForbidden, "ineligible_worker", "Collector lacks required certification")
		case services.ErrInvalidTransition:
			WriteError(w, http.StatusConflict, "invalid_sample_state", "Sample is not in requested state or assignment not accepted")
		case services.ErrOutsideCollectionWindow:
			WriteError(w, http.StatusConflict, "collection_window_missed", "Collection time is outside collection window")
		default:
			WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		}
		return
	}

	resp := map[string]interface{}{
		"data": result,
	}
	respBytes, _ := json.Marshal(resp)
	services.SaveIdempotency(h.DB, req.IdempotencyKey, user.ID, "collect_and_seal_sample", string(respBytes))

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(respBytes)
}

func (h *SampleHandlers) HandleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentId string            `json:"assignmentId"`
		Coordinate   models.Coordinate `json:"coordinate"`
		Sequence     int               `json:"sequence"`
		RecordedAt   string            `json:"recordedAt"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON request")
		return
	}

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	recTime, err := time.Parse(time.RFC3339, req.RecordedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid recordedAt format")
		return
	}

	err = services.RecordWorkerLocation(h.DB, req.AssignmentId, user.ID, req.Coordinate, req.Sequence, recTime, role)
	if err != nil {
		if err == services.ErrAssignmentNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Assignment not found")
			return
		}
		if err == services.ErrAssignmentTaken {
			WriteError(w, http.StatusConflict, "assignment_inactive", "Assignment is not assigned to current user")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusCreated, map[string]interface{}{
		"data": map[string]interface{}{
			"assignmentId": req.AssignmentId,
			"coordinate":   req.Coordinate,
			"sequence":     req.Sequence,
			"recordedAt":   req.RecordedAt,
		},
	})
}

func (h *SampleHandlers) HandleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleId             string  `json:"sampleId"`
