func (h *SampleHandlers) HandleReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleId := chi.URLParam(r, "sampleId")
	if sampleId == "" {
		parts := strings.Split(r.URL.Path, "/")
		if len(parts) > 0 {
			sampleId = parts[len(parts)-1]
		}
	}

	if sampleId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "Sample ID is required")
