func (h *WorkDispatchHandlers) HandleBootstrap(w http.ResponseWriter, r *http.Request) {
	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	if user == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Unauthorized")
		return
	}

	// Fetch requester samples if requester
	requesterSamples := make([]map[string]interface{}, 0)
	rows, err := h.DB.Query(`
        SELECT id, sample_type_id, status, origin_type, delivery_deadline, latest_location_id, latest_location_stale
        FROM samples
        WHERE requester_id = $1
        ORDER BY created_at DESC LIMIT 50
    `, user.ID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id, sType, status, origType string
			var dLine time.Time
			var locId *string
			var stale bool
			if err := rows.Scan(&id, &sType, &status, &origType, &dLine, &locId, &stale); err == nil {
				requesterSamples = append(requesterSamples, map[string]interface{}{
					"sampleId":            id,
					"sampleTypeId":        sType,
					"status":              status,
					"originType":          origType,
					"deliveryDeadline":    dLine.Format(time.RFC3339),
					"latestLocationId":    locId,
					"latestLocationStale": stale,
				})
			}
		}
	}

	// Fetch operations state if dispatcher or admin
	var ops *models.OperationsState
	if role == models.RoleDispatcher || role == models.RoleAdministrator {
		ops, _ = services.GetOperationsState(h.DB, nil, user.ID, role)
	}

	res := map[string]interface{}{
		"user": map[string]interface{}{
			"userId":                user.ID,
			"username":              user.Username,
			"fullName":              user.FullName,
			"roles":                 user.Roles,
			"activeRole":            role,
			"roleSelectionRequired": len(user.Roles) > 1 && role == "",
		},
		"serverTime":       time.Now().Format(time.RFC3339),
		"requesterSamples": requesterSamples,
	}
	if ops != nil {
		res["operations"] = ops
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": res,
	})
}

