export type UserRole =
  | 'requester'
  | 'certified_collection_professional'
  | 'relay_courier'
  | 'node_handler'
  | 'laboratory_intake_operator'
  | 'dispatcher'
  | 'administrator';

export interface User {
  id: string;
  username: string;
  email?: string;
  fullName?: string;
  phone?: string;
  roles: UserRole[];
  activeRole?: UserRole;
  qualifications: string[];
  certifications?: Array<{
    name: string;
    code: string;
    expiresAt?: string;
  }>;
  active: boolean;
  assignedLocationId?: string;
  available?: boolean;
  capacityUnits?: number;
  assignmentCount?: number;
  recentDeclines?: number;
  lastLocation?: {
    latitude: number;
    longitude: number;
    updatedAt: string;
  };
}

export interface Location {
  id: string;
  name: string;
  code: string;
  latitude: number;
  longitude: number;
  isCollectionPoint: boolean;
  isTransferPoint: boolean;
  isHub: boolean;
  isLaboratory: boolean;
  active: boolean;
  collectionActive: boolean;
  transferActive: boolean;
  hubActive: boolean;
  laboratoryActive: boolean;
  acceptedSampleTypes: string[];
  regularCapacity: number;
  cooledCapacity: number;
  reservedRegularCapacity: number;
  reservedCooledCapacity: number;
  handlingTimeMinutes: number;
}

export interface NetworkConnection {
  id: string;
  fromLocationId: string;
  toLocationId: string;
  distanceKm: number;
  transitTimeMinutes: number;
  regularCapacity: number;
  cooledCapacity: number;
  reservedRegularCapacity: number;
  reservedCooledCapacity: number;
  active: boolean;
}

export interface SampleType {
  id: string;
  code: string;
  name: string;
  container: string;
  minTempC: number;
  maxTempC: number;
  requiresCooled: boolean;
  requiresQualifiedCollector: boolean;
  requiredQualificationCode?: string;
  incompatibleSampleTypes: string[];
  isTimeCritical: boolean;
  maxTransitTimeMinutes: number;
  active: boolean;
}

export interface Sample {
  id: string;
  trackingNumber: string;
  sampleTypeCode: string;
  sampleType?: SampleType;
  originType: 'home' | 'clinic' | 'node';
  originAddress?: string;
  originLatitude: number;
  originLongitude: number;
  originLocationId?: string;
  destinationLocationId: string;
  requesterId: string;
  requesterName?: string;
  status: 'requested' | 'assigned' | 'collected' | 'sealed' | 'in_transit' | 'at_hub' | 'received' | 'rejected' | 'exception' | 'expired' | 'cancelled';
  collectionWindowStart: string;
  collectionWindowEnd: string;
  deliveryDeadline: string;
  sealedAt?: string;
  sealedByUserId?: string;
  currentHolderUserId?: string;
  currentHolderName?: string;
  currentLocationId?: string;
  currentLatitude?: number;
  currentLongitude?: number;
  locationUpdatedAt?: string;
  isLocationStale?: boolean;
  requiresCooled: boolean;
  requiresQualifiedCollector: boolean;
  requiredQualificationCode?: string;
  exceptionReason?: string;
  isException?: boolean;
  activeJourneyId?: string;
  createdAt: string;
  updatedAt: string;
}

export interface TransportLeg {
  id: string;
  journeyId: string;
  legSequence: number;
  legType: 'collection' | 'transport' | 'transfer' | 'lab_intake';
  fromLocationId?: string;
  fromLatitude?: number;
  fromLongitude?: number;
  toLocationId?: string;
  toLatitude?: number;
  toLongitude?: number;
  assignedUserId?: string;
