action.file_text:
import {
  User,
  UserRole,
  Location,
  NetworkConnection,
  SampleType,
  Sample,
  Journey,
  WorkAssignment,
  StatusEvent,
  HandoffRecord,
  AuditEvent,
  ServiceabilityResult,
  OperationsState,
} from '../types';

const API_BASE = '/api';

export class ApiError extends Error {
  status: number;
  data: any;

  constructor(message: string, status: number, data?: any) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

function getAuthHeader(): HeadersInit {
  const token = localStorage.getItem('auth_token');
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  return headers;
}

async function request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
  const headers = {
    ...getAuthHeader(),
    ...options.headers,
  };

  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers,
  });

  const text = await response.text();
  let data: any;
  try {
    data = text ? JSON.parse(text) : {};
  } catch {
    data = { message: text };
  }

  if (!response.ok) {
    throw new ApiError(data?.error || data?.message || `Request failed with status ${response.status}`, response.status, data);
  }

  return data as T;
}

export const api = {
  // Auth
  async authenticate(username: string, password?: string): Promise<{ token: string; user: User }> {
    return request('/authenticate-user', {
      method: 'POST',
      body: JSON.stringify({ username, password }),
    });
  },

  async selectActiveRole(role: UserRole): Promise<{ user: User }> {
    return request('/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ role }),
    });
  },

  async getUser(userId: string): Promise<{ user: User }> {
    return request(`/read-user/${userId}`, {
      method: 'GET',
    });
  },

  async getBootstrap(): Promise<{
    user: User;
    locations: Location[];
    sampleTypes: SampleType[];
    connections: NetworkConnection[];
  }> {
    return request('/ui/bootstrap', {
      method: 'GET',
    });
  },

  // Serviceability
  async checkServiceability(params: {
    originLatitude: number;
    originLongitude: number;
    sampleTypeCode: string;
    collectionWindowStart: string;
    collectionWindowEnd: string;
    deliveryDeadline: string;
  }): Promise<ServiceabilityResult> {
    return request('/check-serviceability', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async readServiceabilitySnapshot(): Promise<{ snapshot: any }> {
    return request('/read-serviceability-snapshot', {
      method: 'POST',
      body: JSON.stringify({}),
    });
  },

  // Work & Assignments
  async listRoleWork(params: { role: UserRole; statusFilter?: string }): Promise<{
    currentWork: WorkAssignment[];
    pastWork: WorkAssignment[];
  }> {
    return request('/list-role-work', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async acceptAssignment(assignmentId: string): Promise<{ assignment: WorkAssignment }> {
    return request('/accept-assignment', {
      method: 'POST',
      body: JSON.stringify({ assignmentId }),
    });
  },

  async declineAssignment(assignmentId: string, reason?: string): Promise<{ success: boolean }> {
    return request('/decline-assignment', {
      method: 'POST',
      body: JSON.stringify({ assignmentId, reason }),
    });
  },

  async setWorkerAvailability(available: boolean): Promise<{ success: boolean; user: User }> {
    return request('/set-worker-availability', {
      method: 'POST',
      body: JSON.stringify({ available }),
    });
  },

  async recordWorkerLocation(latitude: number, longitude: number): Promise<{ success: boolean }> {
    return request('/record-worker-location', {
      method: 'POST',
      body: JSON.stringify({ latitude, longitude }),
    });
  },

  async updateAssignmentProgress(params: {
    assignmentId: string;
    progressStatus: string;
    latitude?: number;
    longitude?: number;
    notes?: string;
  }): Promise<{ success: boolean }> {
    return request('/update-assignment-progress', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  // Requests & Samples
  async createCollectionRequest(params: {
    originType: 'home' | 'clinic' | 'node';
    originAddress?: string;
    originLatitude: number;
    originLongitude: number;
    originLocationId?: string;
    destinationLocationId?: string;
    sampleTypeCode: string;
    collectionWindowStart: string;
    collectionWindowEnd: string;
    deliveryDeadline: string;
    notes?: string;
  }): Promise<{ sample: Sample; journey: Journey }> {
    return request('/create-collection-request', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async ingestPresealedSample(params: {
    originLocationId: string;
    destinationLocationId?: string;
    sampleTypeCode: string;
    deliveryDeadline: string;
    containerType: string;
    currentTemperatureC?: number;
    notes?: string;
  }): Promise<{ sample: Sample; journey: Journey }> {
    return request('/ingest-presealed-sample', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async collectAndSealSample(params: {
    sampleId: string;
    containerType: string;
    sealNumber: string;
    initialTemperatureC?: number;
    notes?: string;
  }): Promise<{ sample: Sample }> {
    return request('/collect-and-seal-sample', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async getSampleState(sampleId: string): Promise<{ sample: Sample; journey?: Journey }> {
    return request(`/read-sample-state/${sampleId}`, {
      method: 'GET',
    });
  },

  async getSampleLifecycle(sampleId: string): Promise<{
    sample: Sample;
    timeline: StatusEvent[];
    handoffs: HandoffRecord[];
  }> {
    return request('/read-sample-lifecycle', {
      method: 'POST',
      body: JSON.stringify({ sampleId }),
    });
  },

  async recordHandlingCheckpoint(params: {
    sampleId: string;
    observedContainerType: string;
    observedTemperatureC: number;
    latitude?: number;
    longitude?: number;
    notes?: string;
  }): Promise<{ sample: Sample; isException: boolean }> {
    return request('/record-handling-checkpoint', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async confirmLaboratoryReceipt(params: {
    sampleId: string;
    observedContainerType: string;
    observedTemperatureC: number;
    notes?: string;
  }): Promise<{ sample: Sample }> {
    return request('/confirm-laboratory-receipt', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async recordLaboratoryException(params: {
    sampleId: string;
    reason: string;
    exceptionType: string;
    notes?: string;
  }): Promise<{ sample: Sample }> {
    return request('/record-laboratory-exception', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  // Handoffs
  async initiateHandoff(params: {
    sampleId: string;
    receiverUserId: string;
    locationId?: string;
    containerType?: string;
    temperatureC?: number;
  }): Promise<{ handoff: HandoffRecord }> {
    return request('/initiate-handoff', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async confirmHandoff(params: {
    handoffId: string;
    roleInHandoff: 'sender' | 'receiver';
    observedContainerType?: string;
    observedTemperatureC?: number;
  }): Promise<{ handoff: HandoffRecord; sample: Sample }> {
    return request('/confirm-handoff', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  // Capacity & Network Config
  async configureCapacity(params: {
    targetType: 'location' | 'connection';
    targetId: string;
    regularCapacity: number;
    cooledCapacity: number;
  }): Promise<{ success: boolean; target: any }> {
    return request('/configure-capacity', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  },

  async configureLaboratoryAcceptance(params: {
    locationId: string;
    acceptedSampleTypes: string[];
  }): Promise<{ location: Location }> {
    return request('/configure-laboratory-acceptance', {
      method: 'POST',
