import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { api } from '../api/client';

interface AuthContextType {
  user: User | null;
  activeRole: UserRole | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  login: (username: string, password?: string) => Promise<void>;
  logout: () => void;
  switchRole: (role: UserRole) => Promise<void>;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [token, setToken] = useState<string | null>(localStorage.getItem('auth_token'));
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const initAuth = async () => {
      const savedToken = localStorage.getItem('auth_token');
      const savedUserId = localStorage.getItem('auth_user_id');

      if (savedToken && savedUserId) {
        try {
          const res = await api.getUser(savedUserId);
          if (res && res.user) {
            setUser(res.user);
            setActiveRole(res.user.activeRole || (res.user.roles && res.user.roles.length > 0 ? res.user.roles[0] : null));
          }
        } catch (err) {
          console.error('Failed to restore auth session:', err);
          logout();
        }
      }
      setIsLoading(false);
    };

    initAuth();
  }, []);

  const login = async (username: string, password?: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.authenticate(username, password);
      localStorage.setItem('auth_token', res.token);
      localStorage.setItem('auth_user_id', res.user.id);
      setToken(res.token);
      setUser(res.user);
      setActiveRole(res.user.activeRole || (res.user.roles && res.user.roles.length > 0 ? res.user.roles[0] : null));
    } catch (err: any) {
      const msg = err.message || 'Invalid username or password';
      setError(msg);
      throw err;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_user_id');
    setToken(null);
    setUser(null);
    setActiveRole(null);
  };

  const switchRole = async (role: UserRole) => {
    if (!user) return;
    try {
      const res = await api.selectActiveRole(role);
      setUser(res.user);
      setActiveRole(res.user.activeRole || role);
    } catch (err: any) {
      console.error('Failed to switch active role:', err);
      throw err;
    }
  };

  const refreshUser = async () => {
    if (!user?.id) return;
    try {
      const res = await api.getUser(user.id);
      if (res && res.user) {
        setUser(res.user);
        setActiveRole(res.user.activeRole || activeRole);
      }
    } catch (err) {
      console.error('Failed to refresh user:', err);
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        activeRole,
        token,
        isAuthenticated: !!user && !!token,
        isLoading,
        error,
        login,
        logout,
        switchRole,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

