import React from 'react';
import { useAuth } from '../context/AuthContext';
import { UserRole } from '../types';

interface NavbarProps {
  currentTab: string;
  onSelectTab: (tab: string) => void;
}

export const Navbar: React.FC<NavbarProps> = ({ currentTab, onSelectTab }) => {
  const { user, activeRole, switchRole, logout } = useAuth();

  if (!user) return null;

  const roleLabels: Record<UserRole, string> = {
    requester: 'Requester',
    certified_collection_professional: 'Collection Pro',
    relay_courier: 'Relay Courier',
    node_handler: 'Node Handler',
    laboratory_intake_operator: 'Lab Intake Operator',
    dispatcher: 'Dispatcher',
    administrator: 'Administrator',
  };

  const handleRoleChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRole = e.target.value as UserRole;
    try {
      await switchRole(newRole);
    } catch (err) {
      alert('Failed to switch role');
    }
  };

  const isDispatcherOrAdmin = activeRole === 'dispatcher' || activeRole === 'administrator';
  const isAdmin = activeRole === 'administrator';

  return (
    <header className="navbar">
      <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
        <a href="#home" className="navbar-brand" onClick={() => onSelectTab('work')}>
          <span style={{ fontSize: '1.5rem' }}>🧪</span>
          <span>Lab Logistics System</span>
        </a>

        <nav style={{ display: 'flex', gap: '0.5rem' }}>
          <button
            className={`tab ${currentTab === 'work' ? 'active' : ''}`}
            onClick={() => onSelectTab('work')}
          >
            My Work
          </button>

          {activeRole === 'requester' && (
            <button
              className={`tab ${currentTab === 'serviceability' ? 'active' : ''}`}
              onClick={() => onSelectTab('serviceability')}
            >
              Check Serviceability
            </button>
          )}

          {(activeRole === 'node_handler' || activeRole === 'laboratory_intake_operator' || isDispatcherOrAdmin) && (
            <button
              className={`tab ${currentTab === 'capacity' ? 'active' : ''}`}
              onClick={() => onSelectTab('capacity')}
            >
              Capacity
            </button>
          )}

          {isDispatcherOrAdmin && (
            <>
              <button
                className={`tab ${currentTab === 'operations' ? 'active' : ''}`}
                onClick={() => onSelectTab('operations')}
              >
                Live Operations
              </button>
              <button
                className={`tab ${currentTab === 'audit' ? 'active' : ''}`}
                onClick={() => onSelectTab('audit')}
              >
                Audit Trail
              </button>
            </>
          )}

          {isAdmin && (
            <button
              className={`tab ${currentTab === 'admin' ? 'active' : ''}`}
              onClick={() => onSelectTab('admin')}
            >
              Administration
            </button>
          )}
        </nav>
      </div>

      <div className="navbar-actions">
        {/* Role Switcher */}
        <div className="role-switcher">
          <label htmlFor="role-select" style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--gray-600)' }}>
            Active Role:
          </label>
          <select
            id="role-select"
            aria-label="Select Active Role"
            value={activeRole || ''}
            onChange={handleRoleChange}
          >
            {user.roles.map((r) => (
              <option key={r} value={r}>
                {roleLabels[r] || r}
              </option>
            ))}
          </select>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <span style={{ fontSize: '0.875rem', fontWeight: 500, color: 'var(--gray-700)' }}>
            {user.fullName || user.username}
          </span>
          <button
            className="btn btn-secondary btn-sm"
            onClick={logout}
            aria-label="Sign Out"
          >
            Sign Out
          </button>
        </div>
      </div>
    </header>
  );
};

