import React from 'react';
import { StatusEvent } from '../types';

interface TimelineProps {
  events: StatusEvent[];
}

export const Timeline: React.FC<TimelineProps> = ({ events }) => {
  if (!events || events.length === 0) {
    return <p style={{ color: 'var(--gray-500)', fontSize: '0.875rem' }}>No status events recorded yet.</p>;
  }

  const formatTime = (ts: string) => {
    try {
      const d = new Date(ts);
      return d.toLocaleString(undefined, {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
      });
    } catch {
      return ts;
    }
  };

  return (
    <div className="timeline">
      {events.map((ev, idx) => (
        <div key={idx} className="timeline-item">
          <div className="timeline-dot" />
          <div className="timeline-time">{formatTime(ev.timestamp)}</div>
          <div className="timeline-title">
            <span style={{ textTransform: 'capitalize' }}>{ev.status.replace(/_/g, ' ')}</span>
            {ev.actorName && (
              <span style={{ fontWeight: 'normal', color: 'var(--gray-600)', marginLeft: '0.5rem', fontSize: '0.8125rem' }}>
                by {ev.actorName} {ev.role ? `(${ev.role.replace(/_/g, ' ')})` : ''}
              </span>
            )}
          </div>
          {ev.details && <div className="timeline-desc">{ev.details}</div>}
          {ev.location && <div className="timeline-desc" style={{ color: 'var(--gray-500)' }}>📍 {ev.location}</div>}
        </div>
      ))}
    </div>
  );
};

