import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import { Location, Sample, User } from '../types';

interface MapProps {
  locations?: Location[];
  samples?: Sample[];
  workers?: User[];
  selectedLocation?: { lat: number; lng: number };
  onMapClick?: (coords: { lat: number; lng: number }) => void;
  height?: string;
}

let protocolAdded = false;

export const MapComponent: React.FC<MapProps> = ({
  locations = [],
  samples = [],
  workers = [],
  selectedLocation,
  onMapClick,
  height = '450px',
}) => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!protocolAdded) {
      const protocol = new pmtiles.Protocol();
      maplibregl.addProtocol('pmtiles', protocol.tile);
      protocolAdded = true;
    }

    if (!mapContainer.current) return;

    // Bangalore center coordinates by default
    const defaultCenter: [number, number] = [77.5946, 12.9716];
    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: '/map-assets/style.json',
      center: defaultCenter,
      zoom: 11,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');

    map.on('click', (e) => {
      if (onMapClick) {
        onMapClick({ lat: e.lngLat.lat, lng: e.lngLat.lng });
      }
    });

    mapInstance.current = map;

    return () => {
      map.remove();
      mapInstance.current = null;
    };
  }, []);

  // Update markers whenever props change
  useEffect(() => {
    const map = mapInstance.current;
    if (!map) return;

    // Clear existing markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    // Add Locations
    locations.forEach((loc) => {
      if (loc.latitude && loc.longitude) {
        const el = document.createElement('div');
        el.className = 'location-marker';
        el.style.width = '24px';
        el.style.height = '24px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = loc.isLaboratory ? '#9333ea' : loc.isHub ? '#2563eb' : '#059669';
        el.style.border = '2px solid white';
        el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
        el.style.display = 'flex';
        el.style.alignItems = 'center';
        el.style.justifyContent = 'center';
        el.style.color = 'white';
        el.style.fontSize = '12px';
        el.style.fontWeight = 'bold';
        el.innerHTML = loc.isLaboratory ? '🔬' : loc.isHub ? '🏢' : '🏥';
        el.title = `${loc.name} (${loc.code})`;

        const popup = new maplibregl.Popup({ offset: 25 }).setHTML(`
          <div style="font-family: sans-serif; padding: 4px;">
            <div style="font-weight: bold; margin-bottom: 2px;">${loc.name}</div>
            <div style="font-size: 11px; color: #666;">Code: ${loc.code}</div>
            <div style="font-size: 11px;">Cap: Reg ${loc.regularCapacity}, Cold ${loc.cooledCapacity}</div>
          </div>
        `);

        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(popup)
          .addTo(map);

        markersRef.current.push(marker);
      }
    });

    // Add Workers
    workers.forEach((worker) => {
      if (worker.lastLocation?.latitude && worker.lastLocation?.longitude) {
        const el = document.createElement('div');
        el.className = 'worker-marker';
        el.style.width = '22px';
        el.style.height = '22px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = '#ea580c';
        el.style.border = '2px solid white';
        el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
        el.style.display = 'flex';
        el.style.alignItems = 'center';
        el.style.justifyContent = 'center';
        el.style.color = 'white';
