import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { ServiceabilityResult, SampleType, Location } from '../types';
import { MapComponent } from './Map';

interface ServiceabilityCheckProps {
  sampleTypes: SampleType[];
  locations: Location[];
}

export const ServiceabilityCheck: React.FC<ServiceabilityCheckProps> = ({ sampleTypes, locations }) => {
  const [lat, setLat] = useState<number>(12.9716);
  const [lng, setLng] = useState<number>(77.5946);
  const [sampleType, setSampleType] = useState<string>(sampleTypes[0]?.code || 'Amber');

  // Default window: now to +2h, deadline: +6h
  const now = new Date();
  const defaultStart = new Date(now.getTime() + 15 * 60000).toISOString().slice(0, 16);
  const defaultEnd = new Date(now.getTime() + 120 * 60000).toISOString().slice(0, 16);
  const defaultDeadline = new Date(now.getTime() + 360 * 60000).toISOString().slice(0, 16);

  const [windowStart, setWindowStart] = useState<string>(defaultStart);
  const [windowEnd, setWindowEnd] = useState<string>(defaultEnd);
  const [deadline, setDeadline] = useState<string>(defaultDeadline);

  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<ServiceabilityResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleMapClick = (coords: { lat: number; lng: number }) => {
    setLat(Number(coords.lat.toFixed(6)));
    setLng(Number(coords.lng.toFixed(6)));
  };

  const handleCheck = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
      const res = await api.checkServiceability({
        originLatitude: lat,
        originLongitude: lng,
        sampleTypeCode: sampleType,
        collectionWindowStart: new Date(windowStart).toISOString(),
        collectionWindowEnd: new Date(windowEnd).toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setResult(res);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Serviceability check failed');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="card">
      <div className="card-header">
        <h2 className="card-title">Serviceability Dry Run Check</h2>
        <span className="badge badge-info">Does not create request or reserve capacity</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
        <form onSubmit={handleCheck}>
          <div style={{ marginBottom: '1rem' }}>
            <p style={{ fontSize: '0.875rem', color: 'var(--gray-600)', marginBottom: '0.5rem' }}>
              Click on the map or enter coordinates to check whether a sample can be collected and reach an active laboratory before deadline.
            </p>
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="serv-lat">Latitude</label>
              <input
                id="serv-lat"
                type="number"
                step="any"
                className="form-input"
                value={lat}
                onChange={(e) => setLat(parseFloat(e.target.value))}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="serv-lng">Longitude</label>
              <input
                id="serv-lng"
                type="number"
                step="any"
                className="form-input"
                value={lng}
                onChange={(e) => setLng(parseFloat(e.target.value))}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="serv-type">Sample Type</label>
            <select
              id="serv-type"
              className="form-select"
              value={sampleType}
              onChange={(e) => setSampleType(e.target.value)}
            >
              {sampleTypes.map((st) => (
                <option key={st.code} value={st.code}>
                  {st.name} ({st.code}) - {st.requiresCooled ? '❄️ Cooled' : 'Standard'}
                </option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="serv-start">Window Start</label>
              <input
                id="serv-start"
                type="datetime-local"
                className="form-input"
                value={windowStart}
                onChange={(e) => setWindowStart(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="serv-end">Window End</label>
              <input
                id="serv-end"
                type="datetime-local"
                className="form-input"
                value={windowEnd}
                onChange={(e) => setWindowEnd(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="serv-deadline">Delivery Deadline</label>
            <input
              id="serv-deadline"
              type="datetime-local"
              className="form-input"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            style={{ width: '100%', marginTop: '0.5rem' }}
            disabled={isLoading}
            aria-label="Check Serviceability"
          >
            {isLoading ? 'Checking...' : 'Check Serviceability'}
          </button>

          {error && (
            <div style={{ marginTop: '1rem', padding: '0.75rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', fontSize: '0.875rem' }}>
              <strong>Error:</strong> {error}
            </div>
          )}

          {result && (
            <div style={{ marginTop: '1.5rem', padding: '1rem', borderRadius: '0.375rem', backgroundColor: result.isServiceable ? 'var(--success-light)' : 'var(--danger-light)', border: `1px solid ${result.isServiceable ? 'var(--success)' : 'var(--danger)'}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.5rem' }}>
                <span style={{ fontSize: '1.25rem' }}>{result.isServiceable ? '✅' : '❌'}</span>
