import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { SampleType, Location, Sample } from '../types';

interface PresealedSampleModalProps {
  sampleTypes: SampleType[];
  locations: Location[];
  onClose: () => void;
  onSuccess: (sample: Sample) => void;
}

export const PresealedSampleModal: React.FC<PresealedSampleModalProps> = ({
  sampleTypes,
  locations,
  onClose,
  onSuccess,
}) => {
  const [originLocationId, setOriginLocationId] = useState<string>(locations[0]?.id || '');
  const [sampleTypeCode, setSampleTypeCode] = useState<string>(sampleTypes[0]?.code || 'Amber');
  const [containerType, setContainerType] = useState<string>('Standard Tube');
  const [currentTemp, setCurrentTemp] = useState<number>(20);
  const [notes, setNotes] = useState<string>('');

  const now = new Date();
  const defaultDeadline = new Date(now.getTime() + 240 * 60000).toISOString().slice(0, 16);
  const [deadline, setDeadline] = useState<string>(defaultDeadline);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!originLocationId) {
      setError('Origin location is required (clinic or network node)');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const res = await api.ingestPresealedSample({
        originLocationId,
        sampleTypeCode,
        containerType,
        currentTemperatureC: currentTemp,
        deliveryDeadline: new Date(deadline).toISOString(),
        notes,
      });

      onSuccess(res.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to ingest presealed sample');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>Register Pre-Sealed Sample</h3>
          <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close">
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          {error && (
            <div
              style={{
                marginBottom: '1rem',
                padding: '0.75rem',
                backgroundColor: 'var(--danger-light)',
                color: 'var(--danger)',
                borderRadius: '0.375rem',
                fontSize: '0.875rem',
              }}
            >
              {error}
            </div>
          )}

          <div className="form-group">
            <label className="form-label" htmlFor="pre-loc">Origin Location (Clinic or Node)</label>
            <select
              id="pre-loc"
              className="form-select"
              value={originLocationId}
              onChange={(e) => setOriginLocationId(e.target.value)}
              required
            >
              {locations.map((loc) => (
                <option key={loc.id} value={loc.id}>
                  {loc.name} ({loc.code})
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="pre-type">Sample Type</label>
            <select
              id="pre-type"
              className="form-select"
              value={sampleTypeCode}
              onChange={(e) => setSampleTypeCode(e.target.value)}
            >
              {sampleTypes.map((st) => (
                <option key={st.code} value={st.code}>
                  {st.name} ({st.code})
                </option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="pre-container">Container Type</label>
              <input
                id="pre-container"
                type="text"
                className="form-input"
                value={containerType}
                onChange={(e) => setContainerType(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="pre-temp">Current Temperature (°C)</label>
              <input
                id="pre-temp"
                type="number"
                step="0.1"
                className="form-input"
                value={currentTemp}
                onChange={(e) => setCurrentTemp(parseFloat(e.target.value))}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="pre-deadline">Delivery Deadline</label>
            <input
              id="pre-deadline"
              type="datetime-local"
              className="form-input"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
            />
