import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { Sample } from '../types';

interface HandlingCheckpointModalProps {
  sample: Sample;
  onClose: () => void;
  onSuccess: (updatedSample: Sample) => void;
}

export const HandlingCheckpointModal: React.FC<HandlingCheckpointModalProps> = ({
  sample,
  onClose,
  onSuccess,
}) => {
  const [containerType, setContainerType] = useState('Standard Insulated Container');
  const [tempC, setTempC] = useState<number>(sample.requiresCooled ? 3.0 : 20.0);
  const [lat, setLat] = useState<number>(sample.currentLatitude || 12.9716);
  const [lng, setLng] = useState<number>(sample.currentLongitude || 77.5946);
  const [notes, setNotes] = useState('');

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      const res = await api.recordHandlingCheckpoint({
        sampleId: sample.id,
        observedContainerType: containerType,
        observedTemperatureC: tempC,
        latitude: lat,
        longitude: lng,
        notes,
      });

      onSuccess(res.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to record checkpoint');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>Record Handling Checkpoint</h3>
          <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close">
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '1rem', fontSize: '0.875rem', color: 'var(--gray-600)' }}>
            Recording checkpoint for sample <strong>{sample.trackingNumber}</strong> ({sample.sampleTypeCode}).
            {sample.requiresCooled && <div style={{ color: 'var(--primary)', marginTop: '0.25rem' }}>❄️ Cooled handling required (2°C - 8°C)</div>}
          </div>

          {error && (
            <div
              style={{
                marginBottom: '1rem',
                padding: '0.75rem',
                backgroundColor: 'var(--danger-light)',
                color: 'var(--danger)',
                borderRadius: '0.375rem',
                fontSize: '0.875rem',
              }}
            >
              {error}
            </div>
          )}

          <div className="form-group">
            <label className="form-label" htmlFor="chk-container">Observed Container Type</label>
            <input
              id="chk-container"
              type="text"
              className="form-input"
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="chk-temp">Observed Temperature (°C)</label>
            <input
              id="chk-temp"
              type="number"
              step="0.1"
              className="form-input"
              value={tempC}
              onChange={(e) => setTempC(parseFloat(e.target.value))}
              required
            />
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="chk-lat">Current Latitude</label>
              <input
                id="chk-lat"
                type="number"
                step="any"
                className="form-input"
                value={lat}
                onChange={(e) => setLat(parseFloat(e.target.value))}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="chk-lng">Current Longitude</label>
              <input
                id="chk-lng"
                type="number"
                step="any"
                className="form-input"
                value={lng}
                onChange={(e) => setLng(parseFloat(e.target.value))}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="chk-notes">Observations / Notes</label>
            <textarea
              id="chk-notes"
              className="form-textarea"
              rows={2}
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1rem' }}>
            <button type="button" className="btn btn-secondary" onClick={onClose}>
              Cancel
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isLoading}
              aria-label="Save Checkpoint"
            >
              {isLoading ? 'Saving...' : 'Record Checkpoint'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

