                  {sample.status}
                </span>
              </div>
            </div>

            <div style={{ backgroundColor: 'var(--gray-50)', padding: '0.75rem', borderRadius: '0.375rem', border: '1px solid var(--gray-200)' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Current Custodian</div>
              <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginTop: '0.25rem', color: 'var(--gray-800)' }}>
                {sample.currentHolderName || sample.currentHolderUserId || 'None / Not sealed'}
              </div>
            </div>

            <div style={{ backgroundColor: 'var(--gray-50)', padding: '0.75rem', borderRadius: '0.375rem', border: '1px solid var(--gray-200)' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Location Freshness</div>
              <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginTop: '0.25rem' }}>
                {sample.isLocationStale ? (
                  <span className="badge badge-warning">⚠️ Stale Location</span>
                ) : (
                  <span className="badge badge-success">✓ Fresh</span>
                )}
                {sample.locationUpdatedAt && (
                  <div style={{ fontSize: '0.7rem', color: 'var(--gray-500)', marginTop: '2px' }}>
                    Updated {formatDateTime(sample.locationUpdatedAt)}
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2" style={{ marginBottom: '1.25rem' }}>
            <div>
              <h4 style={{ fontSize: '0.875rem', fontWeight: 600, color: 'var(--gray-700)', marginBottom: '0.5rem' }}>
                Sample Properties
              </h4>
              <ul style={{ fontSize: '0.8125rem', listStyle: 'none', color: 'var(--gray-600)' }}>
                <li style={{ marginBottom: '0.25rem' }}><strong>Type:</strong> {sample.sampleTypeCode}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Origin:</strong> {sample.originType} ({sample.originAddress || `${sample.originLatitude}, ${sample.originLongitude}`})</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Requires Cooled:</strong> {sample.requiresCooled ? 'Yes (2°C - 8°C)' : 'No'}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Qualified Collector:</strong> {sample.requiresQualifiedCollector ? 'Required' : 'Standard'}</li>
                {sample.sealedAt && <li style={{ marginBottom: '0.25rem' }}><strong>Sealed At:</strong> {formatDateTime(sample.sealedAt)}</li>}
              </ul>
            </div>

            <div>
              <h4 style={{ fontSize: '0.875rem', fontWeight: 600, color: 'var(--gray-700)', marginBottom: '0.5rem' }}>
                Time Constraints
              </h4>
              <ul style={{ fontSize: '0.8125rem', listStyle: 'none', color: 'var(--gray-600)' }}>
                <li style={{ marginBottom: '0.25rem' }}><strong>Window Start:</strong> {formatDateTime(sample.collectionWindowStart)}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Window End:</strong> {formatDateTime(sample.collectionWindowEnd)}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Delivery Deadline:</strong> <span style={{ color: 'var(--danger)', fontWeight: 600 }}>{formatDateTime(sample.deliveryDeadline)}</span></li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Current Location:</strong> {sample.currentLatitude ? `${sample.currentLatitude.toFixed(4)}, ${sample.currentLongitude?.toFixed(4)}` : 'N/A'}</li>
              </ul>
            </div>
          </div>

          {/* Custody Actions */}
          <div style={{ display: 'flex', gap: '0.75rem', padding: '0.75rem', backgroundColor: 'var(--gray-100)', borderRadius: '0.375rem', marginBottom: '1.25rem' }}>
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => setShowCheckpointModal(true)}
              aria-label="Record Handling Checkpoint"
            >
              🌡️ Record Handling Checkpoint
            </button>

            <button
              className="btn btn-primary btn-sm"
              onClick={() => setShowHandoffModal(true)}
              aria-label="Manage Handoff"
            >
              🤝 {pendingHandoff ? 'Confirm Custody Handoff' : 'Initiate Custody Handoff'}
            </button>
          </div>

          {/* Status Timeline */}
          <div>
            <h4 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.5rem' }}>
              Status History & Chain of Custody
            </h4>
            <Timeline events={timeline} />
          </div>
        </div>
      </div>

      {showCheckpointModal && (
        <HandlingCheckpointModal
          sample={sample}
          onClose={() => setShowCheckpointModal(false)}
          onSuccess={(updated) => {
            setSample(updated);
            setShowCheckpointModal(false);
            loadData();
          }}
        />
      )}

      {showHandoffModal && (
        <HandoffModal
          sample={sample}
          workers={workers}
          locations={locations}
          existingHandoff={pendingHandoff}
          onClose={() => setShowHandoffModal(false)}
          onSuccess={(updated) => {
            setSample(updated);
            setShowHandoffModal(false);
            loadData();
          }}
        />
      )}
    </>
  );
};

