import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { Location, NetworkConnection, User } from '../types';

interface CapacityManagerProps {
  locations: Location[];
  connections: NetworkConnection[];
  currentUser: User;
  onRefresh: () => void;
}

export const CapacityManager: React.FC<CapacityManagerProps> = ({
  locations,
  connections,
  currentUser,
  onRefresh,
}) => {
  const [targetType, setTargetType] = useState<'location' | 'connection'>('location');
  const [targetId, setTargetId] = useState<string>(
    currentUser.assignedLocationId || locations[0]?.id || ''
  );
  const [regularCap, setRegularCap] = useState<number>(50);
  const [cooledCap, setCooledCap] = useState<number>(20);

  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Filter locations if node handler or lab operator is assigned to a specific node
  const isAssigned = !!currentUser.assignedLocationId;
  const filteredLocations = isAssigned
    ? locations.filter((l) => l.id === currentUser.assignedLocationId)
    : locations;

  const handleTargetChange = (id: string) => {
    setTargetId(id);
    if (targetType === 'location') {
      const loc = locations.find((l) => l.id === id);
      if (loc) {
        setRegularCap(loc.regularCapacity);
        setCooledCap(loc.cooledCapacity);
      }
    } else {
      const conn = connections.find((c) => c.id === id);
      if (conn) {
        setRegularCap(conn.regularCapacity);
        setCooledCap(conn.cooledCapacity);
      }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setMessage(null);

    try {
      await api.configureCapacity({
        targetType,
        targetId,
        regularCapacity: Number(regularCap),
        cooledCapacity: Number(cooledCap),
      });

      setMessage('Capacity updated successfully');
      onRefresh();
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to update capacity');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="card">
      <div className="card-header">
        <h2 className="card-title">Capacity Management</h2>
        <span className="badge badge-info">Regular & Cooled Capacity Pools</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
        <form onSubmit={handleSave}>
          <div className="form-group">
            <label className="form-label" htmlFor="cap-target-type">Target Type</label>
            <select
              id="cap-target-type"
              className="form-select"
              value={targetType}
              onChange={(e) => {
                const t = e.target.value as 'location' | 'connection';
                setTargetType(t);
                if (t === 'location') {
                  setTargetId(filteredLocations[0]?.id || '');
                } else {
                  setTargetId(connections[0]?.id || '');
                }
              }}
              disabled={isAssigned}
            >
              <option value="location">Location / Facility</option>
              {!isAssigned && <option value="connection">Transport Connection</option>}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="cap-target">Select Target</label>
            <select
              id="cap-target"
              className="form-select"
              value={targetId}
              onChange={(e) => handleTargetChange(e.target.value)}
              required
            >
              {targetType === 'location' ? (
                filteredLocations.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name} ({l.code}) - {l.isLaboratory ? 'Lab' : 'Node'}
                  </option>
                ))
              ) : (
                connections.map((c) => (
                  <option key={c.id} value={c.id}>
                    Connection: {c.fromLocationId} → {c.toLocationId}
                  </option>
                ))
              )}
            </select>
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="cap-regular">Configured Regular Capacity</label>
              <input
                id="cap-regular"
                type="number"
                min="0"
                className="form-input"
                value={regularCap}
                onChange={(e) => setRegularCap(parseInt(e.target.value, 10))}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="cap-cooled">Configured Cooled Capacity</label>
              <input
                id="cap-cooled"
                type="number"
                min="0"
                className="form-input"
                value={cooledCap}
                onChange={(e) => setCooledCap(parseInt(e.target.value, 10))}
                required
              />
            </div>
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            disabled={isLoading}
            aria-label="Save Capacity"
          >
            {isLoading ? 'Saving...' : 'Update Capacity'}
          </button>

          {message && (
            <div style={{ marginTop: '0.75rem', padding: '0.5rem', backgroundColor: 'var(--success-light)', color: 'var(--success)', borderRadius: '0.375rem', fontSize: '0.875rem' }}>
              ✓ {message}
            </div>
          )}

          {error && (
            <div style={{ marginTop: '0.75rem', padding: '0.5rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', fontSize: '0.875rem' }}>
              ❌ {error}
            </div>
          )}
        </form>

        {/* Capacity Overview Table */}
        <div className="table-container">
          <h4 style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.5rem' }}>Current Capacity Status</h4>
          <table className="table">
            <thead>
              <tr>
                <th>Location</th>
                <th>Regular (Avail/Tot)</th>
                <th>Cooled (Avail/Tot)</th>
              </tr>
            </thead>
            <tbody>
              {filteredLocations.map((loc) => {
                const regAvail = loc.regularCapacity - (loc.reservedRegularCapacity || 0);
                const coolAvail = loc.cooledCapacity - (loc.reservedCooledCapacity || 0);
                return (
                  <tr key={loc.id}>
                    <td>
                      <div style={{ fontWeight: 600 }}>{loc.name}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{loc.code}</div>
                    </td>
                    <td>
                      <span className={`badge ${regAvail <= 0 ? 'badge-danger' : 'badge-success'}`}>
                        {regAvail} / {loc.regularCapacity}
                      </span>
                    </td>
                    <td>
                      <span className={`badge ${coolAvail <= 0 ? 'badge-danger' : 'badge-info'}`}>
                        {coolAvail} / {loc.cooledCapacity}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

