import React, { useState, useEffect } from 'react';
import { api, ApiError } from '../api/client';
import { UserRole, WorkAssignment, SampleType, Location, User } from '../types';
import { LocationRecorder } from './LocationRecorder';
import { CreateRequestModal } from './CreateRequestModal';
import { PresealedSampleModal } from './PresealedSampleModal';
import { SampleDetailModal } from './SampleDetailModal';

interface RoleWorkViewProps {
  activeRole: UserRole;
  currentUser: User;
  sampleTypes: SampleType[];
  locations: Location[];
  workers: User[];
  onRefreshAll: () => void;
}

export const RoleWorkView: React.FC<RoleWorkViewProps> = ({
  activeRole,
  currentUser,
  sampleTypes,
  locations,
  workers,
  onRefreshAll,
}) => {
  const [currentWork, setCurrentWork] = useState<WorkAssignment[]>([]);
  const [pastWork, setPastWork] = useState<WorkAssignment[]>([]);
  const [activeTab, setActiveTab] = useState<'current' | 'past'>('current');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Modals
  const [showCreateReqModal, setShowCreateReqModal] = useState(false);
  const [showPresealedModal, setShowPresealedModal] = useState(false);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Collect and seal state
  const [collectingAssignment, setCollectingAssignment] = useState<WorkAssignment | null>(null);
  const [sealContainer, setSealContainer] = useState('Standard Insulated Box');
  const [sealNumber, setSealNumber] = useState('SEAL-001');
  const [sealTemp, setSealTemp] = useState<number>(20.0);

  // Lab intake receipt/exception state
  const [labActionAssignment, setLabActionAssignment] = useState<WorkAssignment | null>(null);
  const [labActionType, setLabActionType] = useState<'receipt' | 'exception'>('receipt');
  const [labContainer, setLabContainer] = useState('Standard Tube Box');
  const [labTemp, setLabTemp] = useState<number>(4.0);
  const [labExceptionReason, setLabExceptionReason] = useState('Broken container / seal tampered');

  const loadWork = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.listRoleWork({ role: activeRole });
      setCurrentWork(res.currentWork || []);
      setPastWork(res.pastWork || []);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to load work items');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadWork();
  }, [activeRole]);

  const handleAccept = async (assignmentId: string) => {
    try {
      await api.acceptAssignment(assignmentId);
      loadWork();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to accept assignment');
    }
  };

  const handleDecline = async (assignmentId: string) => {
    const reason = prompt('Please enter decline reason (optional):') || undefined;
    try {
      await api.declineAssignment(assignmentId, reason);
      loadWork();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to decline assignment');
    }
  };

  const handleUpdateProgress = async (assignmentId: string, progressStatus: string) => {
    try {
      await api.updateAssignmentProgress({
        assignmentId,
        progressStatus,
      });
      loadWork();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to update progress');
    }
  };

  const handleCollectAndSealSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!collectingAssignment) return;
    try {
      await api.collectAndSealSample({
        sampleId: collectingAssignment.sampleId,
        containerType: sealContainer,
        sealNumber,
        initialTemperatureC: sealTemp,
      });
      setCollectingAssignment(null);
      loadWork();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to collect and seal sample');
    }
  };

  const handleLabReceiptSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!labActionAssignment) return;
    try {
      if (labActionType === 'receipt') {
        await api.confirmLaboratoryReceipt({
          sampleId: labActionAssignment.sampleId,
          observedContainerType: labContainer,
          observedTemperatureC: labTemp,
        });
      } else {
        await api.recordLaboratoryException({
          sampleId: labActionAssignment.sampleId,
          reason: labExceptionReason,
          exceptionType: 'quality_rejection',
        });
      }
      setLabActionAssignment(null);
      loadWork();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Action failed');
    }
  };

  const roleTitleMap: Record<UserRole, string> = {
    requester: 'Requester Dashboard',
    certified_collection_professional: 'Collection Professional Work Queue',
    relay_courier: 'Relay Courier Transport Queue',
    node_handler: 'Node Operations Queue',
    laboratory_intake_operator: 'Laboratory Intake Queue',
    dispatcher: 'Dispatcher Assigned Work',
    administrator: 'Admin Work Queue',
  };

  const displayedList = activeTab === 'current' ? currentWork : pastWork;

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 700, color: 'var(--gray-900)' }}>
            {roleTitleMap[activeRole] || 'Work Queue'}
          </h2>
          <p style={{ fontSize: '0.875rem', color: 'var(--gray-500)' }}>
            Viewing work for role: <strong style={{ color: 'var(--gray-800)' }}>{activeRole}</strong>
          </p>
        </div>

        <div style={{ display: 'flex', gap: '0.75rem' }}>
          {activeRole === 'requester' && (
            <button
              className="btn btn-primary"
              onClick={() => setShowCreateReqModal(true)}
              aria-label="Create Request"
            >
              + Create Collection Request
            </button>
          )}

          {(activeRole === 'certified_collection_professional' ||
            activeRole === 'relay_courier' ||
            activeRole === 'node_handler' ||
            activeRole === 'laboratory_intake_operator') && (
            <button
              className="btn btn-secondary"
              onClick={() => setShowPresealedModal(true)}
              aria-label="Register Presealed Sample"
            >
              + Ingest Presealed Sample
            </button>
          )}

          <button className="btn btn-secondary" onClick={loadWork} aria-label="Refresh Work">
            🔄 Refresh
          </button>
        </div>
      </div>

      {(activeRole === 'certified_collection_professional' || activeRole === 'relay_courier') && (
        <LocationRecorder onLocationRecorded={() => onRefreshAll()} />
      )}

      {/* Tabs for Current and Past Work */}
      <div className="card">
        <div className="tabs">
          <button
            className={`tab ${activeTab === 'current' ? 'active' : ''}`}
            onClick={() => setActiveTab('current')}
            aria-label="Current Work Tab"
          >
            Current Work ({currentWork.length})
          </button>
          <button
            className={`tab ${activeTab === 'past' ? 'active' : ''}`}
            onClick={() => setActiveTab('past')}
            aria-label="Past Work Tab"
          >
            Past Work ({pastWork.length})
          </button>
        </div>

        {error && (
          <div
            style={{
              padding: '0.75rem',
              backgroundColor: 'var(--danger-light)',
              color: 'var(--danger)',
              borderRadius: '0.375rem',
              marginBottom: '1rem',
            }}
          >
            {error}
          </div>
        )}

        {isLoading ? (
          <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--gray-500)' }}>
            Loading assignments...
          </div>
        ) : displayedList.length === 0 ? (
          <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--gray-500)' }}>
            No {activeTab} work items found for your role.
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Tracking / Sample</th>
                  <th>Leg Type & Route</th>
                  <th>Status</th>
                  <th>Deadlines / Windows</th>
                  <th>Requirements</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {displayedList.map((item) => {
                  const isOffered = item.status === 'offered';
                  const isAssigned = item.status === 'assigned';
                  const isInProgress = item.status === 'in_progress';

                  return (
                    <tr key={item.assignmentId}>
                      <td>
                        <button
                          style={{
                            background: 'none',
                            border: 'none',
                            fontWeight: 700,
                            color: 'var(--primary)',
                            cursor: 'pointer',
                            padding: 0,
                            textAlign: 'left',
                          }}
                          onClick={() => setSelectedSampleId(item.sampleId)}
                          aria-label={`View sample ${item.sampleTrackingNumber}`}
                        >
                          {item.sampleTrackingNumber || item.sampleId}
                        </button>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>
                          Type: {item.sampleTypeCode}
                        </div>
                      </td>

                      <td>
                        <div style={{ fontWeight: 600, textTransform: 'capitalize' }}>
                          {item.legType.replace(/_/g, ' ')}
                        </div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-600)' }}>
                          {item.fromName || 'Origin'} → {item.toName || 'Destination'}
                        </div>
                      </td>

                      <td>
                        <span
                          className={`badge ${
                            item.status === 'completed'
                              ? 'badge-success'
                              : item.status === 'offered'
                              ? 'badge-warning'
                              : item.status === 'in_progress'
                              ? 'badge-info'
                              : item.status === 'declined' || item.status === 'cancelled'
                              ? 'badge-danger'
                              : 'badge-gray'
                          }`}
                        >
                          {item.status}
                        </span>
                      </td>

                      <td>
                        {item.deliveryDeadline && (
                          <div style={{ fontSize: '0.75rem' }}>
                            <strong>Deadline:</strong> {new Date(item.deliveryDeadline).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </div>
                        )}
                        {item.collectionWindowEnd && (
                          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>
                            Window: {new Date(item.collectionWindowStart || '').toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {new Date(item.collectionWindowEnd).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </div>
                        )}
                      </td>

                      <td>
                        <div style={{ display: 'flex', gap: '0.25rem', flexWrap: 'wrap' }}>
                          {item.requiresCooled && <span className="badge badge-info">❄️ Cold</span>}
                          {item.requiresQualifiedCollector && <span className="badge badge-warning">⭐ Qual. Collector</span>}
                          {item.isTimeCritical && <span className="badge badge-danger">⚡ Pulse</span>}
                        </div>
                      </td>

                      <td>
                        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                          {/* Offered Actions */}
                          {isOffered && (
                            <>
                              <button
                                className="btn btn-primary btn-sm"
                                onClick={() => handleAccept(item.assignmentId)}
                                aria-label="Accept Assignment"
                              >
                                Accept
                              </button>
                              <button
                                className="btn btn-danger btn-sm"
                                onClick={() => handleDecline(item.assignmentId)}
                                aria-label="Decline Assignment"
                              >
                                Decline
                              </button>
                            </>
                          )}

                          {/* Collection Pro Actions */}
                          {activeRole === 'certified_collection_professional' && (isAssigned || isInProgress) && (
                            <>
                              {isAssigned && (
                                <button
                                  className="btn btn-secondary btn-sm"
                                  onClick={() => handleUpdateProgress(item.assignmentId, 'in_progress')}
                                  aria-label="Start Collection"
                                >
                                  Start Collection
                                </button>
                              )}
                              <button
                                className="btn btn-success btn-sm"
                                onClick={() => {
                                  setCollectingAssignment(item);
                                  setSealTemp(item.requiresCooled ? 4.0 : 20.0);
                                }}
                                aria-label="Collect and Seal"
                              >
                                Collect & Seal
                              </button>
                            </>
                          )}

                          {/* Relay Courier Actions */}
                          {activeRole === 'relay_courier' && (isAssigned || isInProgress) && (
                            <>
                              {isAssigned && (
                                <button
                                  className="btn btn-secondary btn-sm"
                                  onClick={() => handleUpdateProgress(item.assignmentId, 'in_progress')}
                                  aria-label="Start Transport"
                                >
                                  Start Transport
                                </button>
                              )}
                              {isInProgress && (
                                <button
                                  className="btn btn-success btn-sm"
                                  onClick={() => handleUpdateProgress(item.assignmentId, 'completed')}
                                  aria-label="Complete Leg"
                                >
                                  Complete Leg
                                </button>
                              )}
                            </>
                          )}

                          {/* Lab Intake Actions */}
                          {activeRole === 'laboratory_intake_operator' && (isAssigned || isInProgress) && (
                            <>
                              <button
                                className="btn btn-success btn-sm"
                                onClick={() => {
                                  setLabActionAssignment(item);
                                  setLabActionType('receipt');
                                }}
                                aria-label="Confirm Receipt"
                              >
                                Confirm Receipt
                              </button>
                              <button
                                className="btn btn-danger btn-sm"
                                onClick={() => {
                                  setLabActionAssignment(item);
                                  setLabActionType('exception');
                                }}
                                aria-label="Record Exception"
                              >
                                Exception
                              </button>
                            </>
                          )}

                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => setSelectedSampleId(item.sampleId)}
                            aria-label="View Details"
                          >
                            Details
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Collect & Seal Modal */}
      {collectingAssignment && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>Collect and Seal Sample</h3>
              <button className="btn btn-secondary btn-sm" onClick={() => setCollectingAssignment(null)}>✕</button>
            </div>
            <form onSubmit={handleCollectAndSealSubmit}>
              <div style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
                Sample: <strong>{collectingAssignment.sampleTrackingNumber}</strong> ({collectingAssignment.sampleTypeCode})
              </div>

              <div className="form-group">
                <label className="form-label">Container Type</label>
                <input
                  type="text"
                  className="form-input"
                  value={sealContainer}
                  onChange={(e) => setSealContainer(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Security Seal Number</label>
                <input
                  type="text"
                  className="form-input"
                  value={sealNumber}
                  onChange={(e) => setSealNumber(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Initial Temperature (°C)</label>
                <input
                  type="number"
                  step="0.1"
                  className="form-input"
                  value={sealTemp}
                  onChange={(e) => setSealTemp(parseFloat(e.target.value))}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1rem' }}>
                <button type="button" className="btn btn-secondary" onClick={() => setCollectingAssignment(null)}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary" aria-label="Confirm Sealing">
                  Confirm Sealing & Custody
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Lab Intake Receipt / Exception Modal */}
      {labActionAssignment && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>
                {labActionType === 'receipt' ? 'Confirm Laboratory Receipt' : 'Record Laboratory Exception'}
              </h3>
              <button className="btn btn-secondary btn-sm" onClick={() => setLabActionAssignment(null)}>✕</button>
            </div>
            <form onSubmit={handleLabReceiptSubmit}>
              <div style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
                Sample: <strong>{labActionAssignment.sampleTrackingNumber}</strong>
              </div>

              {labActionType === 'receipt' ? (
                <>
                  <div className="form-group">
                    <label className="form-label">Observed Container</label>
                    <input
                      type="text"
                      className="form-input"
                      value={labContainer}
                      onChange={(e) => setLabContainer(e.target.value)}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Observed Temperature (°C)</label>
                    <input
                      type="number"
                      step="0.1"
                      className="form-input"
                      value={labTemp}
                      onChange={(e) => setLabTemp(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                </>
              ) : (
                <div className="form-group">
                  <label className="form-label">Exception Reason</label>
                  <textarea
                    className="form-textarea"
                    rows={3}
                    value={labExceptionReason}
                    onChange={(e) => setLabExceptionReason(e.target.value)}
                    required
                  />
                </div>
              )}

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1rem' }}>
                <button type="button" className="btn btn-secondary" onClick={() => setLabActionAssignment(null)}>
                  Cancel
                </button>
                <button
                  type="submit"
                  className={`btn ${labActionType === 'receipt' ? 'btn-success' : 'btn-danger'}`}
                  aria-label="Confirm Lab Action"
                >
                  {labActionType === 'receipt' ? 'Confirm Acceptance' : 'Reject Sample'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modals */}
      {showCreateReqModal && (
        <CreateRequestModal
          sampleTypes={sampleTypes}
          locations={locations}
          onClose={() => setShowCreateReqModal(false)}
          onSuccess={(sample) => {
            setShowCreateReqModal(false);
            loadWork();
            onRefreshAll();
            setSelectedSampleId(sample.id);
          }}
        />
      )}

      {showPresealedModal && (
        <PresealedSampleModal
          sampleTypes={sampleTypes}
          locations={locations}
          onClose={() => setShowPresealedModal(false)}
          onSuccess={(sample) => {
            setShowPresealedModal(false);
            loadWork();
            onRefreshAll();
            setSelectedSampleId(sample.id);
          }}
        />
      )}

      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          workers={workers}
          locations={locations}
          currentUserId={currentUser.id}
          onClose={() => {
            setSelectedSampleId(null);
            loadWork();
          }}
        />
      )}
    </div>
  );
};

