                    <button
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleSplit(j)}
                    >
                      Split Leg
                    </button>
                    <button
                      className="btn btn-danger btn-sm"
                      onClick={() => handleCancel(j)}
                    >
                      Cancel
                    </button>
                    <label style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '0.75rem', marginLeft: 'auto' }}>
