                <option value="node">Collection Node / Hub</option>
                <option value="laboratory">Laboratory</option>
                <option value="connection">Transport Connection</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Select Unavailable Entity</label>
