        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Active Samples</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--primary)' }}>
            {samples.length}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Active Journeys</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--gray-800)' }}>
            {journeys.length}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Exceptions Flagged</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: exceptionSamplesCount > 0 ? 'var(--danger)' : 'var(--success)' }}>
            {exceptionSamplesCount}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Stale Locations</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: staleSamplesCount > 0 ? 'var(--warning)' : 'var(--success)' }}>
            {staleSamplesCount}
          </div>
        </div>
      </div>

      {/* Live Map */}
      <div className="card" style={{ marginBottom: '1.5rem' }}>
        <div className="card-header">
          <h3 className="card-title">Live Network Map</h3>
          <span style={{ fontSize: '0.8125rem', color: 'var(--gray-500)' }}>
            🔵 Samples | 🚗 Couriers | 🔬 Laboratories | 🏢 Hubs
          </span>
        </div>
        <MapComponent
          locations={locations}
          samples={samples}
          workers={opWorkers}
          height="450px"
        />
      </div>

      {/* Live Samples Table */}
      <div className="card">
