            </p>

            <div className="form-group">
              <label className="form-label">Disruption Target Type</label>
              <select
                className="form-select"
                value={disruptionTargetType}
                onChange={(e) => {
                  const t = e.target.value as any;
                  setDisruptionTargetType(t);
                  setDisruptionTargetId('');
                }}
              >
                <option value="worker">Worker</option>
                <option value="node">Collection Node / Hub</option>
                <option value="laboratory">Laboratory</option>
                <option value="connection">Transport Connection</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Select Unavailable Entity</label>
              <select
                className="form-select"
                value={disruptionTargetId}
                onChange={(e) => setDisruptionTargetId(e.target.value)}
                required
              >
                <option value="">-- Choose Unavailable Item --</option>
                {disruptionTargetType === 'worker' &&
                  opWorkers.map((w) => (
                    <option key={w.id} value={w.id}>
                      {w.fullName || w.username} ({w.activeRole || 'Worker'})
                    </option>
                  ))}
                {disruptionTargetType === 'node' &&
                  locations
                    .filter((l) => l.isCollectionPoint || l.isHub)
                    .map((l) => (
                      <option key={l.id} value={l.id}>
                        {l.name} ({l.code})
                      </option>
                    ))}
                {disruptionTargetType === 'laboratory' &&
                  locations
                    .filter((l) => l.isLaboratory)
                    .map((l) => (
                      <option key={l.id} value={l.id}>
                        Lab: {l.name} ({l.code})
                      </option>
                    ))}
                {disruptionTargetType === 'connection' &&
                  connections.map((c) => (
                    <option key={c.id} value={c.id}>
                      Connection: {c.fromLocationId} → {c.toLocationId}
                    </option>
                  ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Reason / Notes</label>
              <textarea
                className="form-textarea"
                rows={2}
                value={disruptionReason}
                onChange={(e) => setDisruptionReason(e.target.value)}
                required
              />
            </div>

            <button type="submit" className="btn btn-danger" aria-label="Trigger Disruption Replanning">
              Trigger Disruption Replanning
            </button>
          </form>
        </div>
      </div>

      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          workers={opWorkers}
          locations={locations}
          onClose={() => {
            setSelectedSampleId(null);
            loadOperations();
          }}
        />
      )}
    </div>
  );
};

