import { User, Location, NetworkConnection, SampleType, UserRole } from '../types';

interface AdminPanelProps {
  users: User[];
  locations: Location[];
  connections: NetworkConnection[];
  sampleTypes: SampleType[];
  onRefreshAll: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({
  users,
  locations,
  connections,
  sampleTypes,
  onRefreshAll,
}) => {
  const [activeAdminTab, setActiveAdminTab] = useState<'users' | 'locations' | 'connections' | 'sampleTypes'>('users');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // User form
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('Password123!');
  const [newFullName, setNewFullName] = useState('');
  const [newUserRoles, setNewUserRoles] = useState<UserRole[]>(['certified_collection_professional']);
  const [newQualifications, setNewQualifications] = useState<string>('Amber,Indigo,Frost,Pulse');
  const [newAssignedLocationId, setNewAssignedLocationId] = useState<string>('');

  // Location form
  const [locName, setLocName] = useState('');
  const [locCode, setLocCode] = useState('');
  const [locLat, setLocLat] = useState(12.9716);
  const [locLng, setLocLng] = useState(77.5946);
  const [locIsCollection, setLocIsCollection] = useState(true);
  const [locIsTransfer, setLocIsTransfer] = useState(false);
  const [locIsHub, setLocIsHub] = useState(false);
  const [locIsLab, setLocIsLab] = useState(false);
  const [locRegCap, setLocRegCap] = useState(100);
  const [locCoolCap, setLocCoolCap] = useState(50);
  const [locHandlingMins, setLocHandlingMins] = useState(10);
  const [locAcceptedSamples, setLocAcceptedSamples] = useState('Amber,Indigo,Frost,Pulse');

  // Connection form
  const [connFrom, setConnFrom] = useState(locations[0]?.id || '');
  const [connTo, setConnTo] = useState(locations[1]?.id || '');
  const [connDist, setConnDist] = useState(10);
  const [connTime, setConnTime] = useState(25);
  const [connRegCap, setConnRegCap] = useState(50);
  const [connCoolCap, setConnCoolCap] = useState(20);

  // Sample type form
  const [stCode, setStCode] = useState('');
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('Standard Tube Box');
  const [stMinTemp, setStMinTemp] = useState(2);
  const [stMaxTemp, setStMaxTemp] = useState(8);
  const [stRequiresCooled, setStRequiresCooled] = useState(false);
  const [stRequiresQualified, setStRequiresQualified] = useState(true);
  const [stIncompatibilities, setStIncompatibilities] = useState('');
  const [stIsTimeCritical, setStIsTimeCritical] = useState(false);
  const [stMaxTransitTime, setStMaxTransitTime] = useState(240);

  const clearMessages = () => {
    setError(null);
    setSuccess(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createUser({
        username: newUsername,
        password: newPassword,
        fullName: newFullName,
        roles: newUserRoles,
        qualifications: newQualifications.split(',').map((s) => s.trim()).filter(Boolean),
        assignedLocationId: newAssignedLocationId || undefined,
      });
      setSuccess(`User ${newUsername} created successfully`);
      setNewUsername('');
      setNewFullName('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create user');
    }
  };

  const handleToggleUserActive = async (user: User) => {
    clearMessages();
    try {
      await api.updateUserAccess({
        userId: user.id,
        active: !user.active,
      });
      setSuccess(`User ${user.username} ${user.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to update user status');
    }
  };

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createLocation({
        name: locName,
        code: locCode,
        latitude: locLat,
        longitude: locLng,
        isCollectionPoint: locIsCollection,
        isTransferPoint: locIsTransfer,
        isHub: locIsHub,
        isLaboratory: locIsLab,
        regularCapacity: locRegCap,
        cooledCapacity: locCoolCap,
        handlingTimeMinutes: locHandlingMins,
        acceptedSampleTypes: locAcceptedSamples.split(',').map((s) => s.trim()).filter(Boolean),
      });
      setSuccess(`Location ${locName} created successfully`);
      setLocName('');
      setLocCode('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create location');
    }
  };

  const handleToggleLocationActive = async (loc: Location) => {
    clearMessages();
    try {
      await api.setLocationStatus(loc.id, !loc.active);
      setSuccess(`Location ${loc.name} ${loc.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to toggle location status');
    }
  };

  const handleToggleFunctionActive = async (loc: Location, fnType: 'collection' | 'transfer' | 'hub' | 'laboratory', currentVal: boolean) => {
    clearMessages();
    try {
      await api.setLocationFunctionStatus({
        locationId: loc.id,
        functionType: fnType,
        active: !currentVal,
      });
      setSuccess(`Function ${fnType} on ${loc.name} updated`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to update function status');
    }
  };

  const handleCreateConnection = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createConnection({
        fromLocationId: connFrom,
        toLocationId: connTo,
        distanceKm: Number(connDist),
        transitTimeMinutes: Number(connTime),
        regularCapacity: Number(connRegCap),
        cooledCapacity: Number(connCoolCap),
      });
      setSuccess('Connection created successfully');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create connection');
    }
  };

  const handleToggleConnection = async (conn: NetworkConnection) => {
    clearMessages();
    try {
      await api.setConnectionStatus(conn.id, !conn.active);
      setSuccess(`Connection ${conn.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to toggle connection');
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createSampleType({
        code: stCode,
        name: stName,
        container: stContainer,
        minTempC: Number(stMinTemp),
        maxTempC: Number(stMaxTemp),
        requiresCooled: stRequiresCooled,
        requiresQualifiedCollector: stRequiresQualified,
        incompatibleSampleTypes: stIncompatibilities.split(',').map((s) => s.trim()).filter(Boolean),
        isTimeCritical: stIsTimeCritical,
        maxTransitTimeMinutes: Number(stMaxTransitTime),
      });
      setSuccess(`Sample type ${stName} created successfully`);
      setStCode('');
      setStName('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create sample type');
    }
  };

  return (
    <div>
      <div style={{ marginBottom: '1.25rem' }}>
        <h2 style={{ fontSize: '1.5rem', fontWeight: 700, color: 'var(--gray-900)' }}>
          Administration Panel
        </h2>
        <p style={{ fontSize: '0.875rem', color: 'var(--gray-500)' }}>
          Manage network nodes, laboratories, users, certifications, sample types, and network connections
        </p>
      </div>

      {error && (
        <div style={{ padding: '0.75rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', marginBottom: '1rem' }}>
          ❌ {error}
        </div>
      )}

      {success && (
        <div style={{ padding: '0.75rem', backgroundColor: 'var(--success-light)', color: 'var(--success)', borderRadius: '0.375rem', marginBottom: '1rem' }}>
          ✓ {success}
        </div>
      )}

      {/* Admin Tabs */}
      <div className="card">
        <div className="tabs">
          <button
            className={`tab ${activeAdminTab === 'users' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('users')}
          >
            Users & Certifications ({users.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'locations' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('locations')}
          >
            Locations & Laboratories ({locations.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'connections' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('connections')}
          >
            Network Connections ({connections.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'sampleTypes' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('sampleTypes')}
          >
            Sample Types ({sampleTypes.length})
          </button>
        </div>

        {/* USERS TAB */}
        {activeAdminTab === 'users' && (
          <div className="grid grid-cols-2">
            <div>
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Add New User</h3>
              <form onSubmit={handleCreateUser}>
                <div className="form-group">
                  <label className="form-label">Username</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newUsername}
                    onChange={(e) => setNewUsername(e.target.value)}
                    required
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Password</label>
                  <input
                    type="password"
                    className="form-input"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    required
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Full Name</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newFullName}
                    onChange={(e) => setNewFullName(e.target.value)}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Roles (select multiple)</label>
                  <select
                    multiple
                    className="form-select"
                    style={{ height: '120px' }}
                    value={newUserRoles}
                    onChange={(e) => {
                      const selected = Array.from(e.target.selectedOptions, (option) => option.value as UserRole);
                      setNewUserRoles(selected);
                    }}
                  >
                    <option value="requester">Requester</option>
                    <option value="certified_collection_professional">Certified Collection Professional</option>
                    <option value="relay_courier">Relay Courier</option>
                    <option value="node_handler">Node Handler</option>
                    <option value="laboratory_intake_operator">Laboratory Intake Operator</option>
                    <option value="dispatcher">Dispatcher</option>
                    <option value="administrator">Administrator</option>
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label">Qualifications / Certifications (comma separated)</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newQualifications}
                    onChange={(e) => setNewQualifications(e.target.value)}
                    placeholder="Amber, Indigo, Frost, Pulse"
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Assigned Location (Node Handler / Lab Operator)</label>
                  <select
                    className="form-select"
                    value={newAssignedLocationId}
                    onChange={(e) => setNewAssignedLocationId(e.target.value)}
                  >
                    <option value="">-- No specific assigned facility --</option>
                    {locations.map((loc) => (
                      <option key={loc.id} value={loc.id}>
                        {loc.name} ({loc.code})
                      </option>
                    ))}
                  </select>
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Create User">
                  Create User
                </button>
              </form>
            </div>

            <div className="table-container">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Existing Users</h3>
              <table className="table">
                <thead>
                  <tr>
                    <th>User</th>
                    <th>Roles</th>
                    <th>Qualifications</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map((u) => (
                    <tr key={u.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{u.fullName || u.username}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>@{u.username}</div>
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: '2px', flexWrap: 'wrap' }}>
                          {u.roles.map((r) => (
                            <span key={r} className="badge badge-gray" style={{ fontSize: '0.7rem' }}>
                              {r.replace(/_/g, ' ')}
                            </span>
                          ))}
                        </div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem' }}>{u.qualifications?.join(', ') || 'None'}</div>
                      </td>
                      <td>
                        <span className={`badge ${u.active ? 'badge-success' : 'badge-danger'}`}>
                          {u.active ? 'Active' : 'Disabled'}
                        </span>
                      </td>
                      <td>
                        <button
                          className={`btn ${u.active ? 'btn-danger' : 'btn-success'} btn-sm`}
                          onClick={() => handleToggleUserActive(u)}
                        >
                          {u.active ? 'Disable' : 'Enable'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* LOCATIONS TAB */}
        {activeAdminTab === 'locations' && (
          <div className="grid grid-cols-2">
            <div>
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Create Location / Laboratory</h3>
              <form onSubmit={handleCreateLocation}>
                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Name</label>
                    <input
                      type="text"
                      className="form-input"
                      value={locName}
                      onChange={(e) => setLocName(e.target.value)}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Code</label>
                    <input
                      type="text"
                      className="form-input"
                      value={locCode}
                      onChange={(e) => setLocCode(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Latitude</label>
                    <input
                      type="number"
                      step="any"
                      className="form-input"
                      value={locLat}
                      onChange={(e) => setLocLat(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Longitude</label>
                    <input
                      type="number"
                      step="any"
                      className="form-input"
                      value={locLng}
                      onChange={(e) => setLocLng(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Functions</label>
                  <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                    <label><input type="checkbox" checked={locIsCollection} onChange={(e) => setLocIsCollection(e.target.checked)} /> Collection Point</label>
                    <label><input type="checkbox" checked={locIsTransfer} onChange={(e) => setLocIsTransfer(e.target.checked)} /> Transfer Point</label>
                    <label><input type="checkbox" checked={locIsHub} onChange={(e) => setLocIsHub(e.target.checked)} /> Hub</label>
                    <label><input type="checkbox" checked={locIsLab} onChange={(e) => setLocIsLab(e.target.checked)} /> Laboratory</label>
                  </div>
                </div>

                <div className="grid grid-cols-3">
                  <div className="form-group">
                    <label className="form-label">Reg Capacity</label>
                    <input
                      type="number"
                      className="form-input"
                      value={locRegCap}
                      onChange={(e) => setLocRegCap(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Cooled Capacity</label>
                    <input
                      type="number"
                      className="form-input"
                      value={locCoolCap}
                      onChange={(e) => setLocCoolCap(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Handling Mins</label>
                    <input
                      type="number"
                      className="form-input"
                      value={locHandlingMins}
                      onChange={(e) => setLocHandlingMins(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Accepted Sample Types (if Lab)</label>
                  <input
                    type="text"
                    className="form-input"
                    value={locAcceptedSamples}
                    onChange={(e) => setLocAcceptedSamples(e.target.value)}
                  />
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Create Location">
                  Create Location
                </button>
              </form>
            </div>

            <div className="table-container">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Network Nodes</h3>
              <table className="table">
                <thead>
                  <tr>
                    <th>Facility</th>
                    <th>Functions & Activation</th>
                    <th>Capacities</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {locations.map((loc) => (
                    <tr key={loc.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{loc.name}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{loc.code}</div>
                      </td>
                      <td>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', fontSize: '0.75rem' }}>
                          {loc.isCollectionPoint && (
                            <label>
                              <input
                                type="checkbox"
                                checked={loc.collectionActive}
                                onChange={() => handleToggleFunctionActive(loc, 'collection', loc.collectionActive)}
                              /> Collection
                            </label>
                          )}
                          {loc.isHub && (
                            <label>
                              <input
                                type="checkbox"
                                checked={loc.hubActive}
                                onChange={() => handleToggleFunctionActive(loc, 'hub', loc.hubActive)}
                              /> Hub
                            </label>
                          )}
                          {loc.isLaboratory && (
                            <label>
                              <input
                                type="checkbox"
                                checked={loc.laboratoryActive}
                                onChange={() => handleToggleFunctionActive(loc, 'laboratory', loc.laboratoryActive)}
                              /> Lab
                            </label>
                          )}
                        </div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem' }}>Reg: {loc.regularCapacity} | Cold: {loc.cooledCapacity}</div>
                      </td>
                      <td>
                        <button
                          className={`btn ${loc.active ? 'btn-danger' : 'btn-success'} btn-sm`}
                          onClick={() => handleToggleLocationActive(loc)}
                        >
                          {loc.active ? 'Deactivate' : 'Activate'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* CONNECTIONS TAB */}
        {activeAdminTab === 'connections' && (
          <div className="grid grid-cols-2">
            <div>
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Create Connection</h3>
              <form onSubmit={handleCreateConnection}>
                <div className="form-group">
                  <label className="form-label">From Location</label>
                  <select
                    className="form-select"
                    value={connFrom}
                    onChange={(e) => setConnFrom(e.target.value)}
                    required
                  >
                    {locations.map((l) => (
                      <option key={l.id} value={l.id}>{l.name} ({l.code})</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label">To Location</label>
                  <select
                    className="form-select"
                    value={connTo}
                    onChange={(e) => setConnTo(e.target.value)}
                    required
                  >
                    {locations.map((l) => (
                      <option key={l.id} value={l.id}>{l.name} ({l.code})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Distance (km)</label>
                    <input
                      type="number"
                      step="0.1"
                      className="form-input"
                      value={connDist}
                      onChange={(e) => setConnDist(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Transit Time (mins)</label>
                    <input
                      type="number"
                      className="form-input"
                      value={connTime}
                      onChange={(e) => setConnTime(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Regular Capacity</label>
                    <input
                      type="number"
                      className="form-input"
                      value={connRegCap}
                      onChange={(e) => setConnRegCap(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Cooled Capacity</label>
                    <input
                      type="number"
                      className="form-input"
                      value={connCoolCap}
                      onChange={(e) => setConnCoolCap(parseInt(e.target.value, 10))}
                      required
                    />
                  </div>
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Create Connection">
                  Create Connection
                </button>
              </form>
            </div>

            <div className="table-container">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Active Connections</h3>
              <table className="table">
                <thead>
                  <tr>
                    <th>From → To</th>
                    <th>Distance & Time</th>
                    <th>Capacity</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {connections.map((c) => (
                    <tr key={c.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>
                          {locations.find((l) => l.id === c.fromLocationId)?.code || c.fromLocationId} →{' '}
                          {locations.find((l) => l.id === c.toLocationId)?.code || c.toLocationId}
                        </div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem' }}>{c.distanceKm} km ({c.transitTimeMinutes} min)</div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem' }}>Reg: {c.regularCapacity} | Cold: {c.cooledCapacity}</div>
                      </td>
                      <td>
                        <button
                          className={`btn ${c.active ? 'btn-danger' : 'btn-success'} btn-sm`}
                          onClick={() => handleToggleConnection(c)}
                        >
                          {c.active ? 'Disable' : 'Enable'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* SAMPLE TYPES TAB */}
        {activeAdminTab === 'sampleTypes' && (
          <div className="grid grid-cols-2">
            <div>
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Create Sample Type</h3>
              <form onSubmit={handleCreateSampleType}>
                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Type Code</label>
                    <input
                      type="text"
                      className="form-input"
                      value={stCode}
                      onChange={(e) => setStCode(e.target.value)}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Type Name</label>
                    <input
                      type="text"
                      className="form-input"
                      value={stName}
                      onChange={(e) => setStName(e.target.value)}
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Container Type</label>
                  <input
                    type="text"
                    className="form-input"
                    value={stContainer}
                    onChange={(e) => setStContainer(e.target.value)}
                    required
                  />
                </div>

                <div className="grid grid-cols-2">
                  <div className="form-group">
                    <label className="form-label">Min Temp (°C)</label>
                    <input
                      type="number"
                      step="0.1"
                      className="form-input"
                      value={stMinTemp}
                      onChange={(e) => setStMinTemp(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Max Temp (°C)</label>
                    <input
                      type="number"
                      step="0.1"
                      className="form-input"
                      value={stMaxTemp}
                      onChange={(e) => setStMaxTemp(parseFloat(e.target.value))}
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <div style={{ display: 'flex', gap: '1rem' }}>
                    <label><input type="checkbox" checked={stRequiresCooled} onChange={(e) => setStRequiresCooled(e.target.checked)} /> Requires Cooled</label>
                    <label><input type="checkbox" checked={stRequiresQualified} onChange={(e) => setStRequiresQualified(e.target.checked)} /> Requires Qualified Collector</label>
                    <label><input type="checkbox" checked={stIsTimeCritical} onChange={(e) => setStIsTimeCritical(e.target.checked)} /> Time Critical (Pulse)</label>
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Incompatible Sample Types (comma-separated)</label>
                  <input
                    type="text"
                    className="form-input"
                    value={stIncompatibilities}
                    onChange={(e) => setStIncompatibilities(e.target.value)}
                    placeholder="e.g. Amber"
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Max Transit Time (minutes)</label>
                  <input
                    type="number"
                    className="form-input"
                    value={stMaxTransitTime}
                    onChange={(e) => setStMaxTransitTime(parseInt(e.target.value, 10))}
                    required
                  />
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Create Sample Type">
                  Create Sample Type
                </button>
              </form>
            </div>

            <div className="table-container">
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Configured Sample Types</h3>
              <table className="table">
                <thead>
                  <tr>
                    <th>Type</th>
                    <th>Container & Temp</th>
                    <th>Constraints</th>
                    <th>Incompatible</th>
                  </tr>
                </thead>
                <tbody>
                  {sampleTypes.map((st) => (
                    <tr key={st.id || st.code}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{st.name}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{st.code}</div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem' }}>{st.container}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--gray-600)' }}>{st.minTempC}°C - {st.maxTempC}°C</div>
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: '2px', flexWrap: 'wrap' }}>
                          {st.requiresCooled && <span className="badge badge-info">❄️ Cold</span>}
                          {st.requiresQualifiedCollector && <span className="badge badge-warning">⭐ Qualified</span>}
                          {st.isTimeCritical && <span className="badge badge-danger">⚡ Pulse</span>}
                        </div>
                      </td>
                      <td>
                        <div style={{ fontSize: '0.75rem', color: 'var(--danger)' }}>
                          {st.incompatibleSampleTypes?.join(', ') || 'None'}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
