import React, { useState, useEffect } from 'react';
import { useAuth } from './context/AuthContext';
import { LoginForm } from './components/LoginForm';
import { Navbar } from './components/Navbar';
import { RoleWorkView } from './components/RoleWorkView';
import { ServiceabilityCheck } from './components/ServiceabilityCheck';
import { CapacityManager } from './components/CapacityManager';
import { DispatcherDashboard } from './components/DispatcherDashboard';
import { AuditTrailView } from './components/AuditTrailView';
import { AdminPanel } from './components/AdminPanel';
import { api } from './api/client';
import { Location, NetworkConnection, SampleType, User } from './types';

export const AppContent: React.FC = () => {
  const { user, activeRole, isAuthenticated, isLoading } = useAuth();
  const [currentTab, setCurrentTab] = useState<string>('work');

  // Master network data
  const [locations, setLocations] = useState<Location[]>([]);
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([]);
  const [connections, setConnections] = useState<NetworkConnection[]>([]);
  const [usersList, setUsersList] = useState<User[]>([]);

  const loadBootstrapData = async () => {
    if (!isAuthenticated) return;
    try {
      const res = await api.getBootstrap();
      if (res.locations) setLocations(res.locations);
      if (res.sampleTypes) setSampleTypes(res.sampleTypes);
      if (res.connections) setConnections(res.connections);

      // If user is dispatcher or admin, fetch operations workers
      if (activeRole === 'dispatcher' || activeRole === 'administrator') {
        const ops = await api.getOperationsState();
        if (ops.workers) setUsersList(ops.workers);
      }
    } catch (err) {
      console.error('Failed to load bootstrap data:', err);
    }
  };

  useEffect(() => {
    if (isAuthenticated) {
      loadBootstrapData();
    }
  }, [isAuthenticated, activeRole]);

  // Adjust current tab if switching role to one that doesn't support the active tab
  useEffect(() => {
    if (currentTab === 'serviceability' && activeRole !== 'requester') {
      setCurrentTab('work');
    }
    if ((currentTab === 'operations' || currentTab === 'audit') && activeRole !== 'dispatcher' && activeRole !== 'administrator') {
      setCurrentTab('work');
    }
    if (currentTab === 'admin' && activeRole !== 'administrator') {
      setCurrentTab('work');
    }
  }, [activeRole]);

  if (isLoading) {
    return (
      <div style={{ display: 'flex', minHeight: '100vh', alignItems: 'center', justifyContent: 'center' }}>
        <p style={{ color: 'var(--gray-600)', fontSize: '1.125rem' }}>Loading application...</p>
      </div>
    );
  }

  if (!isAuthenticated || !user) {
    return <LoginForm />;
  }

  return (
    <div className="app-container">
      <Navbar currentTab={currentTab} onSelectTab={setCurrentTab} />

      <main className="main-content">
        {currentTab === 'work' && (
          <RoleWorkView
            activeRole={activeRole || user.roles[0] || 'requester'}
            currentUser={user}
            sampleTypes={sampleTypes}
            locations={locations}
            workers={usersList}
            onRefreshAll={loadBootstrapData}
          />
        )}

        {currentTab === 'serviceability' && (
          <ServiceabilityCheck sampleTypes={sampleTypes} locations={locations} />
        )}

        {currentTab === 'capacity' && (
          <CapacityManager
            locations={locations}
            connections={connections}
            currentUser={user}
            onRefresh={loadBootstrapData}
          />
        )}

        {currentTab === 'operations' && (
          <DispatcherDashboard
            locations={locations}
            connections={connections}
            sampleTypes={sampleTypes}
            workers={usersList}
            onRefreshAll={loadBootstrapData}
          />
        )}

        {currentTab === 'audit' && (
          <AuditTrailView workers={usersList} />
        )}

        {currentTab === 'admin' && (
          <AdminPanel
            users={usersList}
            locations={locations}
            connections={connections}
            sampleTypes={sampleTypes}
            onRefreshAll={loadBootstrapData}
          />
        )}
      </main>
    </div>
  );
};

