	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Fatalf("Server shutdown error: %v", err)
	}
	log.Printf("Server gracefully stopped")
}

func initInitialAdmin(db *sql.DB, username, password string) {
	var count int
	err := db.QueryRow("SELECT COUNT(*) FROM users WHERE username = $1", username).Scan(&count)
	if err == nil && count > 0 {
		return
	}

	admin := models.User{
		Username: username,
		Roles:    []string{models.RoleAdministrator, models.RoleDispatcher},
		Active:   true,
	}
	_, err = services.CreateUser(db, admin, password, "system", models.RoleAdministrator)
	if err != nil {
		log.Printf("Error creating initial admin: %v", err)
	} else {
		log.Printf("Initial admin user '%s' created successfully", username)
	}
}

