observation.old_content:
package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
	"labsystem/internal/models"
)

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrRoleNotHeld        = errors.New("role_not_held")
	ErrUserNotFound       = errors.New("not_found")
	ErrUsernameExists     = errors.New("username_exists")
	ErrUnauthorized       = errors.New("unauthorized")
	ErrForbidden          = errors.New("forbidden")
)

func Authenticate(db *sql.DB, username, password string) (*models.User, string, string, error) {
	var u models.User
	var certsJSON string
	var locId sql.NullString
	var lat, lng sql.NullFloat64
	var recAt sql.NullTime

	err := db.QueryRow(`
        SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units, assignment_count, recent_declines, latest_latitude, latest_longitude, location_recorded_at, created_at, updated_at
        FROM users
        WHERE username = $1
    `, username).Scan(
		&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		pq.Array(&u.Roles), pq.Array(&u.Qualifications), &certsJSON, &u.Active, &locId,
		&u.Available, &u.CapacityUnits, &u.AssignmentCount, &u.RecentDeclines,
		&lat, &lng, &recAt, &u.CreatedAt, &u.UpdatedAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, "", "", ErrInvalidCredentials
		}
		return nil, "", "", err
	}

	if !u.Active {
		return nil, "", "", ErrInvalidCredentials
	}

	if err := bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(password)); err != nil {
		return nil, "", "", ErrInvalidCredentials
	}

	if locId.Valid {
		u.AssignedLocationId = &locId.String
	}
	if lat.Valid {
		u.LatestLatitude = &lat.Float64
	}
	if lng.Valid {
		u.LatestLongitude = &lng.Float64
	}
	if recAt.Valid {
		u.LocationRecordedAt = &recAt.Time
	}
	_ = json.Unmarshal([]byte(certsJSON), &u.Certifications)

	activeRole := ""
	if len(u.Roles) > 0 {
		activeRole = u.Roles[0]
	}

	token := uuid.New().String()
	expiresAt := time.Now().Add(7 * 24 * time.Hour)

	_, err = db.Exec(`
        INSERT INTO sessions (token, user_id, active_role, created_at, expires_at)
        VALUES ($1, $2, $3, NOW(), $4)
    `, token, u.ID, activeRole, expiresAt)
	if err != nil {
		return nil, "", "", fmt.Errorf("failed to create session: %w", err)
	}

	RecordAudit(db, u.ID, activeRole, activeRole, "user_authenticated", "user", u.ID, true, map[string]interface{}{
		"username":   username,
		"activeRole": activeRole,
	})

	return &u, token, activeRole, nil
}

func SelectActiveRole(db *sql.DB, token, role string) (*models.User, string, error) {
	user, _, err := ValidateToken(db, token)
	if err != nil {
		return nil, "", err
	}

	held := false
	for _, r := range user.Roles {
		if r == role {
			held = true
			break
		}
	}
	if !held {
		return nil, "", ErrRoleNotHeld
	}

	_, err = db.Exec(`
        UPDATE sessions
        SET active_role = $1
        WHERE token = $2
    `, role, token)
	if err != nil {
		return nil, "", err
	}

	RecordAudit(db, user.ID, role, role, "role_selected", "user", user.ID, true, map[string]interface{}{
		"selectedRole": role,
	})

	return user, role, nil
}

func ValidateToken(db *sql.DB, token string) (*models.User, string, error) {
	if token == "" {
		return nil, "", ErrUnauthorized
	}

	var u models.User
	var certsJSON string
	var locId sql.NullString
	var lat, lng sql.NullFloat64
	var recAt sql.NullTime
	var activeRole string
	var expiresAt time.Time

	err := db.QueryRow(`
