package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/lib/pq"

	"labsystem/internal/models"
)

var (
	ErrAssignmentNotFound   = errors.New("not_found")
	ErrIneligibleWorker     = errors.New("ineligible_worker")
	ErrOfferNotOffered      = errors.New("offer_not_offered")
	ErrOfferNotAvailable    = errors.New("offer_not_available")
	ErrAssignmentTaken      = errors.New("assignment_taken")
	ErrAssignmentInactive   = errors.New("assignment_inactive")
	ErrWorkerUnavailable    = errors.New("worker_unavailable")
)

func FindEligibleWorker(db *sql.DB, kind, sampleTypeId string, locationId *string, excludedWorkerIds []string) (*models.User, error) {
	requiredRole := ""
	switch kind {
	case "collection":
		requiredRole = models.RoleCollectionProfessional
	case "transport":
		requiredRole = models.RoleDeliveryPartner
	case "node":
		requiredRole = models.RoleNodeHandler
	case "laboratory":
		requiredRole = models.RoleLaboratoryTeam
	default:
		requiredRole = models.RoleDeliveryPartner
	}

	var st *models.SampleType
	if sampleTypeId != "" {
		st, _ = GetSampleType(db, sampleTypeId)
	}

	rows, err := db.Query(`
        SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units, assignment_count, recent_declines, latest_latitude, latest_longitude, location_recorded_at, created_at, updated_at
        FROM users
        WHERE active = true AND available = true AND $1 = ANY(roles)
        ORDER BY assignment_count ASC, recent_declines ASC, created_at ASC
    `, requiredRole)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var u models.User
		var certsJSON string
		var locId sql.NullString
		var lat, lng sql.NullFloat64
		var recAt sql.NullTime

		if err := rows.Scan(
			&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
			pq.Array(&u.Roles), pq.Array(&u.Qualifications), &certsJSON, &u.Active, &locId,
			&u.Available, &u.CapacityUnits, &u.AssignmentCount, &u.RecentDeclines,
			&lat, &lng, &recAt, &u.CreatedAt, &u.UpdatedAt,
		); err != nil {
			return nil, err
		}

		if locId.Valid {
			u.AssignedLocationId = &locId.String
		}
		if lat.Valid {
			u.LatestLatitude = &lat.Float64
		}
		if lng.Valid {
			u.LatestLongitude = &lng.Float64
		}
		if recAt.Valid {
			u.LocationRecordedAt = &recAt.Time
		}
		_ = json.Unmarshal([]byte(certsJSON), &u.Certifications)

		// Check exclusion
		excluded := false
		for _, exId := range excludedWorkerIds {
			if exId == u.ID {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}

		// Check location match for node / lab
		if (kind == "node" || kind == "laboratory") && locationId != nil && *locationId != "" {
			if u.AssignedLocationId == nil || *u.AssignedLocationId != *locationId {
				continue
			}
		}

		// Check qualification for sample types
		if st != nil && st.QualifiedCollectorRequired && kind == "collection" {
			hasQual := false
			for _, q := range u.Qualifications {
				if q == st.RequiredQualification || q == st.Name || q == "certified_collector" {
					hasQual = true
					break
				}
			}
			if !hasQual {
				for _, c := range u.Certifications {
					if (c.Code == st.RequiredQualification || c.Code == st.Name || c.Code == "certified_collector") && c.Active {
						hasQual = true
						break
					}
				}
			}
			if !hasQual {
				continue
			}
		}

		return &u, nil
	}

	return nil, nil
}

func OfferAssignment(db *sql.DB, legId string, worker *models.User, actorId, actorRole string) error {
	expiresAt := time.Now().Add(15 * time.Minute)
	_, err := db.Exec(`
        UPDATE journey_legs
        SET worker_id = $1, status = 'offered', offer_expires_at = $2, updated_at = NOW()
        WHERE id = $3
    `, worker.ID, expiresAt, legId)
	if err != nil {
		return err
	}

	RecordAudit(db, actorId, actorRole, actorRole, "assignment_offered", "journey_leg", legId, true, map[string]interface{}{
		"workerId":       worker.ID,
		"offerExpiresAt": expiresAt.Format(time.RFC3339),
	})

	BroadcastEvent(db, "assignment_offered", "journey_leg", legId, map[string]interface{}{
		"workerId":       worker.ID,
		"offerExpiresAt": expiresAt.Format(time.RFC3339),
	})

	return nil
}

func AcceptAssignment(db *sql.DB, assignmentId, workerId, actorRole string) (map[string]interface{}, error) {
	var currentWorkerId sql.NullString
	var status string
	var expiresAt sql.NullTime
	var sampleId sql.NullString

	err := db.QueryRow(`
        SELECT worker_id, status, offer_expires_at, sample_id
        FROM journey_legs
        WHERE id = $1
    `, assignmentId).Scan(&currentWorkerId, &status, &expiresAt, &sampleId)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrAssignmentNotFound
		}
		return nil, err
	}

	if status == "accepted" || status == "in_transit" || status == "completed" {
		if currentWorkerId.Valid && currentWorkerId.String != workerId {
			return nil, ErrAssignmentTaken
		}
		return map[string]interface{}{
			"assignmentId": assignmentId,
			"workerId":     workerId,
			"status":       "accepted",
		}, nil
	}

	if status == "cancelled" || status == "replaced" {
		return nil, ErrAssignmentInactive
	}

	if !currentWorkerId.Valid || currentWorkerId.String != workerId {
		return nil, ErrOfferNotOffered
	}

	if expiresAt.Valid && time.Now().After(expiresAt.Time) {
		return nil, ErrOfferNotAvailable
	}

	_, err = db.Exec(`
        UPDATE journey_legs
        SET status = 'accepted', updated_at = NOW()
        WHERE id = $1
    `, assignmentId)
	if err != nil {
		return nil, err
	}

	_, _ = db.Exec(`
        UPDATE users
        SET assignment_count = assignment_count + 1, updated_at = NOW()
        WHERE id = $1
    `, workerId)

	RecordAudit(db, workerId, actorRole, actorRole, "assignment_accepted", "journey_leg", assignmentId, true, map[string]interface{}{
		"workerId": workerId,
		"status":   "accepted",
	})

	BroadcastEvent(db, "assignment_accepted", "journey_leg", assignmentId, map[string]interface{}{
		"workerId": workerId,
		"status":   "accepted",
	})

	return map[string]interface{}{
		"assignmentId": assignmentId,
		"workerId":     workerId,
		"status":       "accepted",
	}, nil
}

func DeclineAssignment(db *sql.DB, assignmentId, workerId, reason string, declinedAt time.Time, actorRole string) (map[string]interface{}, error) {
	var currentWorkerId sql.NullString
	var status, kind, fromLocId, toLocId string
	var sampleId sql.NullString
	var declinedWorkers []string

	err := db.QueryRow(`
        SELECT worker_id, status, kind, from_location_id, to_location_id, sample_id, declined_worker_ids
        FROM journey_legs
        WHERE id = $1
    `, assignmentId).Scan(&currentWorkerId, &status, &kind, &fromLocId, &toLocId, &sampleId, &declinedWorkers)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrAssignmentNotFound
		}
		return nil, err
	}

	if !currentWorkerId.Valid || currentWorkerId.String != workerId {
		return nil, ErrOfferNotAvailable
	}

	declinedWorkers = append(declinedWorkers, workerId)
	_, _ = db.Exec(`
        UPDATE users
        SET recent_declines = recent_declines + 1, updated_at = NOW()
        WHERE id = $1
    `, workerId)

	var sampleTypeId string
	if sampleId.Valid {
		_ = db.QueryRow("SELECT sample_type_id FROM samples WHERE id = $1", sampleId.String).Scan(&sampleTypeId)
	}

	locToMatch := &fromLocId
	if kind == "laboratory" {
		locToMatch = &toLocId
	}

	nextWorker, _ := FindEligibleWorker(db, kind, sampleTypeId, locToMatch, declinedWorkers)

	var reofferedTo *string
	if nextWorker != nil {
		reofferedTo = &nextWorker.ID
		expiresAt := time.Now().Add(15 * time.Minute)
		_, err = db.Exec(`
            UPDATE journey_legs
            SET worker_id = $1, status = 'offered', offer_expires_at = $2, declined_worker_ids = $3, updated_at = NOW()
            WHERE id = $4
        `, nextWorker.ID, expiresAt, declinedWorkers, assignmentId)
	} else {
		// No worker available - flag exception on sample
		_, err = db.Exec(`
            UPDATE journey_legs
            SET worker_id = NULL, status = 'pending', offer_expires_at = NULL, declined_worker_ids = $1, updated_at = NOW()
            WHERE id = $2
        `, declinedWorkers, assignmentId)

		if sampleId.Valid {
			excJSON, _ := json.Marshal(map[string]interface{}{
				"type":   "no_worker_available",
				"reason": "No eligible worker available after assignment decline",
				"time":   time.Now().Format(time.RFC3339),
			})
			_, _ = db.Exec(`
                UPDATE samples
                SET status = 'exception', exception = $1, updated_at = NOW()
                WHERE id = $2
            `, string(excJSON), sampleId.String)
		}
	}

	RecordAudit(db, workerId, actorRole, actorRole, "assignment_declined", "journey_leg", assignmentId, true, map[string]interface{}{
		"declinedBy":  workerId,
		"reason":      reason,
		"reofferedTo": reofferedTo,
	})

	BroadcastEvent(db, "assignment_declined", "journey_leg", assignmentId, map[string]interface{}{
		"declinedBy":  workerId,
		"reofferedTo": reofferedTo,
	})

	asgnStatus := "declined"
	if reofferedTo != nil {
		asgnStatus = "reoffered"
	}

	res := map[string]interface{}{
		"assignmentId": assignmentId,
		"status":       asgnStatus,
		"declinedBy":   workerId,
		"declinedAt":   declinedAt.Format(time.RFC3339),
	}
	if reofferedTo != nil {
		res["reofferedTo"] = *reofferedTo
	}
	return res, nil
}

func SetWorkerAvailability(db *sql.DB, workerId string, available bool, capacityUnits int, actorId, actorRole string) error {
	if capacityUnits < 0 {
		return errors.New("invalid_capacity")
	}

	res, err := db.Exec(`
        UPDATE users
        SET available = $1, capacity_units = $2, updated_at = NOW()
        WHERE id = $3
    `, available, capacityUnits, workerId)
	if err != nil {
		return err
	}
	rowsAffected, _ := res.RowsAffected()
	if rowsAffected == 0 {
		return errors.New("not_found")
	}

	RecordAudit(db, actorId, actorRole, actorRole, "worker_availability_updated", "user", workerId, true, map[string]interface{}{
		"available":     available,
		"capacityUnits": capacityUnits,
	})

	return nil
}

func GetRoleWork(db *sql.DB, userId, role, statusFilter string) (*models.RoleWork, error) {
	roleWork := &models.RoleWork{
		Pending:    make([]interface{}, 0),
		InProgress: make([]interface{}, 0),
		Completed:  make([]interface{}, 0),
	}

	if role == models.RoleRequester {
		rows, err := db.Query(`
			SELECT s.id, s.request_id, s.status, s.delivery_deadline, s.active_journey_id, s.target_laboratory_id, s.current_holder_id,
			       s.requester_id, s.latest_latitude, s.latest_longitude, s.location_recorded_at,
			       r.earliest_collection_at, r.latest_collection_at, r.serviceability, r.created_at
			FROM samples s
			JOIN requests r ON s.request_id = r.id
			WHERE s.requester_id = $1
			ORDER BY s.created_at DESC
		`, userId)
		if err != nil {
			return nil, err
		}
		defer rows.Close()

		for rows.Next() {
			var (
				sId, rId, sStatus, dDeadline string
				jId, labId, holderId, reqId  sql.NullString
				lat, lon                     sql.NullFloat64
				locRecAt                     sql.NullTime
				earliestColl, latestColl     sql.NullTime
				serviceability               sql.NullString
				createdAt                    time.Time
			)
			if err := rows.Scan(&sId, &rId, &sStatus, &dDeadline, &jId, &labId, &holderId, &reqId, &lat, &lon, &locRecAt, &earliestColl, &latestColl, &serviceability, &createdAt); err != nil {
				continue
			}

			timeline, _ := GetSampleTimeline(db, sId)
			locStale := false
			var locRecAtStr *string
			if locRecAt.Valid {
				s := locRecAt.Time.Format(time.RFC3339)
				locRecAtStr = &s
				if time.Since(locRecAt.Time) > 15*time.Minute {
					locStale = true
				}
			}

			var ecStr, lcStr, servStr *string
			if earliestColl.Valid {
				s := earliestColl.Time.Format(time.RFC3339)
				ecStr = &s
			}
			if latestColl.Valid {
				s := latestColl.Time.Format(time.RFC3339)
				lcStr = &s
			}
			if serviceability.Valid {
				servStr = &serviceability.String
			}
			var jIdStr, labIdStr, holderIdStr, reqIdStr *string
			if jId.Valid {
				jIdStr = &jId.String
			}
			if labId.Valid {
				labIdStr = &labId.String
			}
			if holderId.Valid {
				holderIdStr = &holderId.String
			}
			if reqId.Valid {
				reqIdStr = &reqId.String
			}

			reqAtStr := createdAt.Format(time.RFC3339)

			item := models.SampleWorkItem{
				Kind:                 "sample",
				SampleId:             sId,
				Sample_Id:            sId,
				RequestId:            rId,
				Status:               sStatus,
				Serviceability:       servStr,
				RequestedAt:          &reqAtStr,
				DeliveryDeadline:     &dDeadline,
				EarliestCollectionAt: ecStr,
				LatestCollectionAt:   lcStr,
				JourneyId:            jIdStr,
				ActiveJourneyId:      jIdStr,
				LaboratoryId:         labIdStr,
				CurrentHolderId:      holderIdStr,
				RequesterId:          reqIdStr,
				History:              timeline,
				LocationRecordedAt:   locRecAtStr,
				LocationStale:        locStale,
			}

			switch sStatus {
			case "pending", "created":
				roleWork.Pending = append(roleWork.Pending, item)
			case "collected", "in_transit", "handoff_pending", "processing":
				roleWork.InProgress = append(roleWork.InProgress, item)
			case "received", "delivered", "completed", "cancelled", "exception", "expired":
				roleWork.Completed = append(roleWork.Completed, item)
			default:
				roleWork.InProgress = append(roleWork.InProgress, item)
			}
		}
		return roleWork, nil
	}

	var query string
	var args []interface{}

	if role == models.RoleAdministrator || role == models.RoleDispatcher {
		query = `
			SELECT jl.id, jl.journey_id, jl.sample_id, jl.kind, jl.sequence, jl.status,
			       jl.from_location_id, jl.to_location_id, jl.offer_expires_at, jl.created_at
			FROM journey_legs jl
			ORDER BY jl.created_at DESC
		`
	} else {
		query = `
			SELECT jl.id, jl.journey_id, jl.sample_id, jl.kind, jl.sequence, jl.status,
			       jl.from_location_id, jl.to_location_id, jl.offer_expires_at, jl.created_at
			FROM journey_legs jl
			WHERE jl.worker_id = $1
			ORDER BY jl.created_at DESC
		`
		args = append(args, userId)
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var (
			asgnId, kind, status string
			jId, sId, fromLoc, toLoc sql.NullString
			seq sql.NullInt64
			offerExp sql.NullTime
			createdAt time.Time
		)
		if err := rows.Scan(&asgnId, &jId, &sId, &kind, &seq, &status, &fromLoc, &toLoc, &offerExp, &createdAt); err != nil {
			continue
		}

		sampleIdStr := ""
		if sId.Valid {
			sampleIdStr = sId.String
		}

		timeline, _ := GetAssignmentTimeline(db, asgnId)
		if len(timeline) == 0 && sampleIdStr != "" {
			timeline, _ = GetSampleTimeline(db, sampleIdStr)
		}

		var jIdStr, fromLocStr, toLocStr *string
		if jId.Valid {
			jIdStr = &jId.String
		}
		if fromLoc.Valid {
			fromLocStr = &fromLoc.String
		}
		if toLoc.Valid {
			toLocStr = &toLoc.String
		}

		var seqInt *int
		if seq.Valid {
			n := int(seq.Int64)
			seqInt = &n
		}

		var offerExpStr *string
		if offerExp.Valid {
			s := offerExp.Time.Format(time.RFC3339)
			offerExpStr = &s
		}

		var destCap *models.Capacity
		var labIdStr *string
		var expSampleType *string
		var nodeLocIdStr *string

		if kind == "laboratory" && toLoc.Valid {
			labIdStr = &toLoc.String
			if sampleIdStr != "" {
				_ = db.QueryRow("SELECT sample_type_id FROM samples WHERE id = $1", sampleIdStr).Scan(&expSampleType)
			}
			destCap, _ = GetLocationCapacity(db, toLoc.String)
		} else if kind == "node" && fromLoc.Valid {
			nodeLocIdStr = &fromLoc.String
			destCap, _ = GetLocationCapacity(db, fromLoc.String)
		} else if toLoc.Valid {
			destCap, _ = GetLocationCapacity(db, toLoc.String)
		}

		item := models.AssignmentWorkItem{
			Kind:                   kind,
			AssignmentId:           asgnId,
			Assignment_Id:          asgnId,
			SampleId:               sampleIdStr,
			Sample_Id:              sampleIdStr,
			Status:                 status,
			JourneyId:              jIdStr,
			FromLocationId:         fromLocStr,
			ToLocationId:           toLocStr,
			Sequence:               seqInt,
			OfferExpiresAt:         offerExpStr,
			DestinationCapacity:    destCap,
			NodeId:                 nodeLocIdStr,
			IncomingFromLocationId: fromLocStr,
			OutgoingToLocationId:   toLocStr,
			LaboratoryId:           labIdStr,
			ExpectedSampleTypeId:   expSampleType,
			History:                timeline,
		}

		switch status {
		case "offered", "pending":
			roleWork.Pending = append(roleWork.Pending, item)
		case "accepted", "in_transit", "handoff_pending":
			roleWork.InProgress = append(roleWork.InProgress, item)
		case "completed", "delivered", "declined", "cancelled":
			roleWork.Completed = append(roleWork.Completed, item)
		default:
			roleWork.InProgress = append(roleWork.InProgress, item)
		}
	}

	return roleWork, nil
}

func GetOperationsState(db *sql.DB, filter models.OperationsFilter) (*models.OperationsState, error) {
	state := &models.OperationsState{
		Samples:                   make([]map[string]interface{}, 0),
		Workers:                   make([]models.OperationsWorker, 0),
		Locations:                 make([]models.OperationsLocation, 0),
		Connections:               make([]models.OperationsConnection, 0),
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  make([]map[string]interface{}, 0),
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                make([]map[string]interface{}, 0),
		AssignmentCountSpread:     0,
		IneligibleAssignmentCount: 0,
	}

	// 1. Samples
	sampleRows, err := db.Query(`
		SELECT s.id, s.request_id, s.status, s.delivery_deadline, s.active_journey_id,
		       s.current_holder_id, s.latest_latitude, s.latest_longitude, s.location_recorded_at,
		       r.origin_lat, r.origin_lon, s.exception
		FROM samples s
		JOIN requests r ON s.request_id = r.id
		ORDER BY s.created_at DESC
	`)
	if err == nil {
		defer sampleRows.Close()
		for sampleRows.Next() {
			var (
				sId, rId, sStatus, dDeadline string
				jId, holderId                sql.NullString
				lat, lon                     sql.NullFloat64
				locRecAt                     sql.NullTime
				origLat, origLon             float64
				exc                          sql.NullString
			)
			if err := sampleRows.Scan(&sId, &rId, &sStatus, &dDeadline, &jId, &holderId, &lat, &lon, &locRecAt, &origLat, &origLon, &exc); err != nil {
				continue
			}

			locStale := false
			var locRecAtStr *string
			if locRecAt.Valid {
				s := locRecAt.Time.Format(time.RFC3339)
				locRecAtStr = &s
				if time.Since(locRecAt.Time) > 15*time.Minute {
					locStale = true
				}
			}

			sObj := map[string]interface{}{
				"sampleId":         sId,
				"sample_id":        sId,
				"requestId":        rId,
				"status":           sStatus,
				"deliveryDeadline": dDeadline,
				"locationStale":    locStale,
				"origin": models.Coordinate{
					Latitude:  origLat,
					Longitude: origLon,
				},
			}
			if holderId.Valid {
				sObj["currentHolderId"] = holderId.String
			}
			if jId.Valid {
				sObj["activeJourneyId"] = jId.String
			}
			if lat.Valid && lon.Valid {
				sObj["latestLocation"] = models.Coordinate{
					Latitude:  lat.Float64,
					Longitude: lon.Float64,
				}
			}
			if locRecAtStr != nil {
				sObj["locationRecordedAt"] = *locRecAtStr
			}

			state.Samples = append(state.Samples, sObj)

			if sStatus == "exception" || (exc.Valid && exc.String != "" && exc.String != "{}") {
				var excMap map[string]interface{}
				if exc.Valid {
					_ = json.Unmarshal([]byte(exc.String), &excMap)
				}
				state.Exceptions = append(state.Exceptions, map[string]interface{}{
					"sampleId":  sId,
					"status":    sStatus,
					"exception": excMap,
				})
			}
		}
	}

	// 2. Workers
	workerRows, err := db.Query(`
		SELECT id, full_name, roles, available, capacity_units, assignment_count,
		       latest_latitude, latest_longitude, location_recorded_at
		FROM users
		WHERE active = TRUE AND array_length(roles, 1) > 0
		ORDER BY username
	`)
	minCount := 999999
	maxCount := 0
	workerCount := 0
	if err == nil {
		defer workerRows.Close()
		for workerRows.Next() {
			var (
				wId               string
				fn                sql.NullString
				roles             []string
				avail             bool
				capUnits, asgnCnt int
				lat, lon          sql.NullFloat64
				locRecAt          sql.NullTime
			)
			if err := workerRows.Scan(&wId, &fn, pq.Array(&roles), &avail, &capUnits, &asgnCnt, &lat, &lon, &locRecAt); err != nil {
				continue
			}

			wStatus := "unavailable"
			if avail {
				wStatus = "available"
			}

			locStale := false
			var locRecAtStr *string
			if locRecAt.Valid {
				s := locRecAt.Time.Format(time.RFC3339)
				locRecAtStr = &s
				if time.Since(locRecAt.Time) > 15*time.Minute {
					locStale = true
				}
			}

			var coord *models.Coordinate
			if lat.Valid && lon.Valid {
				coord = &models.Coordinate{Latitude: lat.Float64, Longitude: lon.Float64}
			}

			var fnStr *string
			if fn.Valid {
				fnStr = &fn.String
			}

			workerObj := models.OperationsWorker{
				WorkerId:           wId,
				Worker_Id:          wId,
				FullName:           fnStr,
				Roles:              roles,
				Available:          avail,
				Status:             wStatus,
				CapacityUnits:      capUnits,
				AssignmentCount:    asgnCnt,
				LatestLocation:     coord,
				Latest_Location:    coord,
				LocationRecordedAt: locRecAtStr,
				LocationStale:      locStale,
			}

			state.Workers = append(state.Workers, workerObj)

			if asgnCnt < minCount {
				minCount = asgnCnt
			}
			if asgnCnt > maxCount {
				maxCount = asgnCnt
			}
			workerCount++
		}
	}
	if workerCount > 0 {
		state.AssignmentCountSpread = maxCount - minCount
	}

	// 3. Locations
	locations, _ := GetAllLocations(db)
	for _, loc := range locations {
		cap, _ := GetLocationCapacity(db, loc.LocationId)
		acceptedTypes, _ := GetLocationAcceptedSampleTypes(db, loc.LocationId)
		state.Locations = append(state.Locations, models.OperationsLocation{
			ID:                    loc.LocationId,
			LocationId:            loc.LocationId,
			Name:                  loc.Name,
			Coordinate:            loc.Coordinate,
			Active:                loc.Active,
			CoverageKm:            loc.CoverageKm,
			HandlingMinutes:       loc.HandlingMinutes,
			Functions:             loc.Functions,
			Capacity:              cap,
			AcceptedSampleTypeIds: acceptedTypes,
		})
	}

	// 4. Connections
	connections, _ := GetAllConnections(db)
	for _, conn := range connections {
		cap, _ := GetConnectionCapacity(db, conn.ID)
		state.Connections = append(state.Connections, models.OperationsConnection{
			ID:             conn.ID,
			ConnectionId:   conn.ID,
			FromLocationId: conn.FromLocationId,
			ToLocationId:   conn.ToLocationId,
			TravelMinutes:  conn.TravelMinutes,
			CostUnits:      conn.CostUnits,
			Cooled:         conn.Cooled,
			Active:         conn.Active,
			Capacity:       cap,
		})
	}

	// 5. Routes (Active Journeys)
	journeyRows, err := db.Query(`
		SELECT id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids
		FROM journeys
		ORDER BY created_at DESC
	`)
	if err == nil {
		defer journeyRows.Close()
		for journeyRows.Next() {
			var (
				jId, mode, status string
				ver               int
				estDel            sql.NullTime
				cost              sql.NullFloat64
				sIds              []string
			)
			if err := journeyRows.Scan(&jId, &ver, &mode, &status, &estDel, &cost, pq.Array(&sIds)); err != nil {
				continue
			}
			jObj := map[string]interface{}{
				"journeyId":   jId,
				"planVersion": ver,
				"routeMode":   mode,
				"status":      status,
				"sampleIds":   sIds,
			}
			if estDel.Valid {
				jObj["estimatedDeliveryAt"] = estDel.Time.Format(time.RFC3339)
			}
			if cost.Valid {
				jObj["totalCostUnits"] = cost.Float64
			}
			state.Routes = append(state.Routes, jObj)
		}
	}

	// 6. Handoffs (Pending handoffs)
	handoffRows, err := db.Query(`
		SELECT h.id, h.sample_id, h.from_user_id, h.to_user_id, h.location_id, h.status, h.created_at
		FROM handoffs h
		WHERE h.status = 'pending'
		ORDER BY h.created_at DESC
	`)
	if err == nil {
		defer handoffRows.Close()
		for handoffRows.Next() {
			var (
				hId, sId, fromUser, toUser, status string
				locId                              sql.NullString
				createdAt                          time.Time
			)
			if err := handoffRows.Scan(&hId, &sId, &fromUser, &toUser, &locId, &status, &createdAt); err != nil {
				continue
			}
			hObj := map[string]interface{}{
				"handoffId":  hId,
				"sampleId":   sId,
				"fromUserId": fromUser,
				"toUserId":   toUser,
				"status":     status,
				"createdAt":  createdAt.Format(time.RFC3339),
			}
			if locId.Valid {
				hObj["locationId"] = locId.String
			}
			state.Handoffs = append(state.Handoffs, hObj)
		}
	}

	// Ineligible assignment count
	var ineligCount int
	_ = db.QueryRow("SELECT COUNT(*) FROM journey_legs WHERE array_length(declined_worker_ids, 1) > 0").Scan(&ineligCount)
	state.IneligibleAssignmentCount = ineligCount

	return state, nil
}

