			&conn.FromLocationId,
			&conn.ToLocationId,
			&conn.TravelMinutes,
			&conn.CostUnits,
			&conn.Cooled,
			&conn.Active,
		); err != nil {
			continue
		}
		conn.ConnectionId = conn.ID
		conns = append(conns, conn)
	}
	return conns, nil
}

func GetLocationCapacity(db *sql.DB, locationId string) (*models.Capacity, error) {
	var cap models.Capacity
	err := db.QueryRow(`
        SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM locations
        WHERE id = $1
    `, locationId).Scan(&cap.CapacityUnits, &cap.ReservedUnits, &cap.CooledCapacityUnits, &cap.CooledReservedUnits)
	if err != nil {
		return nil, nil
	}
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
	if cap.AvailableUnits < 0 {
		cap.AvailableUnits = 0
	}
	cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
	if cap.CooledAvailableUnits < 0 {
		cap.CooledAvailableUnits = 0
	}
	return &cap, nil
}

func GetConnectionCapacity(db *sql.DB, connectionId string) (*models.Capacity, error) {
	var cap models.Capacity
	err := db.QueryRow(`
        SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM connections
        WHERE id = $1
    `, connectionId).Scan(&cap.CapacityUnits, &cap.ReservedUnits, &cap.CooledCapacityUnits, &cap.CooledReservedUnits)
	if err != nil {
		return nil, nil
	}
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
	if cap.AvailableUnits < 0 {
		cap.AvailableUnits = 0
	}
	cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
	if cap.CooledAvailableUnits < 0 {
		cap.CooledAvailableUnits = 0
	}
	return &cap, nil
}

func GetLocationAcceptedSampleTypes(db *sql.DB, locationId string) ([]string, error) {
	var accepted []string
	err := db.QueryRow(`
        SELECT accepted_sample_types
        FROM locations
        WHERE id = $1 AND function_laboratory = true
    `, locationId).Scan(pq.Array(&accepted))
	if err != nil {
		return nil, err
	}
	return accepted, nil
}"}

