func ConfigureCapacity(db *sql.DB, resourceId string, capacityUnits int, cooledCapacityUnits *int, actorId, actorRole string) (*int, error) {
	if capacityUnits < 0 || (cooledCapacityUnits != nil && *cooledCapacityUnits < 0) {
		return nil, ErrInvalidCapacity
	}

	// Try Location first
	var reservedUnits, cooledReservedUnits int
	err := db.QueryRow("SELECT reserved_units, cooled_reserved_units FROM locations WHERE id = $1", resourceId).Scan(&reservedUnits, &cooledReservedUnits)
	if err == nil {
		if capacityUnits < reservedUnits {
			return nil, ErrCapacityReserved
		}
		if cooledCapacityUnits != nil && *cooledCapacityUnits < cooledReservedUnits {
			return nil, ErrCapacityReserved
		}

		cCap := 0
		if cooledCapacityUnits != nil {
			cCap = *cooledCapacityUnits
			_, err = db.Exec("UPDATE locations SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW() WHERE id = $3", capacityUnits, cCap, resourceId)
		} else {
			_, err = db.Exec("UPDATE locations SET capacity_units = $1, updated_at = NOW() WHERE id = $2", capacityUnits, resourceId)
		}
		if err != nil {
			return nil, err
		}

		RecordAudit(db, actorId, actorRole, actorRole, "capacity_configured", "location", resourceId, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_ = RecomputeAndPublishSnapshot(db)
		return cooledCapacityUnits, nil
	}

	// Try Connection
	err = db.QueryRow("SELECT reserved_units, cooled_reserved_units FROM connections WHERE id = $1", resourceId).Scan(&reservedUnits, &cooledReservedUnits)
	if err == nil {
		if capacityUnits < reservedUnits {
			return nil, ErrCapacityReserved
		}
		if cooledCapacityUnits != nil && *cooledCapacityUnits < cooledReservedUnits {
			return nil, ErrCapacityReserved
		}

		if cooledCapacityUnits != nil {
			_, err = db.Exec("UPDATE connections SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW() WHERE id = $3", capacityUnits, *cooledCapacityUnits, resourceId)
		} else {
			_, err = db.Exec("UPDATE connections SET capacity_units = $1, updated_at = NOW() WHERE id = $2", capacityUnits, resourceId)
		}
		if err != nil {
			return nil, err
		}

		RecordAudit(db, actorId, actorRole, actorRole, "capacity_configured", "connection", resourceId, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_ = RecomputeAndPublishSnapshot(db)
		return cooledCapacityUnits, nil
	}

	return nil, ErrLocationNotFound
}

func ConfigureLaboratoryAcceptance(db *sql.DB, laboratoryId, sampleTypeId string, accepts bool, actorId, actorRole string) (string, error) {
	var currentAccepted []string
	var isLab bool
	err := db.QueryRow("SELECT function_laboratory, accepted_sample_types FROM locations WHERE id = $1", laboratoryId).Scan(&isLab, &currentAccepted)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", ErrLocationNotFound
		}
		return "", err
	}
	if !isLab {
		return "", ErrLocationNotFound
	}

	newAccepted := make([]string, 0)
	if accepts {
		exists := false
		for _, id := range currentAccepted {
			if id == sampleTypeId {
				exists = true
			}
			newAccepted = append(newAccepted, id)
		}
		if !exists {
			newAccepted = append(newAccepted, sampleTypeId)
		}
	} else {
		for _, id := range currentAccepted {
			if id != sampleTypeId {
				newAccepted = append(newAccepted, id)
			}
		}
	}

	_, err = db.Exec("UPDATE locations SET accepted_sample_types = $1, updated_at = NOW() WHERE id = $2", newAccepted, laboratoryId)
	if err != nil {
		return "", err
	}

	RecordAudit(db, actorId, actorRole, actorRole, "laboratory_acceptance_configured", "location", laboratoryId, true, map[string]interface{}{
		"sampleTypeId": sampleTypeId,
		"accepts":      accepts,
	})

