        FROM location_capacities
        WHERE location_id = $1
    `, locationId).Scan(&cap.CapacityUnits, &cap.ReservedUnits, &cap.CooledCapacityUnits, &cap.CooledReservedUnits)
	if err != nil {
		return nil, nil
	}
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
	if cap.AvailableUnits < 0 {
		cap.AvailableUnits = 0
	}
	cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
	if cap.CooledAvailableUnits < 0 {
