func GetAllLocations(db *sql.DB) ([]models.Location, error) {
	rows, err := db.Query(`
        SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
               function_collection_point, function_transfer_point, function_hub, function_laboratory
        FROM locations
        ORDER BY name
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var locs []models.Location
	for rows.Next() {
		var loc models.Location
		if err := rows.Scan(
			&loc.LocationId,
			&loc.Name,
			&loc.Coordinate.Latitude,
			&loc.Coordinate.Longitude,
			&loc.CoverageKm,
			&loc.HandlingMinutes,
			&loc.Active,
			&loc.Functions.CollectionPoint,
			&loc.Functions.TransferPoint,
			&loc.Functions.Hub,
			&loc.Functions.Laboratory,
		); err != nil {
			continue
		}
		locs = append(locs, loc)
	}
	return locs, nil
}

func GetAllConnections(db *sql.DB) ([]models.OperationsConnection, error) {
	rows, err := db.Query(`
        SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active
        FROM connections
        ORDER BY created_at
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var conns []models.OperationsConnection
	for rows.Next() {
		var conn models.OperationsConnection
		if err := rows.Scan(
			&conn.ID,
			&conn.FromLocationId,
			&conn.ToLocationId,
			&conn.TravelMinutes,
			&conn.CostUnits,
			&conn.Cooled,
			&conn.Active,
		); err != nil {
			continue
		}
		conn.ConnectionId = conn.ID
		conns = append(conns, conn)
	}
	return conns, nil
}

func GetLocationCapacity(db *sql.DB, locationId string) (*models.Capacity, error) {
	var cap models.Capacity
	err := db.QueryRow(`
        SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM locations
        WHERE id = $1
    `, locationId).Scan(&cap.CapacityUnits, &cap.ReservedUnits, &cap.CooledCapacityUnits, &cap.CooledReservedUnits)
	if err != nil {
		return nil, nil
	}
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
	if cap.AvailableUnits < 0 {
		cap.AvailableUnits = 0
	}
	cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
	if cap.CooledAvailableUnits < 0 {
		cap.CooledAvailableUnits = 0
	}
	return &cap, nil
}

