	"labsystem/internal/models"
)

var (
	ErrSampleNotFound            = errors.New("not_found")
	ErrPresealedHomeOriginReject = errors.New("presealed_sample_home_origin_rejected")
	ErrSampleException           = errors.New("sample_exception")
	ErrInvalidTransition         = errors.New("invalid_sample_state")
	ErrOutsideCollectionWindow   = errors.New("collection_window_missed")
