		earT = *earliest
	} else {
		earT = requestedAt
	}
	if latest != nil {
		latT = *latest
	} else {
		latT = deadline
	}

	serviceable, reason, labIdPtr, _, _, err := CheckServiceability(db, origin, originType, originNodeId, sampleTypeId, requestedAt, deadline, earT, latT)
	if err != nil {
		return nil, err
	}

	requestId := uuid.New().String()
	sampleId := uuid.New().String()

