func GetSampleState(db *sql.DB, sampleId string) (*models.SampleState, error) {
	var s models.SampleState
	var reqId, reqUser, origType, stId, cType, serv string
	var reqAt, delDead time.Time
	var origLat, origLng, tMin, tMax float64
	var incomp []string
	var actJId, targetLab sql.NullString
	var lat, lng sql.NullFloat64
	var recAt sql.NullTime
	var sampleStatus string

	err := db.QueryRow(`
        SELECT s.id, s.request_id, s.requester_id, s.sample_type_id, s.status, s.active_journey_id, s.target_laboratory_id, s.latest_latitude, s.latest_longitude, s.location_recorded_at,
               r.origin_lat, r.origin_lng, r.origin_type, r.requested_at, r.delivery_deadline, r.container_type, r.temperature_min_c, r.temperature_max_c, r.incompatible_sample_types, r.serviceability
        FROM samples s
        JOIN collection_requests r ON s.request_id = r.id
        WHERE s.id = $1
    `, sampleId).Scan(
		&s.SampleId, &reqId, &reqUser, &stId, &sampleStatus, &actJId, &targetLab, &lat, &lng, &recAt,
		&origLat, &origLng, &origType, &reqAt, &delDead, &cType, &tMin, &tMax, pq.Array(&incomp), &serv,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleNotFound
		}
		return nil, err
	}

	s.RequestId = reqId
	s.RequesterId = reqUser
	s.SampleTypeId = stId
	s.State.Status = sampleStatus
	s.Origin = models.Coordinate{Latitude: origLat, Longitude: origLng}
	s.OriginType = origType
	s.RequestedAt = reqAt.Format(time.RFC3339)
	s.DeliveryDeadline = delDead.Format(time.RFC3339)
	s.ContainerType = cType
	s.TemperatureMinC = tMin
	s.TemperatureMaxC = tMax
	s.IncompatibleSampleTypes = incomp
	s.Serviceability = serv
	if actJId.Valid {
		s.ActiveJourneyId = &actJId.String
	}
	if targetLab.Valid {
		s.TargetLaboratoryId = &targetLab.String
	}
	if lat.Valid && lng.Valid {
		s.LatestLocation = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
	}
	if recAt.Valid {
		r := recAt.Time.Format(time.RFC3339)
		s.LocationRecordedAt = &r
		s.LocationStale = time.Since(recAt.Time) > 15*time.Minute
	} else {
		s.LocationStale = true
	}

	// Fetch active assignments
	lRows, err := db.Query("SELECT id FROM journey_legs WHERE sample_id = $1 AND status IN ('pending', 'offered', 'accepted', 'in_transit')", sampleId)
	if err == nil {
		defer lRows.Close()
		s.ActiveAssignmentIds = make([]string, 0)
		for lRows.Next() {
			var legId string
			if err := lRows.Scan(&legId); err == nil {
				s.ActiveAssignmentIds = append(s.ActiveAssignmentIds, legId)
			}
		}
	}

	s.Timeline, _ = GetSampleTimeline(db, sampleId)
	return &s, nil
}

func GetSampleLifecycle(db *sql.DB, sampleId string) (*models.SampleLifecycle, error) {
	var sl models.SampleLifecycle
	var actJId, currHold, recLab, pendHand sql.NullString
	var excJSON sql.NullString
	var lat, lng sql.NullFloat64
	var recAt sql.NullTime

	err := db.QueryRow(`
        SELECT id, status, sealed, active_journey_id, current_holder_id, received_laboratory_id, exception, pending_handoff_id, latest_latitude, latest_longitude, location_recorded_at
        FROM samples
        WHERE id = $1
    `, sampleId).Scan(
		&sl.SampleId, &sl.Status, &sl.Sealed, &actJId, &currHold, &recLab, &excJSON, &pendHand, &lat, &lng, &recAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrSampleNotFound
		}
		return nil, err
	}

	if actJId.Valid {
		sl.ActiveJourneyId = &actJId.String
	}
	if currHold.Valid {
		sl.CurrentHolderId = &currHold.String
	}
	if recLab.Valid {
		sl.ReceivedLaboratoryId = &recLab.String
	}
	if pendHand.Valid {
		sl.PendingHandoffId = &pendHand.String
		sl.PendingHandoff = map[string]interface{}{
			"handoffId": pendHand.String,
		}
	}
	if excJSON.Valid {
		_ = json.Unmarshal([]byte(excJSON.String), &sl.Exception)
	}
	if lat.Valid && lng.Valid {
		sl.LatestLocation = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
	}
	if recAt.Valid {
		r := recAt.Time.Format(time.RFC3339)
		sl.LocationRecordedAt = &r
		sl.LocationStale = time.Since(recAt.Time) > 15*time.Minute
	} else {
		sl.LocationStale = true
	}

	// Completed legs
	sl.CompletedLegIds = make([]string, 0)
	sl.ActiveReplacementPlanIds = make([]string, 0)

	clRows, err := db.Query("SELECT id FROM journey_legs WHERE sample_id = $1 AND status = 'completed'", sampleId)
	if err == nil {
		defer clRows.Close()
		for clRows.Next() {
			var legId string
			if err := clRows.Scan(&legId); err == nil {
				sl.CompletedLegIds = append(sl.CompletedLegIds, legId)
			}
		}
	}

	sl.Timeline, _ = GetSampleTimeline(db, sampleId)
	return &sl, nil
}

func ListRoleWork(db *sql.DB, user *models.User, role string, statusFilter string) (*models.RoleWork, error) {
	rw := &models.RoleWork{
		Pending:    make([]interface{}, 0),
		InProgress: make([]interface{}, 0),
		Completed:  make([]interface{}, 0),
	}

	switch role {
	case models.RoleRequester:
		rows, err := db.Query(`
            SELECT s.id, s.request_id, s.status, s.active_journey_id, s.target_laboratory_id, s.current_holder_id, s.latest_latitude, s.latest_longitude, s.location_recorded_at,
                   r.serviceability, r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at
            FROM samples s
            JOIN collection_requests r ON s.request_id = r.id
            WHERE s.requester_id = $1
            ORDER BY s.created_at DESC
        `, user.ID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sw models.SampleWorkItem
				sw.Kind = "sample"
				sw.RequesterId = &user.ID
				var jId, tLab, cHold sql.NullString
				var lat, lng sql.NullFloat64
				var recAt, reqAt, delDead, eColl, lColl sql.NullTime
				var serv sql.NullString

				if err := rows.Scan(&sw.SampleId, &sw.RequestId, &sw.Status, &jId, &tLab, &cHold, &lat, &lng, &recAt, &serv, &reqAt, &delDead, &eColl, &lColl); err == nil {
					sw.Sample_Id = sw.SampleId
					if jId.Valid {
						sw.JourneyId = &jId.String
						sw.ActiveJourneyId = &jId.String
					}
					if tLab.Valid {
						sw.LaboratoryId = &tLab.String
					}
					if cHold.Valid {
						sw.CurrentHolderId = &cHold.String
					}
					if serv.Valid {
						sw.Serviceability = &serv.String
					}
					if reqAt.Valid {
						r := reqAt.Time.Format(time.RFC3339)
						sw.RequestedAt = &r
					}
					if delDead.Valid {
						d := delDead.Time.Format(time.RFC3339)
						sw.DeliveryDeadline = &d
					}
					if eColl.Valid {
						e := eColl.Time.Format(time.RFC3339)
						sw.EarliestCollectionAt = &e
					}
					if lColl.Valid {
						l := lColl.Time.Format(time.RFC3339)
						sw.LatestCollectionAt = &l
					}
					if recAt.Valid {
						r := recAt.Time.Format(time.RFC3339)
						sw.LocationRecordedAt = &r
						sw.LocationStale = time.Since(recAt.Time) > 15*time.Minute
					} else {
						sw.LocationStale = true
					}
					sw.History, _ = GetSampleTimeline(db, sw.SampleId)

					if sw.Status == "requested" || sw.Status == "unserviceable" {
						rw.Pending = append(rw.Pending, sw)
					} else if sw.Status == "collected" || sw.Status == "in_transit" || sw.Status == "exception" {
						rw.InProgress = append(rw.InProgress, sw)
					} else if sw.Status == "received" || sw.Status == "completed" {
						rw.Completed = append(rw.Completed, sw)
					}
				}
			}
		}

	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		rows, err := db.Query(`
            SELECT id, journey_id, sample_id, sequence, status, from_location_id, to_location_id, kind, offer_expires_at
            FROM journey_legs
            WHERE worker_id = $1
            ORDER BY created_at DESC
        `, user.ID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aw models.AssignmentWorkItem
				var jId, sId, fromLoc, toLoc, offExp sql.NullString
				var seq sql.NullInt32

				if err := rows.Scan(&aw.AssignmentId, &jId, &sId, &seq, &aw.Status, &fromLoc, &toLoc, &aw.Kind, &offExp); err == nil {
					aw.Assignment_Id = aw.AssignmentId
					if jId.Valid {
						aw.JourneyId = &jId.String
					}
					if sId.Valid {
						aw.SampleId = sId.String
						aw.Sample_Id = sId.String
					}
					if fromLoc.Valid {
						aw.FromLocationId = &fromLoc.String
						aw.IncomingFromLocationId = &fromLoc.String
					}
					if toLoc.Valid {
						aw.ToLocationId = &toLoc.String
						aw.OutgoingToLocationId = &toLoc.String
					}
					if seq.Valid {
						sq := int(seq.Int32)
						aw.Sequence = &sq
					}
					if offExp.Valid {
						aw.OfferExpiresAt = &offExp.String
					}
					aw.History, _ = GetAssignmentTimeline(db, aw.AssignmentId)

					if aw.Status == "offered" || aw.Status == "pending" {
						rw.Pending = append(rw.Pending, aw)
					} else if aw.Status == "accepted" || aw.Status == "in_transit" {
						rw.InProgress = append(rw.InProgress, aw)
					} else if aw.Status == "completed" {
						rw.Completed = append(rw.Completed, aw)
					}
				}
			}
		}

	case models.RoleDispatcher, models.RoleAdministrator:
		// Dispatcher sees journeys
		rows, err := db.Query(`
            SELECT id, plan_version, route_mode, status, estimated_delivery_at, sample_ids
            FROM journeys
            ORDER BY created_at DESC
        `)
		if err == nil {
			defer rows.Close()
							for rows.Next() {
				var jw models.JourneyWorkItem
				jw.Kind = "journey"
				var estDel time.Time
				if err := rows.Scan(&jw.JourneyId, &jw.PlanVersion, &jw.RouteMode, &jw.Status, &estDel, pq.Array(&jw.SampleIds)); err == nil {
					jw.Journey_Id = jw.JourneyId
					jw.EstimatedDeliveryAt = estDel.Format(time.RFC3339)
					jw.History, _ = GetJourneyTimeline(db, jw.JourneyId)

					var legCount int
					_ = db.QueryRow("SELECT COUNT(*) FROM journey_legs WHERE journey_id = $1", jw.JourneyId).Scan(&legCount)
					jw.AssignmentCount = legCount

					if jw.Status == "active" || jw.Status == "pending" {
						rw.InProgress = append(rw.InProgress, jw)
					} else if jw.Status == "completed" || jw.Status == "merged" || jw.Status == "cancelled" {
						rw.Completed = append(rw.Completed, jw)
					} else {
						rw.Pending = append(rw.Pending, jw)
					}
				}
			}
		}
	}

	return rw, nil
}

